# SPDX-License-Identifier: Apache-2.0
"""Zing H3 DiT 4D Block-Sparse Attention and Single-Router-per-Chunk runtime.

Production Step C upgrades:
  1. Multi-Resolution Support (480p and 736p):
     - _StaticRouterWorkspace with dynamic (num_heads, max_m_q=48, max_m_cand=1280).
     - Dynamic BLOCK_N (512, 1024, 2048) in pack/shift and dual-pool reduction kernels.
     - Dynamic tokens_per_frame inference (390 for 480p, 920 for 736p).
     - Resolution-proportional budget scaling for M_cand > 460 preserving active KV ratio.
  2. Sequence Parallel Support (SP=1 H=56 and Ulysses SP=2 H=28):
     - Local head count H_local = 56 // sp_world_size.
     - Head sharding [head_start : head_start + H_local] where head_start = ulysses_rank * H_local.
     - Workspace, Triton kernels, and SDPA reference all support arbitrary H_local.
  3. Seamless DiT Runtime Integration:
     - Controlled via environment variables: SGLANG_ZING_SPARSE_ATTN_MODE and SGLANG_ZING_SPARSE_MIN_CHUNK.
     - Hooked directly into ZingH3DiTModel._fixed_block_attention via execute_fixed_block_sparse_branches.
     - Zero-router overhead reuse across joint branches (final_t1, source_t0, active_t1000).
     - Long-horizon accuracy protection: layer 0 dense, warmup chunks (u_cur < min_chunk) dense.
"""

from __future__ import annotations

import json
import math
import os
from dataclasses import dataclass
from typing import Any

import torch
import torch.nn.functional as F

try:
    import triton
    import triton.language as tl

    HAS_TRITON = True
except ImportError:
    triton = None
    tl = None
    HAS_TRITON = False

if not HAS_TRITON:

    class _DummyTriton:
        @staticmethod
        def jit(fn=None, **kwargs):
            if fn is None:
                return lambda f: f
            return fn

    triton = _DummyTriton()

    class _DummyTL:
        constexpr = Any

    tl = _DummyTL()

