_BLK_KIND_CACHE: dict[tuple[Any, ...], torch.Tensor] = {}
_RATIO_TENSOR_CACHE: dict[tuple[str, str], torch.Tensor] = {}
_LAST_STEP1_NUM_FULL: dict[tuple[int, int, int], tuple[int, torch.Tensor]] = {}


def _find_contiguous_spans(mask: torch.Tensor | list[bool]) -> list[tuple[int, int]]:
    """Return list of (start, stop) contiguous True spans."""
    if isinstance(mask, list):
        mask = torch.tensor(mask, dtype=torch.bool)
    if mask.numel() == 0:
        return []
    m = mask.bool().view(-1)
    padded = torch.cat(
        [
            torch.tensor([False], device=m.device),
            m,
            torch.tensor([False], device=m.device),
        ]
    )
    diff = torch.diff(padded.int())
    starts = (diff == 1).nonzero(as_tuple=False).view(-1).tolist()
    stops = (diff == -1).nonzero(as_tuple=False).view(-1).tolist()
    return list(zip(starts, stops))


def _infer_role4_spans_from_positions(pos: torch.Tensor) -> tuple[tuple[int, int], ...]:
    """Infer 2D VAE visual reference spans from [L_prefix, 3] position_ids.

    1D Qwen conditioning rows have unique pos[:, 0] with (h=0, w=0).
    2D VAE reference patches share duplicate pos[:, 0] across all H*W patches of each image.
    """
    pos_cpu = pos.cpu() if hasattr(pos, "cpu") else pos
    if pos_cpu.dim() != 2 or pos_cpu.shape[0] == 0 or pos_cpu.shape[1] < 3:
        return ()
    _, inv, counts = torch.unique(
        pos_cpu[:, 0], return_inverse=True, return_counts=True
    )
    mask = (counts[inv] > 1) | (pos_cpu[:, 1] != 0) | (pos_cpu[:, 2] != 0)
    return tuple(_find_contiguous_spans(mask))


def _get_blk_kind_gpu(
    device: torch.device,
    M_cand: int,
    M_prefix: int,
    blk_kind_sig: tuple[Any, ...] | None = None,
) -> torch.Tensor:
    """Return cached [M_cand] int8 block kind tensor on device."""
    key = (device, M_cand, M_prefix, blk_kind_sig)
    cached = _BLK_KIND_CACHE.get(key)
    if cached is not None:
        return cached

    kinds = [KIND_WIN_FIN] * M_cand
    if blk_kind_sig is None:
        for b in range(min(M_prefix, M_cand)):
            kinds[b] = KIND_REF_VIS
    else:
        # blk_kind_sig: (M_cand, role4_blk_spans, sink_blk_span, win_src_blk_spans)
        _, role4_spans, sink_span, win_src_spans = blk_kind_sig

        is_token_spans = False
        if role4_spans and any(e > M_cand for _, e in role4_spans):
            is_token_spans = True
        if sink_span:
            if (
                isinstance(sink_span, tuple)
                and len(sink_span) == 2
                and isinstance(sink_span[0], int)
            ):
                if sink_span[1] > M_cand:
                    is_token_spans = True
            elif (
                isinstance(sink_span, tuple)
                and len(sink_span) > 0
                and isinstance(sink_span[0], tuple)
            ):
                if any(e > M_cand for _, e in sink_span):
                    is_token_spans = True
        if win_src_spans and any(e > M_cand for _, e in win_src_spans):
            is_token_spans = True

        if is_token_spans:
            for b in range(M_cand):
                mid = b * BLOCK_SIZE + (BLOCK_SIZE // 2)
                if mid < M_prefix * BLOCK_SIZE:
                    if not role4_spans:
                        kinds[b] = KIND_REF_VIS
                    elif any(s <= mid < e for s, e in role4_spans):
                        kinds[b] = KIND_REF_VIS
                    else:
                        kinds[b] = KIND_TEXT
                else:
                    is_s = False
                    if sink_span:
                        if isinstance(sink_span[0], int):
                            is_s = sink_span[0] <= mid < sink_span[1]
                        else:
                            is_s = any(s <= mid < e for s, e in sink_span)
                    if is_s:
                        kinds[b] = KIND_SINK
                    elif win_src_spans and any(s <= mid < e for s, e in win_src_spans):
                        kinds[b] = KIND_WIN_SRC
                    else:
                        kinds[b] = KIND_WIN_FIN
        else:
            if not role4_spans:
                for b in range(min(M_prefix, M_cand)):
                    kinds[b] = KIND_REF_VIS
            else:
                for b in range(min(M_prefix, M_cand)):
                    kinds[b] = KIND_TEXT
                for s, e in role4_spans:
                    for b in range(max(0, s), min(M_cand, e)):
                        kinds[b] = KIND_REF_VIS
            if sink_span is not None:
                if len(sink_span) > 0 and isinstance(sink_span[0], tuple):
                    for s, e in sink_span:
                        for b in range(max(0, s), min(M_cand, e)):
                            kinds[b] = KIND_SINK
                elif len(sink_span) == 2 and isinstance(sink_span[0], int):
                    s, e = sink_span
                    for b in range(max(0, s), min(M_cand, e)):
                        kinds[b] = KIND_SINK
            if win_src_spans:
                for s, e in win_src_spans:
                    for b in range(max(0, s), min(M_cand, e)):
                        kinds[b] = KIND_WIN_SRC

    t = torch.tensor(kinds, dtype=torch.int8, device=device)
    if len(_BLK_KIND_CACHE) >= 4096:
        _BLK_KIND_CACHE.pop(next(iter(_BLK_KIND_CACHE)))
    _BLK_KIND_CACHE[key] = t
    return t


