def get_sparse_mode() -> str:
    """Return active sparse attention mode from environment: 'dense', 'sparse_095', or 'sparse_090'."""
    raw = os.environ.get("SGLANG_ZING_SPARSE_ATTN_MODE", "dense").strip().lower()
    if raw in ("", "dense", "off", "0", "false", "no", "none"):
        return "dense"
    if raw == "auto":
        return "sparse_095_triage"
    return raw


def set_sparse_mode(mode: str) -> None:
    """Set active sparse attention mode in environment."""
    os.environ["SGLANG_ZING_SPARSE_ATTN_MODE"] = str(mode)


def get_min_sparse_chunk() -> int:
    """Return minimum chunk index for sparse attention (earlier chunks run 100% dense)."""
    return int(
        os.environ.get("SGLANG_ZING_SPARSE_MIN_CHUNK", str(DEFAULT_MIN_SPARSE_CHUNK_ID))
    )


def set_min_sparse_chunk(chunk: int) -> None:
    """Set minimum chunk index for sparse attention."""
    os.environ["SGLANG_ZING_SPARSE_MIN_CHUNK"] = str(int(chunk))


def get_sparse_budget_tau(mode: str | None = None) -> str:
    """Resolve sparse budget tier tau ('0.95' or '0.90') from mode and SGLANG_ZING_SPARSE_BUDGET_SCALE."""
    m = (mode if mode is not None else get_sparse_mode()).strip().lower()
    if "090" in m or "0.90" in m:
        return "0.90"
    if "095" in m or "0.95" in m:
        return "0.95"
    env_scale = os.environ.get("SGLANG_ZING_SPARSE_BUDGET_SCALE", "").strip().lower()
    if env_scale:
        if "090" in env_scale or "0.90" in env_scale or env_scale == "0.9":
            return "0.90"
        if "095" in env_scale or "0.95" in env_scale:
            return "0.95"
        try:
            if float(env_scale) <= 0.925:
                return "0.90"
        except ValueError:
            pass
    return "0.95"


def is_three_tier_enabled(mode: str | None = None) -> bool:
    """Return True if Three-Tier All-FP8 (Refine / Skim / Skip) attention is enabled."""
    env_val = os.environ.get("SGLANG_ZING_SPARSE_THREE_TIER", "").strip().lower()
    if env_val in ("1", "true", "yes", "on"):
        return True
    if env_val in ("0", "false", "no", "off"):
        return False
    m = (mode if mode is not None else get_sparse_mode()).lower()
    return ("3tier" in m) or ("all_fp8" in m) or ("three_tier" in m)


def is_virtual_mean_enabled(mode: str | None = None) -> bool:
    """Return True if P0 Virtual Mean Tiles are enabled for skipped candidate blocks."""
    env_val = os.environ.get("SGLANG_ZING_SPARSE_VIRTUAL_MEAN", "").strip().lower()
    if env_val in ("1", "true", "yes", "on"):
        return True
    if env_val in ("0", "false", "no", "off"):
        return False
    m = (mode if mode is not None else get_sparse_mode()).lower()
    return ("triage" in m) or is_three_tier_enabled(m)


def is_triage_score_enabled(mode: str | None = None) -> bool:
    """Return True if P1 Triage second-order complexity routing is enabled."""
    env_val = os.environ.get("SGLANG_ZING_SPARSE_TRIAGE_SCORE", "").strip().lower()
    if env_val in ("1", "true", "yes", "on"):
        return True
    if env_val in ("0", "false", "no", "off"):
        return False
    m = (mode if mode is not None else get_sparse_mode()).lower()
    return ("triage" in m) or is_three_tier_enabled(m)


def get_sparse_price_pi(mode: str | None = None) -> float:
    """Return optional Top-K-free marginal gain price threshold pi (0.0 uses Theorem 4 quota-anchored S_(K)/c_rf)."""
    env_val = os.environ.get("SGLANG_ZING_SPARSE_PRICE_PI", "").strip()
    if env_val:
        try:
            return max(0.0, float(env_val))
        except ValueError:
            return 0.0
    return 0.0


def get_sparse_c_rf(mode: str | None = None) -> float:
    """Return Refine-vs-Skim effective cost ratio c_rf (default 12.0 = (64 / 4) * 0.75)."""
    env_val = os.environ.get("SGLANG_ZING_SPARSE_C_RF", "").strip()
    if env_val:
        try:
            return max(1.0, float(env_val))
        except ValueError:
            return 12.0
    return 12.0


def get_sparse_alpha_triage(mode: str | None = None) -> float:
    """Return Skim candidate fraction alpha_triage (default 0.22)."""
    env_val = os.environ.get("SGLANG_ZING_SPARSE_ALPHA_TRIAGE", "").strip()
    if env_val:
        try:
            return max(0.0, min(1.0, float(env_val)))
        except ValueError:
            return 0.22
    return 0.22


_LAST_3TIER_EXEC_META: dict[str, Any] = {}


@dataclass
class Frame2DSquarePartition:
    """Single-frame 2D near-square spatial partition metadata (SPEC Rev 7 Section 3.3)."""

    h_lat: int
    w_lat: int
    num_frames: int
    tokens_per_frame: int
    blocks_per_frame: int
    num_blocks: int
    perm: torch.Tensor
    inv_perm: torch.Tensor
    block_valid_len: torch.Tensor
    sub_valid_len: torch.Tensor
    block_frame_idx: torch.Tensor

    def __getitem__(self, key: str) -> Any:
        return getattr(self, key)

    def permute_tokens(self, x: torch.Tensor) -> torch.Tensor:
        """Permute leading token dimension of x from 1D raster order to 2D quadrant-major block order."""
        n_tok = int(x.shape[0])
        return x.index_select(0, self.perm[:n_tok].to(x.device))

    def unpermute_tokens(self, x: torch.Tensor) -> torch.Tensor:
        """Restore leading token dimension of x from 2D quadrant-major block order to 1D raster order."""
        n_tok = int(x.shape[0])
        return x.index_select(0, self.inv_perm[:n_tok].to(x.device))


def _quadrant_order_coords(coords: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Order 2D (row, col) coordinates into 4 spatial quadrants (top-left, top-right, bottom-left, bottom-right)."""
    if not coords:
        return []
    r_min = min(r for r, _ in coords)
    r_max = max(r for r, _ in coords)
    c_min = min(c for _, c in coords)
    c_max = max(c for _, c in coords)
    r_mid = r_min + min(4, max(1, (r_max - r_min + 2) // 2))
    c_mid = c_min + min(4, max(1, (c_max - c_min + 2) // 2))
    tl_q = sorted((r, c) for r, c in coords if r < r_mid and c < c_mid)
    tr_q = sorted((r, c) for r, c in coords if r < r_mid and c >= c_mid)
    bl_q = sorted((r, c) for r, c in coords if r >= r_mid and c < c_mid)
    br_q = sorted((r, c) for r, c in coords if r >= r_mid and c >= c_mid)
    return tl_q + tr_q + bl_q + br_q


def build_frame_2d_square_partition(
    h_lat: int,
    w_lat: int,
    num_frames: int = 1,
    *,
    device: torch.device | str = "cpu",
) -> Frame2DSquarePartition:
    """Build single-frame 2D near-square spatial partition with quadrant-major sub-block ordering (SPEC Rev 7 §3.3).

    - 736p (h_lat=23, w_lat=40, 920 tokens/frame):
      3 row strips [8, 8, 7] x 5 col strips [8, 8, 8, 8, 8] -> 15 blocks/frame:
      10 blocks of 8x8=64 tokens + 5 blocks of 7x8=56 tokens (sum=920).
    - 480p (h_lat=15, w_lat=26, 390 tokens/frame):
      Top strip (rows 0..7, 208 tokens) -> 4 compact blocks of [52, 52, 52, 52];
      Bottom strip (rows 8..14, 182 tokens) -> 3 compact blocks of [61, 61, 60]
      -> 7 blocks/frame (sum=390).
    """
    H_l = int(h_lat)
    W_l = int(w_lat)
    F_n = max(1, int(num_frames))
    dev = torch.device(device)
    tpf = H_l * W_l

    frame_blocks_coords: list[list[tuple[int, int]]] = []
    if H_l == 23 and W_l == 40:
        row_bounds = [(0, 8), (8, 16), (16, 23)]
        col_bounds = [(0, 8), (8, 16), (16, 24), (24, 32), (32, 40)]
        for r0, r1 in row_bounds:
            for c0, c1 in col_bounds:
                patch = [(r, c) for r in range(r0, r1) for c in range(c0, c1)]
                frame_blocks_coords.append(_quadrant_order_coords(patch))
    elif H_l == 15 and W_l == 26:
        # Top row strip (rows 0..7, 208 tokens): column-major stream split into 4 compact blocks of 52
        top_col_major = [(r, c) for c in range(26) for r in range(0, 8)]
        for b_i in range(4):
            patch = top_col_major[b_i * 52 : (b_i + 1) * 52]
            frame_blocks_coords.append(_quadrant_order_coords(patch))
        # Bottom row strip (rows 8..14, 182 tokens): column-major stream split into [61, 61, 60]
        bot_col_major = [(r, c) for c in range(26) for r in range(8, 15)]
        bot_splits = [(0, 61), (61, 122), (122, 182)]
        for s0, s1 in bot_splits:
            patch = bot_col_major[s0:s1]
            frame_blocks_coords.append(_quadrant_order_coords(patch))
    else:
        for r0 in range(0, H_l, 8):
            r1 = min(H_l, r0 + 8)
            for c0 in range(0, W_l, 8):
                c1 = min(W_l, c0 + 8)
                patch = [(r, c) for r in range(r0, r1) for c in range(c0, c1)]
                frame_blocks_coords.append(_quadrant_order_coords(patch))

    bpf = len(frame_blocks_coords)
    single_perm_list: list[int] = []
    single_valid_lens: list[int] = []
    single_sub_lens: list[list[int]] = []
    for patch_coords in frame_blocks_coords:
        n_v = len(patch_coords)
        single_valid_lens.append(n_v)
        single_sub_lens.append(
            [min(16, max(0, n_v - s_i * 16)) for s_i in range(SUB_PER_BLK)]
        )
        for r, c in patch_coords:
            single_perm_list.append(r * W_l + c)

    single_perm = torch.tensor(single_perm_list, dtype=torch.long, device=dev)
    frame_offsets = torch.arange(F_n, dtype=torch.long, device=dev)[:, None] * tpf
    perm = (frame_offsets + single_perm[None, :]).reshape(-1)
    inv_perm = torch.empty_like(perm)
    inv_perm[perm] = torch.arange(F_n * tpf, dtype=torch.long, device=dev)

    block_valid_len = torch.tensor(
        single_valid_lens, dtype=torch.int32, device=dev
    ).repeat(F_n)
    sub_valid_len = torch.tensor(single_sub_lens, dtype=torch.int32, device=dev).repeat(
        F_n, 1
    )
    block_frame_idx = torch.arange(
        F_n, dtype=torch.int32, device=dev
    ).repeat_interleave(bpf)

    return Frame2DSquarePartition(
        h_lat=H_l,
        w_lat=W_l,
        num_frames=F_n,
        tokens_per_frame=tpf,
        blocks_per_frame=bpf,
        num_blocks=F_n * bpf,
        perm=perm,
        inv_perm=inv_perm,
        block_valid_len=block_valid_len,
        sub_valid_len=sub_valid_len,
        block_frame_idx=block_frame_idx,
    )


def apply_temporal_rope_32d(
    x: torch.Tensor,
    delta_t: float | torch.Tensor,
    inv_freq: torch.Tensor | None = None,
    *,
    inverse: bool = False,
    theta: float = 10000.0,
) -> torch.Tensor:
    """Apply 32D temporal RoPE rotation R_t(±delta_t) on temporal channels [0..15, 48..63] of D=128."""
    try:
        from seedleap_kernels.ops.block_sparse_attention import (
            apply_temporal_rope_32d as _sk_apply_temporal_rope_32d,
        )

        return _sk_apply_temporal_rope_32d(
            x, delta_t, inv_freq=inv_freq, inverse=inverse, theta=theta
        )
    except Exception:
        pass

    D = x.shape[-1]
    assert D == 128, f"Expected D=128 for 32D temporal RoPE, got {D}"
    device = x.device
    if inv_freq is None:
        inv_freq = 1.0 / (
            theta ** (torch.arange(0, 16, dtype=torch.float32, device=device) / 16.0)
        )
    else:
        inv_freq = inv_freq.to(device=device, dtype=torch.float32)

    dt = (
        torch.as_tensor(delta_t, dtype=torch.float32, device=device)
        if not isinstance(delta_t, torch.Tensor)
        else delta_t.to(device=device, dtype=torch.float32)
    )
    if inverse:
        dt = -dt
    while dt.dim() < x.dim() - 1:
        dt = dt.unsqueeze(0)
    angles = dt.unsqueeze(-1) * inv_freq
    cos_t = torch.cos(angles)
    sin_t = torch.sin(angles)

    x_f = x.float()
    out = x_f.clone()
    x0 = x_f[..., 0:16].clone()
    x1 = x_f[..., 48:64].clone()
    out[..., 0:16] = x0 * cos_t - x1 * sin_t
    out[..., 48:64] = x0 * sin_t + x1 * cos_t
    return out.to(x.dtype)


def _quantize_fp8_with_scale(
    x: torch.Tensor,
    reduce_dims: tuple[int, ...] | None = None,
    fp8_max: float = 448.0,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Quantize tensor x to float8_e4m3fn with per-group FP32 scale."""
    xf = x.float()
    if reduce_dims is None:
        amax = xf.abs().max()
        scale = torch.clamp(amax / fp8_max, min=1e-8)
        x_fp8 = torch.clamp(xf / scale, -fp8_max, fp8_max).to(torch.float8_e4m3fn)
        return x_fp8, scale.to(torch.float32)
    amax = xf.abs().amax(dim=reduce_dims, keepdim=True)
    scale = torch.clamp(amax / fp8_max, min=1e-8)
    x_fp8 = torch.clamp(xf / scale, -fp8_max, fp8_max).to(torch.float8_e4m3fn)
    return x_fp8, scale.squeeze(reduce_dims).to(torch.float32)


class ZingCompressedKVStore:
    """Chunk-boundary aligned compressed resident KV cache (~18.21 KB/blk, -62.1% vs 48 KB/blk raw).

    Implements SPEC Rev 7 Section 3.3 & 3.4:
      - Chunk-boundary / intra-frame 2D square block splitting: each chunk starts at a fresh block
        index b, with block_valid_len[b] = N_b <= 64 and tail rows N_b..63 zero-padded so no block
        ever crosses a frame or chunk boundary.
      - Write-once de-meaned FP8 residuals: k_res_fp8 [M_cap, H, 64, 128] (row-major) and
        v_res_fp8 [M_cap, H, 128, 64] (V_colmajor).
      - Theorem 3 3D RoPE SO(2) homomorphism: on sliding-window shift delta_t, only k_blk_mean
        and k_sub_mean are rotated on the 32D temporal subspace [0..15, 48..63] and re-quantized
        to FP8 (640 B/blk), while historical 16 KB/blk FP8 residuals remain 100% untouched.
      - Theorem 4 Law of Total Variance decomposition: vectorized computation of tau_k_between,
        tau_k_within, and alpha_k = clamp(tau_k_within / tau_k, 0.05, 0.95).
    """

    def __init__(
        self,
        max_blocks: int,
        num_heads: int = NUM_HEADS,
        head_dim: int = HEAD_DIM,
        device: torch.device | str = "cpu",
    ):
        self.max_blocks = int(max_blocks)
        self.num_heads = int(num_heads)
        self.head_dim = int(head_dim)
        self.device = torch.device(device)
        M = self.max_blocks
        H = self.num_heads
        D = self.head_dim

        # 1. Phase 1 (Refine): de-meaned FP8 residuals (8,192 B + 8,192 B = 16,384 B/blk)
        self.k_res_fp8 = torch.zeros(
            (M, H, BLOCK_SIZE, D), dtype=torch.float8_e4m3fn, device=self.device
        )
        self.v_res_fp8 = torch.zeros(
            (M, H, D, BLOCK_SIZE), dtype=torch.float8_e4m3fn, device=self.device
        )
        self.k_res_scale = torch.ones((H, M), dtype=torch.float32, device=self.device)
        self.v_res_scale = torch.ones((H, M), dtype=torch.float32, device=self.device)

        # 2. BF16 block means (256 B + 256 B = 512 B/blk) for Refine DC & 32D RoPE shift
        self.k_blk_mean = torch.zeros(
            (H, M, D), dtype=torch.bfloat16, device=self.device
        )
        self.v_blk_mean = torch.zeros(
            (H, M, D), dtype=torch.bfloat16, device=self.device
        )

        # 3. Phase 2 (Skim): 1/16 sub-block FP8 means + scales (512 B + 512 B + 32 B = 1,056 B/blk)
        self.k_sub_mean_fp8 = torch.zeros(
            (H, M * SUB_PER_BLK, D), dtype=torch.float8_e4m3fn, device=self.device
        )
        self.v_sub_mean_fp8 = torch.zeros(
            (H, D, M * SUB_PER_BLK), dtype=torch.float8_e4m3fn, device=self.device
        )
        self.k_sub_scale = torch.ones(
            (H, M * SUB_PER_BLK), dtype=torch.float32, device=self.device
        )
        self.v_sub_scale = torch.ones(
            (H, M * SUB_PER_BLK), dtype=torch.float32, device=self.device
        )

        # 4. Phase 3 (Skip / Virtual Tile): 1/64 block FP8 means + scales (128 B + 128 B + 8 B = 264 B/blk)
        self.k_blk_mean_fp8 = torch.zeros(
            (H, M, D), dtype=torch.float8_e4m3fn, device=self.device
        )
        self.v_blk_mean_fp8 = torch.zeros(
            (H, D, M), dtype=torch.float8_e4m3fn, device=self.device
        )
        self.k_blk_scale = torch.ones((H, M), dtype=torch.float32, device=self.device)
        self.v_blk_scale = torch.ones((H, M), dtype=torch.float32, device=self.device)

        # 5. Second-order moments and chunk-boundary metadata
        self.tau_k = torch.zeros((H, M), dtype=torch.float32, device=self.device)
        self.rho_kv = torch.zeros((H, M), dtype=torch.float32, device=self.device)
        self.block_valid_len = torch.zeros((M,), dtype=torch.int32, device=self.device)
        self.block_delta_t = torch.zeros((M,), dtype=torch.float32, device=self.device)
        self.block_is_shifted = torch.zeros((M,), dtype=torch.bool, device=self.device)
        self.block_chunk_id = torch.full(
            (M,), -999, dtype=torch.int32, device=self.device
        )
        self._router_stats: dict[str, torch.Tensor] = {
            "tau_k_between": torch.zeros(
                (H, M), dtype=torch.float32, device=self.device
            ),
            "tau_k_within": torch.zeros(
                (H, M), dtype=torch.float32, device=self.device
            ),
            "alpha_k": torch.full((H, M), 0.5, dtype=torch.float32, device=self.device),
        }
        self.num_blocks = 0
        self.window_delta_t = 0.0

    @property
    def tau_k_between(self) -> torch.Tensor:
        return self._router_stats["tau_k_between"]

    @property
    def tau_k_within(self) -> torch.Tensor:
        return self._router_stats["tau_k_within"]

    @property
    def alpha_k(self) -> torch.Tensor:
        return self._router_stats["alpha_k"]

    def allocated_bytes(self) -> int:
        """Return total allocated resident bytes for this layer's compressed store."""
        tensors = [
            getattr(self, "k_res_fp8", None),
            getattr(self, "v_res_fp8", None),
            getattr(self, "k_res_scale", None),
            getattr(self, "v_res_scale", None),
            getattr(self, "k_blk_mean", None),
            getattr(self, "v_blk_mean", None),
            getattr(self, "k_sub_mean_fp8", None),
            getattr(self, "v_sub_mean_fp8", None),
            getattr(self, "k_sub_scale", None),
            getattr(self, "v_sub_scale", None),
            getattr(self, "k_blk_mean_fp8", None),
            getattr(self, "v_blk_mean_fp8", None),
            getattr(self, "k_blk_scale", None),
            getattr(self, "v_blk_scale", None),
            getattr(self, "tau_k", None),
            getattr(self, "rho_kv", None),
            getattr(self, "block_valid_len", None),
            getattr(self, "block_delta_t", None),
            getattr(self, "block_is_shifted", None),
            getattr(self, "block_chunk_id", None),
        ]
        stats = getattr(self, "_router_stats", {})
        tensors.extend(stats.values())
        return sum(
            t.untyped_storage().nbytes()
            for t in tensors
            if t is not None and hasattr(t, "untyped_storage")
        )

    @staticmethod
    def bytes_per_block_per_head() -> int:
        """Return exact resident byte footprint per (block, head) matching allocated tensors (18,245 B = 17.82 KiB)."""
        return (
            8192  # k_res_fp8 [64, 128] FP8
            + 8192  # v_res_fp8 [128, 64] FP8 (V_colmajor)
            + 8  # k_res_scale + v_res_scale [1] FP32 each
            + 256  # k_blk_mean [128] BF16 (Refine DC & 32D temporal RoPE shift)
            + 256  # v_blk_mean [128] BF16 (Refine DC)
            + 512  # k_sub_mean_fp8 [4, 128] FP8
            + 512  # v_sub_mean_fp8 [128, 4] FP8 (V_colmajor)
            + 32  # k_sub_scale + v_sub_scale [4] FP32 each
            + 128  # k_blk_mean_fp8 [128] FP8
            + 128  # v_blk_mean_fp8 [128, 1] FP8 (V_colmajor)
            + 8  # k_blk_scale + v_blk_scale [1] FP32 each
            + 8  # tau_k + rho_kv [1] FP32 each
            + 13  # valid length, delta and chunk ID (4 B each), shifted flag (1 B)
        )

    def clear(self) -> None:
        """Reset logical block count without reallocating resident buffers."""
        self.num_blocks = 0
        self.window_delta_t = 0.0
        self.block_valid_len.zero_()
        self.block_delta_t.zero_()
        self.block_is_shifted.zero_()
        self.block_chunk_id.fill_(-999)
        self._router_stats["tau_k_between"].zero_()
        self._router_stats["tau_k_within"].zero_()
        self._router_stats["alpha_k"].fill_(0.5)

    def retain_prefix_blocks(self, count: int) -> None:
        """Retire dynamic blocks without requantizing the immutable prefix.

        A source block can share the prefix's chunk ID, so a resident prefix
        reset must use the boundary recorded at prefix publication, not IDs.
        All graph-visible allocations and retained bytes keep their identity.
        """
        if type(count) is not int or not 0 < count <= self.num_blocks:
            raise ValueError("Invalid compressed prefix boundary")
        self.block_chunk_id[count:].fill_(-999)
        self.block_valid_len[count:].zero_()
        self.block_delta_t[count:].zero_()
        self.block_is_shifted[count:].zero_()
        self.num_blocks = count
        self.window_delta_t = 0.0

    def compact_retained_chunks(self, valid_chunk_ids: set[int] | list[int]) -> int:
        """In-place compaction of retained blocks belonging to valid_chunk_ids.

        Zero raw16 reliance: all tensors (FP8 residuals, BF16 block means, sub-block FP8 means,
        scales, and metadata) are compacted in-place without reallocation, strictly preserving
        underlying data_ptr() for zero-recapture CUDA Graph replay.
        """
        if self.num_blocks == 0:
            return 0
        if not isinstance(valid_chunk_ids, set):
            valid_chunk_ids = set(valid_chunk_ids)

        cids = self.block_chunk_id[: self.num_blocks].cpu().tolist()
        keep_blks = [b for b, cid in enumerate(cids) if cid in valid_chunk_ids]
        return self.compact_blocks(keep_blks)

    def compact_blocks(self, keep_blks: list[int]) -> int:
        """Apply an owner-validated host compaction map, preserving allocations."""
        if keep_blks != sorted(set(keep_blks)) or any(
            type(b) is not int or not 0 <= b < self.num_blocks for b in keep_blks
        ):
            raise ValueError("Invalid compressed KV compaction map")
        K = len(keep_blks)
        if K == self.num_blocks and keep_blks == list(range(self.num_blocks)):
            return K
        if K == 0:
            self.clear()
            return 0

        keep_idx = torch.tensor(keep_blks, dtype=torch.long, device=self.device)

        # 1. Block-level tensors copy
        self.k_res_fp8.view(torch.uint8)[:K].copy_(
            self.k_res_fp8.view(torch.uint8)[keep_idx]
        )
        self.v_res_fp8.view(torch.uint8)[:K].copy_(
            self.v_res_fp8.view(torch.uint8)[keep_idx]
        )
        self.k_res_scale[:, :K].copy_(self.k_res_scale[:, keep_idx])
        self.v_res_scale[:, :K].copy_(self.v_res_scale[:, keep_idx])

        self.k_blk_mean[:, :K, :].copy_(self.k_blk_mean[:, keep_idx, :])
        self.v_blk_mean[:, :K, :].copy_(self.v_blk_mean[:, keep_idx, :])

        self.k_blk_mean_fp8.view(torch.uint8)[:, :K, :].copy_(
            self.k_blk_mean_fp8.view(torch.uint8)[:, keep_idx, :]
        )
        self.v_blk_mean_fp8.view(torch.uint8)[:, :, :K].copy_(
            self.v_blk_mean_fp8.view(torch.uint8)[:, :, keep_idx]
        )
        self.k_blk_scale[:, :K].copy_(self.k_blk_scale[:, keep_idx])
        self.v_blk_scale[:, :K].copy_(self.v_blk_scale[:, keep_idx])

        self.tau_k[:, :K].copy_(self.tau_k[:, keep_idx])
        self.rho_kv[:, :K].copy_(self.rho_kv[:, keep_idx])
        self.block_valid_len[:K].copy_(self.block_valid_len[keep_idx])
        self.block_delta_t[:K].copy_(self.block_delta_t[keep_idx])
        self.block_is_shifted[:K].copy_(self.block_is_shifted[keep_idx])
        self.block_chunk_id[:K].copy_(self.block_chunk_id[keep_idx])

        self._router_stats["tau_k_between"][:, :K].copy_(
            self._router_stats["tau_k_between"][:, keep_idx]
        )
        self._router_stats["tau_k_within"][:, :K].copy_(
            self._router_stats["tau_k_within"][:, keep_idx]
        )
        self._router_stats["alpha_k"][:, :K].copy_(
            self._router_stats["alpha_k"][:, keep_idx]
        )

        # 2. Sub-block level tensors copy (SUB_PER_BLK = 4)
        sub_keep_list = []
        for b in keep_blks:
            sub_keep_list.extend(range(b * SUB_PER_BLK, (b + 1) * SUB_PER_BLK))
        sub_keep_idx = torch.tensor(sub_keep_list, dtype=torch.long, device=self.device)
        K_sub = K * SUB_PER_BLK

        self.k_sub_mean_fp8.view(torch.uint8)[:, :K_sub, :].copy_(
            self.k_sub_mean_fp8.view(torch.uint8)[:, sub_keep_idx, :]
        )
        self.v_sub_mean_fp8.view(torch.uint8)[:, :, :K_sub].copy_(
            self.v_sub_mean_fp8.view(torch.uint8)[:, :, sub_keep_idx]
        )
        self.k_sub_scale[:, :K_sub].copy_(self.k_sub_scale[:, sub_keep_idx])
        self.v_sub_scale[:, :K_sub].copy_(self.v_sub_scale[:, sub_keep_idx])

        # 3. Clear vacated tail slots
        self.block_chunk_id[K:].fill_(-999)
        self.block_valid_len[K:].zero_()
        self.block_delta_t[K:].zero_()
        self.block_is_shifted[K:].zero_()

        self.num_blocks = K
        return K

    def append_chunk(
        self,
        k_chunk: torch.Tensor,
        v_chunk: torch.Tensor,
        *,
        chunk_id: int = 0,
        block_valid_lengths: list[int] | torch.Tensor | None = None,
        block_start: int | None = None,
        publish: bool = True,
    ) -> tuple[int, int]:
        """Vectorized append of one chunk [L_chunk, H, D] aligned to fresh block boundary [b_start, b_end).

        When `block_valid_lengths` is provided, `k_chunk` and `v_chunk` are compactly concatenated
        along dim 0 with `L_chunk == sum(block_valid_lengths)` (matching `Frame2DSquarePartition.permute_tokens`).
        """
        L_c, H, D = k_chunk.shape
        assert H == self.num_heads and D == self.head_dim
        if L_c == 0:
            return self.num_blocks, self.num_blocks

        if block_valid_lengths is None:
            n_blks = (L_c + BLOCK_SIZE - 1) // BLOCK_SIZE
            blk_idx_local = torch.arange(n_blks, dtype=torch.int32, device=self.device)
            valid_lens = torch.clamp(
                L_c - blk_idx_local * BLOCK_SIZE, min=1, max=BLOCK_SIZE
            )
        else:
            if isinstance(block_valid_lengths, torch.Tensor):
                valid_lens = block_valid_lengths.to(
                    device=self.device, dtype=torch.int32
                ).view(-1)
            else:
                valid_lens = torch.tensor(
                    list(block_valid_lengths), dtype=torch.int32, device=self.device
                )
            n_blks = int(valid_lens.numel())
            if n_blks == 0:
                return self.num_blocks, self.num_blocks

        b_start = self.num_blocks if block_start is None else block_start
        if type(b_start) is not int or b_start < 0:
            raise ValueError("Invalid compressed KV write offset")
        b_end = b_start + n_blks
        if b_end > self.max_blocks:
            raise RuntimeError(
                f"ZingCompressedKVStore capacity exceeded: {b_end} > {self.max_blocks}"
            )

        self.block_valid_len[b_start:b_end] = valid_lens
        self.block_chunk_id[b_start:b_end] = (
            chunk_id if isinstance(chunk_id, torch.Tensor) else int(chunk_id)
        )
        self.block_is_shifted[b_start:b_end] = 0
        self.block_delta_t[b_start:b_end] = 0.0

        s_tok = torch.cumsum(valid_lens.to(torch.long), dim=0) - valid_lens.to(
            torch.long
        )
        r_offs = torch.arange(BLOCK_SIZE, dtype=torch.long, device=self.device)
        tok_idx = (s_tok[:, None] + r_offs[None, :]).clamp(max=max(0, L_c - 1))
        valid_mask = (
            r_offs[None, :] < valid_lens.to(torch.long)[:, None]
        )  # [n_blks, 64]
        mask_4d = valid_mask[None, :, :, None]  # [1, n_blks, 64, 1]

        k_blk = k_chunk[tok_idx].float().permute(2, 0, 1, 3)  # [H, n_blks, 64, D]
        v_blk = v_chunk[tok_idx].float().permute(2, 0, 1, 3)  # [H, n_blks, 64, D]
        k_masked = torch.where(mask_4d, k_blk, 0.0)
        v_masked = torch.where(mask_4d, v_blk, 0.0)

        n_val_f = valid_lens.float().clamp_min(1.0)[None, :, None]  # [1, n_blks, 1]
        km = k_masked.sum(dim=2) / n_val_f  # [H, n_blks, D]
        vm = v_masked.sum(dim=2) / n_val_f  # [H, n_blks, D]
        self.k_blk_mean[:, b_start:b_end, :] = km.to(torch.bfloat16)
        self.v_blk_mean[:, b_start:b_end, :] = vm.to(torch.bfloat16)

        km_fp8, km_sc = _quantize_fp8_with_scale(km, reduce_dims=(-1,))
        vm_fp8, vm_sc = _quantize_fp8_with_scale(vm, reduce_dims=(-1,))
        self.k_blk_mean_fp8[:, b_start:b_end, :] = km_fp8
        self.v_blk_mean_fp8[:, :, b_start:b_end] = vm_fp8.transpose(1, 2).contiguous()
        self.k_blk_scale[:, b_start:b_end] = km_sc
        self.v_blk_scale[:, b_start:b_end] = vm_sc

        dk_full = torch.where(mask_4d, k_blk - km.unsqueeze(2), 0.0)
        dv_full = torch.where(mask_4d, v_blk - vm.unsqueeze(2), 0.0)
        dk_fp8, dk_sc = _quantize_fp8_with_scale(dk_full, reduce_dims=(2, 3))
        dv_fp8, dv_sc = _quantize_fp8_with_scale(dv_full, reduce_dims=(2, 3))
        self.k_res_fp8[b_start:b_end] = dk_fp8.transpose(0, 1).contiguous()
        self.v_res_fp8[b_start:b_end] = dv_fp8.permute(1, 0, 3, 2).contiguous()
        self.k_res_scale[:, b_start:b_end] = dk_sc
        self.v_res_scale[:, b_start:b_end] = dv_sc

        # Second-order moments over valid rows
        n_val_2d = valid_lens.float().clamp_min(1.0)[None, :]  # [1, n_blks]
        dk_sq = (dk_full * dk_full).sum(dim=-1)  # [H, n_blks, 64]
        dv_sq = (dv_full * dv_full).sum(dim=-1)  # [H, n_blks, 64]
        tr_sigma_k = dk_sq.sum(dim=-1) / n_val_2d
        tr_sigma_v = dv_sq.sum(dim=-1) / n_val_2d
        tk_tot = tr_sigma_k / (2.0 * float(D))
        self.tau_k[:, b_start:b_end] = tk_tot

        cross_row = torch.where(
            valid_mask[None, :, :],
            torch.sqrt(dk_sq + 1e-12) * torch.sqrt(dv_sq + 1e-12),
            0.0,
        )
        cross_kv = cross_row.sum(dim=-1) / n_val_2d
        v_mean_norm = torch.sqrt((vm * vm).sum(dim=-1) + 1e-12)
        sigma_v = torch.sqrt(tr_sigma_v + 1e-12)
        self.rho_kv[:, b_start:b_end] = cross_kv / (
            float(D) * (v_mean_norm + sigma_v + 1e-5)
        )

        # Vectorized 4-sub-block means & Theorem 4 Law of Total Variance decomposition
        k_sub_5d = k_masked.view(H, n_blks, SUB_PER_BLK, SUB_BLOCK_SIZE, D)
        v_sub_5d = v_masked.view(H, n_blks, SUB_PER_BLK, SUB_BLOCK_SIZE, D)
        sub_mask_3d = valid_mask.view(n_blks, SUB_PER_BLK, SUB_BLOCK_SIZE)
        sub_cnt = sub_mask_3d.sum(dim=-1)  # [n_blks, 4]
        sub_cnt_f = sub_cnt.float().clamp_min(1.0)[None, :, :, None]
        sub_nonempty = (sub_cnt > 0)[None, :, :, None]

        ks = torch.where(sub_nonempty, k_sub_5d.sum(dim=3) / sub_cnt_f, 0.0)
        vs = torch.where(sub_nonempty, v_sub_5d.sum(dim=3) / sub_cnt_f, 0.0)

        ks_flat = ks.reshape(H, n_blks * SUB_PER_BLK, D)
        vs_flat = vs.reshape(H, n_blks * SUB_PER_BLK, D)
        ks_fp8, ks_sc = _quantize_fp8_with_scale(ks_flat, reduce_dims=(-1,))
        vs_fp8, vs_sc = _quantize_fp8_with_scale(vs_flat, reduce_dims=(-1,))
        g_start = b_start * SUB_PER_BLK
        g_end = b_end * SUB_PER_BLK
        self.k_sub_mean_fp8[:, g_start:g_end, :] = ks_fp8
        self.v_sub_mean_fp8[:, :, g_start:g_end] = vs_fp8.transpose(1, 2).contiguous()
        self.k_sub_scale[:, g_start:g_end] = ks_sc
        self.v_sub_scale[:, g_start:g_end] = vs_sc

        # Exact weighted Law of Total Variance: tau_k = tau_k_between + tau_k_within
        sub_weights = (
            sub_cnt.float()[None, :, :] / n_val_2d[:, :, None]
        )  # [1, n_blks, 4]
        dk_between_sq = ((ks - km.unsqueeze(2)) ** 2).sum(dim=-1)  # [H, n_blks, 4]
        tk_between = (dk_between_sq * sub_weights).sum(dim=-1) / (2.0 * float(D))

        dk_within = torch.where(
            sub_mask_3d[None, :, :, :, None], k_sub_5d - ks.unsqueeze(3), 0.0
        )
        dk_within_sq = (dk_within * dk_within).sum(dim=(-2, -1))  # [H, n_blks, 4]
        tk_within = dk_within_sq.sum(dim=-1) / (2.0 * float(D) * n_val_2d)
        alpha_blk = ((tk_within + 0.95e-5) / (tk_tot + 1.0e-5)).clamp(0.05, 0.95)

        self._router_stats["tau_k_between"][:, b_start:b_end] = tk_between
        self._router_stats["tau_k_within"][:, b_start:b_end] = tk_within
        self._router_stats["alpha_k"][:, b_start:b_end] = alpha_blk

        if publish:
            self.num_blocks = b_end
        return b_start, b_end

    def apply_window_shift(
        self,
        block_indices: list[int] | torch.Tensor,
        delta_t: float,
    ) -> None:
        """Vectorized incremental 32D temporal RoPE rotation on k_blk_mean & k_sub_mean_fp8."""
        if isinstance(block_indices, torch.Tensor):
            if block_indices.numel() == 0:
                return
            idx_t = block_indices.to(device=self.device, dtype=torch.long).view(-1)
        else:
            if not block_indices:
                return
            idx_t = torch.tensor(
                [int(x) for x in block_indices], dtype=torch.long, device=self.device
            )

        # Rotate BF16 block means and re-quantize FP8 block means
        km_rot = apply_temporal_rope_32d(self.k_blk_mean[:, idx_t, :], delta_t)
        self.k_blk_mean[:, idx_t, :] = km_rot.to(torch.bfloat16)
        km_fp8, km_sc = _quantize_fp8_with_scale(km_rot, reduce_dims=(-1,))
        self.k_blk_mean_fp8.view(torch.uint8)[:, idx_t, :] = km_fp8.view(torch.uint8)
        self.k_blk_scale[:, idx_t] = km_sc

        # Vectorized rotation of all 4 sub-block means per shifted block
        # (use uint8 view for advanced indexing compatibility on CPU PyTorch 2.6)
        g_sub_t = (
            idx_t[:, None] * SUB_PER_BLK
            + torch.arange(SUB_PER_BLK, dtype=torch.long, device=self.device)[None, :]
        ).reshape(-1)
        ks_deq = self.k_sub_mean_fp8.view(torch.uint8)[:, g_sub_t, :].view(
            self.k_sub_mean_fp8.dtype
        ).float() * self.k_sub_scale[:, g_sub_t].unsqueeze(-1)
        ks_rot = apply_temporal_rope_32d(ks_deq, delta_t)
        ks_fp8, ks_sc = _quantize_fp8_with_scale(ks_rot, reduce_dims=(-1,))
        self.k_sub_mean_fp8.view(torch.uint8)[:, g_sub_t, :] = ks_fp8.view(torch.uint8)
        self.k_sub_scale[:, g_sub_t] = ks_sc

        self.block_is_shifted[idx_t] = 1
        self.block_delta_t[idx_t] = self.block_delta_t[idx_t] + float(delta_t)
        self.window_delta_t = float(delta_t)

    def as_kernel_dict(self, num_blocks: int | None = None) -> dict[str, torch.Tensor]:
        """Return sliced dictionary matching seedleap_kernels compressed_kv operator contract."""
        M = (
            self.num_blocks
            if num_blocks is None
            else min(self.max_blocks, max(self.num_blocks, int(num_blocks)))
        )
        M_sub = M * SUB_PER_BLK
        return {
            "k_res_fp8": self.k_res_fp8[:M],
            "v_res_fp8": self.v_res_fp8[:M],
            "k_res_scale": self.k_res_scale[:, :M],
            "v_res_scale": self.v_res_scale[:, :M],
            "k_scale": self.k_res_scale[:, :M],
            "v_scale": self.v_res_scale[:, :M],
            "k_blk_mean": self.k_blk_mean[:, :M, :],
            "v_blk_mean": self.v_blk_mean[:, :M, :],
            "k_blk_mean_fp8": self.k_blk_mean_fp8[:, :M, :],
            "v_blk_mean_fp8": self.v_blk_mean_fp8[:, :, :M],
            "k_blk_scale": self.k_blk_scale[:, :M],
            "v_blk_scale": self.v_blk_scale[:, :M],
            "k_sub_mean_fp8": self.k_sub_mean_fp8[:, :M_sub, :],
            "v_sub_mean_fp8": self.v_sub_mean_fp8[:, :, :M_sub],
            "k_sub_scale": self.k_sub_scale[:, :M_sub],
            "v_sub_scale": self.v_sub_scale[:, :M_sub],
            "tau_k": self.tau_k[:, :M],
            "tau_k_between": self._router_stats["tau_k_between"][:, :M],
            "tau_k_within": self._router_stats["tau_k_within"][:, :M],
            "alpha_k": self._router_stats["alpha_k"][:, :M],
            "rho_kv": self.rho_kv[:, :M],
            "block_valid_len": self.block_valid_len[:M],
            "block_is_shifted": self.block_is_shifted[:M],
        }


def infer_tokens_per_frame(L_q: int) -> int:
    """Infer tokens per frame dynamically from query length L_q."""
    if L_q in (390, 780, 1170):
        return 390
    if L_q in (920, 1840, 2760):
        return 920
    if L_q % 390 == 0 and L_q > 0:
        return 390
    if L_q % 920 == 0 and L_q > 0:
        return 920
    return max(1, L_q // 2)


def compute_min_exempt_tail(L_q: int, tokens_per_frame: int | None = None) -> int:
    """Compute tail exemption threshold: max(L_q, 2 * tokens_per_frame)."""
    tpf = infer_tokens_per_frame(L_q) if tokens_per_frame is None else tokens_per_frame
    return max(L_q, 2 * tpf)


def compute_seg_prefix_fallback(
    total_kv: int, L_q: int, tokens_per_frame: int | None = None
) -> int:
    """Compute fallback prefix protection length: min(15 * tokens_per_frame, total_kv // 3)."""
    tpf = infer_tokens_per_frame(L_q) if tokens_per_frame is None else tokens_per_frame
    return min(15 * tpf, total_kv // 3)


def scale_budget_k(K_h: int, M_cand: int, M_cand_ref: float = 434.0) -> int:
    """Proportionally scale 480p-calibrated budget K_h when M_cand > 460 (e.g. 736p)."""
    if M_cand > 460:
        return min(M_cand, max(8, int(math.ceil(K_h * (M_cand / M_cand_ref)))))
    return min(M_cand, max(8, K_h))


def get_zing_h3_head_budget_table(
    tau: str = "0.95",
    *,
    head_start: int = 0,
    num_heads: int = 56,
    m_cand: int | None = None,
    m_cand_scale: float | None = None,
) -> list[list[int]]:
    """Return 50-layer budget table sliced to [head_start : head_start + num_heads] with optional scaling."""
    base_table = (
        _BUDGET_TABLE_090_LIST
        if ("090" in tau or "0.90" in tau)
        else _BUDGET_TABLE_095_LIST
    )
    table_out: list[list[int]] = []

    for row in base_table:
        head_slice = row[head_start : head_start + num_heads]
        if m_cand is not None:
            scaled_row = [scale_budget_k(kh, m_cand) for kh in head_slice]
        elif m_cand_scale is not None and m_cand_scale > 1.05:
            scaled_row = [
                max(8, int(math.ceil(kh * m_cand_scale))) for kh in head_slice
            ]
        else:
            scaled_row = list(head_slice)
        table_out.append(scaled_row)
    return table_out


@triton.jit
def _zing_subblock16_pool_q_pair_kernel(
    Q_src,
    Q_act,
    Q_sub_out,  # [H, n_mult * M_q_sub, D]
    Q_norm_out,  # [H, n_mult * M_q_sub]
    stride_qsm,
    stride_qsh,
    stride_qsd,
    stride_qam,
    stride_qah,
    stride_qad,
    stride_osh,
    stride_osm,
    stride_osd,
    stride_nsh,
    stride_nsm,
    L_q,
    M_q_sub,
    HAS_PAIR: tl.constexpr,
    HEAD_DIM: tl.constexpr,
):
    pid_s = tl.program_id(0)  # 0 .. M_q_sub - 1
    pid_h = tl.program_id(1)  # 0 .. H - 1

    offs_r = pid_s * 16 + tl.arange(0, 16)
    clamped_r = tl.minimum(offs_r, L_q - 1)
    offs_d = tl.arange(0, HEAD_DIM)

    qs_ptrs = (
        Q_src
        + clamped_r[:, None] * stride_qsm
        + pid_h * stride_qsh
        + offs_d[None, :] * stride_qsd
    )
    qs = tl.load(qs_ptrs).to(tl.float32)
    qs_mean_f32 = tl.sum(qs, axis=0) * (1.0 / 16.0)
    qs_mean = qs_mean_f32.to(tl.bfloat16)

    out_s_ptrs = (
        Q_sub_out + pid_h * stride_osh + pid_s * stride_osm + offs_d * stride_osd
    )
    tl.store(out_s_ptrs, qs_mean)

    qs_norm = tl.rsqrt(tl.sum(qs_mean_f32 * qs_mean_f32, axis=0) + 1e-6)
    tl.store(Q_norm_out + pid_h * stride_nsh + pid_s * stride_nsm, qs_norm)

    if HAS_PAIR:
        qa_ptrs = (
            Q_act
            + clamped_r[:, None] * stride_qam
            + pid_h * stride_qah
            + offs_d[None, :] * stride_qad
        )
        qa = tl.load(qa_ptrs).to(tl.float32)
        qa_mean_f32 = tl.sum(qa, axis=0) * (1.0 / 16.0)
        qa_mean = qa_mean_f32.to(tl.bfloat16)
        out_a_ptrs = (
            Q_sub_out
            + pid_h * stride_osh
            + (M_q_sub + pid_s) * stride_osm
            + offs_d * stride_osd
        )
        tl.store(out_a_ptrs, qa_mean)

        qa_norm = tl.rsqrt(tl.sum(qa_mean_f32 * qa_mean_f32, axis=0) + 1e-6)
        tl.store(
            Q_norm_out + pid_h * stride_nsh + (M_q_sub + pid_s) * stride_nsm, qa_norm
        )


@triton.jit
def _zing_subblock16_pool_k_kernel(
    K,
    K_sub_out,  # [H, M_cand_sub, D]
    K_norm_out,  # [H, M_cand_sub]
    Meta_ptr,  # Optional int32 [32]
    stride_kn,
    stride_kh,
    stride_kd,
    stride_okh,
    stride_okn,
    stride_okd,
    stride_nkh,
    stride_nkn,
    M_cand_fallback,
    HAS_META_PTR: tl.constexpr,
    HEAD_DIM: tl.constexpr,
    SUB_SAMPLES: tl.constexpr,
    SUB_STEP: tl.constexpr,
):
    pid_s = tl.program_id(0)  # 0 .. M_cand_sub_cap - 1
    pid_h = tl.program_id(1)  # 0 .. H - 1

    m_cand = tl.load(Meta_ptr + 0) if HAS_META_PTR else M_cand_fallback
    if pid_s >= m_cand * 4:
        return

    offs_r = pid_s * 16 + tl.arange(0, SUB_SAMPLES) * SUB_STEP
    offs_d = tl.arange(0, HEAD_DIM)

    k_ptrs = (
        K
        + offs_r[:, None] * stride_kn
        + pid_h * stride_kh
        + offs_d[None, :] * stride_kd
    )
    k_val = tl.load(k_ptrs).to(tl.float32)
    k_mean_f32 = tl.sum(k_val, axis=0) * (1.0 / SUB_SAMPLES)
    k_mean = k_mean_f32.to(tl.bfloat16)

    out_ptrs = K_sub_out + pid_h * stride_okh + pid_s * stride_okn + offs_d * stride_okd
    tl.store(out_ptrs, k_mean)

    k_norm = tl.rsqrt(tl.sum(k_mean_f32 * k_mean_f32, axis=0) + 1e-6)
    tl.store(K_norm_out + pid_h * stride_nkh + pid_s * stride_nkn, k_norm)


@triton.jit
def _zing_kv_block_stats_kernel(
    K_ptr,
    V_ptr,
    K_mean_ptr,  # [H, M_cand_cap, D] bf16
    V_mean_ptr,  # [H, M_cand_cap, D] bf16
    Tau_k_ptr,  # [H, M_cand_cap] float32
    Rho_kv_ptr,  # [H, M_cand_cap] float32
    Meta_m_cand_ptr,  # Optional int32 scalar pointer to M_cand
    stride_kn,
    stride_kh,
    stride_kd,
    stride_vn,
    stride_vh,
    stride_vd,
    stride_km_h,
    stride_km_b,
    stride_km_d,
    stride_vm_h,
    stride_vm_b,
    stride_vm_d,
    stride_tk_h,
    stride_tk_b,
    stride_rk_h,
    stride_rk_b,
    start_block,
    M_cand_fallback,
    K_cap,
    HAS_META_PTR: tl.constexpr,
    HEAD_DIM: tl.constexpr,
):
    pid_b = start_block + tl.program_id(0)  # start_block .. M_cand_cap - 1
    pid_h = tl.program_id(1)  # 0 .. H - 1

    m_cand = tl.load(Meta_m_cand_ptr) if HAS_META_PTR else M_cand_fallback
    if pid_b >= m_cand:
        return

    offs_r = pid_b * 64 + tl.arange(0, 64)
    clamped_r = tl.minimum(offs_r, K_cap - 1)
    offs_d = tl.arange(0, HEAD_DIM)

    k_ptrs = (
        K_ptr
        + clamped_r[:, None] * stride_kn
        + pid_h * stride_kh
        + offs_d[None, :] * stride_kd
    )
    v_ptrs = (
        V_ptr
        + clamped_r[:, None] * stride_vn
        + pid_h * stride_vh
        + offs_d[None, :] * stride_vd
    )
    k_val = tl.load(k_ptrs).to(tl.float32)
    v_val = tl.load(v_ptrs).to(tl.float32)

    k_mean = tl.sum(k_val, axis=0) * (1.0 / 64.0)
    v_mean = tl.sum(v_val, axis=0) * (1.0 / 64.0)

    km_ptrs = (
        K_mean_ptr + pid_h * stride_km_h + pid_b * stride_km_b + offs_d * stride_km_d
    )
    vm_ptrs = (
        V_mean_ptr + pid_h * stride_vm_h + pid_b * stride_vm_b + offs_d * stride_vm_d
    )
    tl.store(km_ptrs, k_mean.to(tl.bfloat16))
    tl.store(vm_ptrs, v_mean.to(tl.bfloat16))

    dk = k_val - k_mean[None, :]
    dv = v_val - v_mean[None, :]
    dk_sq_row = tl.sum(dk * dk, axis=1)  # [64]
    dv_sq_row = tl.sum(dv * dv, axis=1)  # [64]

    tr_sigma_k = tl.sum(dk_sq_row, axis=0) * (1.0 / 64.0)
    tr_sigma_v = tl.sum(dv_sq_row, axis=0) * (1.0 / 64.0)
    tau_k = tr_sigma_k * (1.0 / (2.0 * HEAD_DIM))

    dk_norm = tl.sqrt(dk_sq_row + 1e-12)
    dv_norm = tl.sqrt(dv_sq_row + 1e-12)
    cross_kv = tl.sum(dk_norm * dv_norm, axis=0) * (1.0 / 64.0)
    v_mean_norm = tl.sqrt(tl.sum(v_mean * v_mean, axis=0) + 1e-12)
    sigma_v = tl.sqrt(tr_sigma_v + 1e-12)
    rho_kv = cross_kv / (HEAD_DIM * (v_mean_norm + sigma_v + 1e-5))

    tl.store(Tau_k_ptr + pid_h * stride_tk_h + pid_b * stride_tk_b, tau_k)
    tl.store(Rho_kv_ptr + pid_h * stride_rk_h + pid_b * stride_rk_b, rho_kv)


@triton.jit
def _zing_reduce_4x4_dualpool_kernel(
    Sub_Logits,  # [H, n_mult * M_q_sub, M_cand_sub] bf16
    Blk_Scores,  # [2 * H, M_q, M_cand_cap] float32
    Q_norm,  # [H, n_mult * M_q_sub] float32
    K_norm,  # [H, M_cand_sub] float32
    Blk_Kind,  # [M_cand_cap] int8 or int32
    Meta_ptr,  # Optional int32 [32]
    Tau_k_ptr,  # [H, M_cand_cap] float32
    Rho_kv_ptr,  # [H, M_cand_cap] float32
    stride_slh,
    stride_slm,
    stride_sln,
    stride_bsh,
    stride_bsm,
    stride_bsc,
    stride_qnh,
    stride_qnm,
    stride_knh,
    stride_knn,
    stride_tk_h,
    stride_tk_b,
    stride_rk_h,
    stride_rk_b,
    M_q_sub,
    M_cand_fallback,
    M_prefix_fallback,
    M_cand_cap,
    H_heads,
    HAS_META_PTR: tl.constexpr,
    HAS_PAIR: tl.constexpr,
    HAS_TRIAGE: tl.constexpr,
    BLOCK_C: tl.constexpr,
):
    pid_m = tl.program_id(0)  # 0 .. M_q - 1
    pid_h = tl.program_id(1)  # 0 .. H - 1

    M_cand = tl.load(Meta_ptr + 0) if HAS_META_PTR else M_cand_fallback
    M_prefix = tl.load(Meta_ptr + 1) if HAS_META_PTR else M_prefix_fallback

    offs_c = tl.arange(0, BLOCK_C)
    mask_c = offs_c < M_cand
    mask_cap = offs_c < M_cand_cap
    base_ptr = Sub_Logits + pid_h * stride_slh

    s0 = tl.zeros([BLOCK_C], dtype=tl.float32) - 1.0e20
    c0 = tl.zeros([BLOCK_C], dtype=tl.float32) - 1.0e20
    q0_rms_sq = 0.0
    for iq in tl.static_range(0, 4):
        iq_idx = pid_m * 4 + iq
        q_inv0 = tl.load(Q_norm + pid_h * stride_qnh + iq_idx * stride_qnm)
        q0_rms_sq = q0_rms_sq + 1.0 / (tl.maximum(q_inv0 * q_inv0, 1e-12) * 512.0)
        row_ptr = base_ptr + iq_idx * stride_slm
        for ik in tl.static_range(0, 4):
            ik_offs = offs_c * 4 + ik
            k_inv = tl.load(
                K_norm + pid_h * stride_knh + ik_offs * stride_knn,
                mask=mask_c,
                other=0.0,
            )
            col_offs = ik_offs * stride_sln
            v = tl.load(row_ptr + col_offs, mask=mask_c, other=-1.0e20).to(tl.float32)
            s0 = tl.maximum(s0, v)
            cos0 = tl.where(mask_c, v * q_inv0 * k_inv, -1.0e20)
            c0 = tl.maximum(c0, cos0)

    kind = tl.load(Blk_Kind + offs_c, mask=mask_c, other=0)
    is_ref = (kind == 1) & mask_c
    is_sink = (kind == 2) & mask_c
    is_wsrc = (kind == 3) & mask_c
    is_wfin = (kind == 4) & mask_c
    is_win = (is_wsrc | is_wfin) & mask_c

    n_win = tl.sum(is_win.to(tl.int32), axis=0)
    m_w0 = tl.where(n_win >= 4, is_win, (offs_c >= M_prefix) & mask_c)
    n_w0 = tl.maximum(tl.sum(m_w0.to(tl.float32), axis=0), 1.0)

    mu_w0 = tl.sum(tl.where(m_w0, s0, 0.0), axis=0) / n_w0
    dw0 = tl.where(m_w0, s0 - mu_w0, 0.0)
    std_w0 = tl.sqrt(tl.sum(dw0 * dw0, axis=0) / n_w0 + 1e-6)

    mu_cw0 = tl.sum(tl.where(m_w0, c0, 0.0), axis=0) / n_w0
    dcw0 = tl.where(m_w0, c0 - mu_cw0, 0.0)
    std_cw0 = tl.sqrt(tl.sum(dcw0 * dcw0, axis=0) / n_w0 + 1e-6)

    n_r = tl.sum(is_ref.to(tl.int32), axis=0)
    n_rf = tl.maximum(n_r.to(tl.float32), 1.0)
    has_ref0 = (n_r >= 2) & (n_w0 >= 4.0)

    mu_r0 = tl.sum(tl.where(is_ref, s0, 0.0), axis=0) / n_rf
    dr0 = tl.where(is_ref, s0 - mu_r0, 0.0)
    std_r0 = tl.sqrt(tl.sum(dr0 * dr0, axis=0) / n_rf + 1e-6)

    mu_cr0 = tl.sum(tl.where(is_ref, c0, 0.0), axis=0) / n_rf
    dcr0 = tl.where(is_ref, c0 - mu_cr0, 0.0)
    std_cr0 = tl.sqrt(tl.sum(dcr0 * dcr0, axis=0) / n_rf + 1e-6)

    c_thr0 = tl.maximum(
        0.05, tl.minimum(mu_cr0 - 1.15 * std_cr0, mu_cw0 - 1.10 * std_cw0)
    )
    gate_r0 = tl.minimum(tl.maximum((c0 - c_thr0) / (std_cr0 + 1e-4), 0.0), 1.0)
    shift_r0 = tl.minimum(tl.maximum(mu_w0 - mu_r0, 0.0), 1.25 * std_w0)
    scale_r0 = tl.minimum(tl.maximum(std_w0 / std_r0, 1.0), 1.25)
    boost_r0 = tl.maximum(shift_r0 + (s0 - mu_r0) * (scale_r0 - 1.0), 0.0)
    s0_cal = tl.where(has_ref0 & is_ref, s0 + gate_r0 * boost_r0, s0)

    std_cw0_eff = tl.maximum(std_cw0, 0.05)
    z_c0 = (c0 - mu_cw0) / (std_cw0_eff + 1e-4)
    d0_sink = tl.minimum(tl.maximum(-0.35 - z_c0, 0.0), 2.0)
    g0_sink = tl.minimum(d0_sink / 0.65, 1.0)
    ev0_sink = mu_w0 - (1.5 + 2.0 * d0_sink) * std_w0
    s0_sink = (1.0 - g0_sink) * s0_cal + g0_sink * tl.minimum(s0_cal, ev0_sink)
    ev0_s = (n_win >= 4) & is_sink & (c0 < 0.05) & (z_c0 < -0.35)
    s0_cal = tl.where(ev0_s, s0_sink, s0_cal)

    d0_ref = tl.minimum(tl.maximum(-0.50 - z_c0, 0.0), 2.0)
    g0_ref = tl.minimum(d0_ref / 0.70, 1.0)
    ev0_ref = mu_w0 - (1.25 + 1.75 * d0_ref) * std_w0
    s0_ref = (1.0 - g0_ref) * s0_cal + g0_ref * tl.minimum(s0_cal, ev0_ref)
    ev0_r = has_ref0 & is_ref & (c0 < 0.05) & (c0 < mu_cr0) & (z_c0 < -0.50)
    s0_cal = tl.where(ev0_r, s0_ref, s0_cal)
    ev0 = ev0_s | ev0_r | (is_ref & (c0 < 0.0))
    ch0 = is_ref & (c0 > 0.05)

    if HAS_TRIAGE:
        tau_k_val = tl.load(
            Tau_k_ptr + pid_h * stride_tk_h + offs_c * stride_tk_b,
            mask=mask_c,
            other=0.0,
        )
        rho_kv_val = tl.load(
            Rho_kv_ptr + pid_h * stride_rk_h + offs_c * stride_rk_b,
            mask=mask_c,
            other=0.0,
        )
        j0 = tl.minimum(q0_rms_sq * tau_k_val, 4.0)
        r0 = tl.minimum(tl.sqrt(q0_rms_sq) * rho_kv_val, 4.0)
        comp0 = j0 + r0 + 0.05
        comp0 = tl.where(ev0, 0.05, tl.where(ch0, tl.maximum(comp0, 1.0), comp0))
        s0_cal = s0_cal * comp0

    s0_out = tl.where(mask_c, s0_cal, -1.0e30)

    if HAS_PAIR:
        s1 = tl.zeros([BLOCK_C], dtype=tl.float32) - 1.0e20
        c1 = tl.zeros([BLOCK_C], dtype=tl.float32) - 1.0e20
        q1_rms_sq = 0.0
        for iq in tl.static_range(0, 4):
            iq_idx = M_q_sub + pid_m * 4 + iq
            q_inv1 = tl.load(Q_norm + pid_h * stride_qnh + iq_idx * stride_qnm)
            q1_rms_sq = q1_rms_sq + 1.0 / (tl.maximum(q_inv1 * q_inv1, 1e-12) * 512.0)
            row_ptr = base_ptr + iq_idx * stride_slm
            for ik in tl.static_range(0, 4):
                ik_offs = offs_c * 4 + ik
                k_inv = tl.load(
                    K_norm + pid_h * stride_knh + ik_offs * stride_knn,
                    mask=mask_c,
                    other=0.0,
                )
                col_offs = ik_offs * stride_sln
                v = tl.load(row_ptr + col_offs, mask=mask_c, other=-1.0e20).to(
                    tl.float32
                )
                s1 = tl.maximum(s1, v)
                cos1 = tl.where(mask_c, v * q_inv1 * k_inv, -1.0e20)
                c1 = tl.maximum(c1, cos1)

        n_wfin = tl.sum(is_wfin.to(tl.int32), axis=0)
        m_w1 = tl.where(
            n_wfin >= 4,
            is_wfin,
            tl.where(n_win >= 4, is_win, (offs_c >= M_prefix) & mask_c),
        )
        n_w1 = tl.maximum(tl.sum(m_w1.to(tl.float32), axis=0), 1.0)

        mu_w1 = tl.sum(tl.where(m_w1, s1, 0.0), axis=0) / n_w1
        dw1 = tl.where(m_w1, s1 - mu_w1, 0.0)
        std_w1 = tl.sqrt(tl.sum(dw1 * dw1, axis=0) / n_w1 + 1e-6)

        mu_cw1 = tl.sum(tl.where(m_w1, c1, 0.0), axis=0) / n_w1
        dcw1 = tl.where(m_w1, c1 - mu_cw1, 0.0)
        std_cw1 = tl.sqrt(tl.sum(dcw1 * dcw1, axis=0) / n_w1 + 1e-6)

        has_ref1 = (n_r >= 2) & (n_w1 >= 4.0)
        mu_r1 = tl.sum(tl.where(is_ref, s1, 0.0), axis=0) / n_rf
        dr1 = tl.where(is_ref, s1 - mu_r1, 0.0)
        std_r1 = tl.sqrt(tl.sum(dr1 * dr1, axis=0) / n_rf + 1e-6)

        mu_cr1 = tl.sum(tl.where(is_ref, c1, 0.0), axis=0) / n_rf
        dcr1 = tl.where(is_ref, c1 - mu_cr1, 0.0)
        std_cr1 = tl.sqrt(tl.sum(dcr1 * dcr1, axis=0) / n_rf + 1e-6)

        c_thr1 = tl.maximum(
            0.05, tl.minimum(mu_cr1 - 1.15 * std_cr1, mu_cw1 - 1.10 * std_cw1)
        )
        gate_r1 = tl.minimum(tl.maximum((c1 - c_thr1) / (std_cr1 + 1e-4), 0.0), 1.0)
        shift_r1 = tl.minimum(tl.maximum(mu_w1 - mu_r1, 0.0), 1.25 * std_w1)
        scale_r1 = tl.minimum(tl.maximum(std_w1 / std_r1, 1.0), 1.25)
        boost_r1 = tl.maximum(shift_r1 + (s1 - mu_r1) * (scale_r1 - 1.0), 0.0)
        s1_cal = tl.where(has_ref1 & is_ref, s1 + gate_r1 * boost_r1, s1)

        has_dual_decay = (n_win >= 4) & (n_w1 >= 4.0) & (n_w0 >= 4.0)
        std_cw1_eff = tl.maximum(std_cw1, 0.05)
        z_c1 = (c1 - mu_cw1) / (std_cw1_eff + 1e-4)
        z_c_sink = tl.minimum(z_c0, 0.25 * z_c1 + 0.75 * z_c0)
        d1_sink = tl.minimum(tl.maximum(-0.35 - z_c_sink, 0.0), 2.0)
        g1_sink = tl.minimum(d1_sink / 0.65, 1.0)
        ev1_sink = mu_w1 - (1.5 + 2.0 * d1_sink) * std_w1
        s1_sink = (1.0 - g1_sink) * s1_cal + g1_sink * tl.minimum(s1_cal, ev1_sink)
        ev1_s = (
            has_dual_decay & is_sink & ((c0 < 0.05) | (c1 < 0.05)) & (z_c_sink < -0.35)
        )
        s1_cal = tl.where(ev1_s, s1_sink, s1_cal)

        z_c_ref = tl.minimum(z_c0, 0.40 * z_c1 + 0.60 * z_c0)
        d1_ref = tl.minimum(tl.maximum(-0.50 - z_c_ref, 0.0), 2.0)
        g1_ref = tl.minimum(d1_ref / 0.70, 1.0)
        ev1_ref = mu_w1 - (1.25 + 1.75 * d1_ref) * std_w1
        s1_ref = (1.0 - g1_ref) * s1_cal + g1_ref * tl.minimum(s1_cal, ev1_ref)
        ev1_r = (
            has_ref1
            & has_dual_decay
            & is_ref
            & ((c0 < 0.05) | (c1 < 0.05))
            & (c1 < mu_cr1)
            & (z_c_ref < -0.50)
        )
        s1_cal = tl.where(ev1_r, s1_ref, s1_cal)
        ev1 = ev1_s | ev1_r | (is_ref & ((c1 < 0.0) | (c0 < 0.0)))
        ch1 = is_ref & ((c1 > 0.05) | (c0 > 0.05))

        mu_s0_w = tl.sum(tl.where(m_w0, s0_cal, 0.0), axis=0) / n_w0
        ds0_w = tl.where(m_w0, s0_cal - mu_s0_w, 0.0)
        std_s0_w = tl.sqrt(tl.sum(ds0_w * ds0_w, axis=0) / n_w0 + 1e-6)

        s0_on_w1 = mu_w1 + (s0_cal - mu_s0_w) * (std_w1 / std_s0_w)
        s_wsrc = tl.maximum(s1_cal, 0.35 * s1_cal + 0.65 * s0_on_w1)
        s_wfin = tl.maximum(s1_cal, 0.80 * s1_cal + 0.20 * s0_on_w1)
        s_sink = tl.maximum(s1_cal, 0.65 * s1_cal + 0.35 * s0_on_w1)
        s_ref = tl.maximum(s1_cal, 0.50 * s1_cal + 0.50 * s0_on_w1)
        s_act = tl.where(
            is_wsrc,
            s_wsrc,
            tl.where(
                is_wfin,
                s_wfin,
                tl.where(
                    is_sink & (~ev1_s),
                    s_sink,
                    tl.where(ch1 & (~ev1), s_ref, s1_cal),
                ),
            ),
        )

        if HAS_TRIAGE:
            j1 = tl.minimum(q1_rms_sq * tau_k_val, 4.0)
            r1 = tl.minimum(tl.sqrt(q1_rms_sq) * rho_kv_val, 4.0)
            comp1 = j1 + r1 + 0.05
            comp1 = tl.where(ev1, 0.05, tl.where(ch1, tl.maximum(comp1, 1.0), comp1))
            s_act = s_act * comp1

        s_act_out = tl.where(mask_c, s_act, -1.0e30)

        out_s0_ptrs = (
            Blk_Scores + pid_h * stride_bsh + pid_m * stride_bsm + offs_c * stride_bsc
        )
        tl.store(out_s0_ptrs, s0_out, mask=mask_cap)
        out_act_ptrs = (
            Blk_Scores
            + (H_heads + pid_h) * stride_bsh
            + pid_m * stride_bsm
            + offs_c * stride_bsc
        )
        tl.store(out_act_ptrs, s_act_out, mask=mask_cap)
    else:
        out_s0_ptrs = (
            Blk_Scores + pid_h * stride_bsh + pid_m * stride_bsm + offs_c * stride_bsc
        )
        tl.store(out_s0_ptrs, s0_out, mask=mask_cap)


@triton.jit
def _zing_pack_and_shift_all_masks_kernel(
    Top_Idx,  # int64 [total_heads, M_q, K_top]
    Top_Val,  # float32 [total_heads, M_q, K_top]
    Out_src,  # int32 [H, M_q, MAX_ROW_STRIDE]
    Out_s0,  # int32 [H, M_q, MAX_ROW_STRIDE]
    Out_s1,  # int32 [H, M_q, MAX_ROW_STRIDE]
    K_cand_src_ptr,  # int32 [H]
    K_cand_s0_ptr,  # int32 [H]
    K_cand_s1_ptr,  # int32 [H]
    Meta_ptr,  # Optional int32 [32]
    stride_th,
    stride_tm,
    stride_tk,
    stride_outh,
    stride_outm,
    M_cand_fallback,
    M_full_src_fallback,
    M_full_s0_fallback,
    M_cand_s1_fallback,
    M_full_s1_fallback,
    b_evict_lo_fallback,
    b_evict_hi_fallback,
    shift_s1_fallback,
    K_top,
    H_heads,
    PRICE_PI,
    HAS_META_PTR: tl.constexpr,
    HAS_PAIR: tl.constexpr,
    WRITE_SRC: tl.constexpr,
    WRITE_S0: tl.constexpr,
    WRITE_S1: tl.constexpr,
    USE_PRICE_PI: tl.constexpr,
    BLOCK_FULL: tl.constexpr,
    BLOCK_N: tl.constexpr,
):
    pid_m = tl.program_id(0)  # 0 .. M_q - 1
    pid_h = tl.program_id(1)  # 0 .. H - 1

    if HAS_META_PTR:
        M_cand = tl.load(Meta_ptr + 0)
        M_full_src = tl.load(Meta_ptr + 4)
        M_full_s0 = tl.load(Meta_ptr + 7)
        M_cand_s1 = tl.load(Meta_ptr + 10)
        M_full_s1 = tl.load(Meta_ptr + 11)
        b_evict_lo = tl.load(Meta_ptr + 12)
        b_evict_hi = tl.load(Meta_ptr + 13)
        shift_s1 = tl.load(Meta_ptr + 14)
    else:
        M_cand = M_cand_fallback
        M_full_src = M_full_src_fallback
        M_full_s0 = M_full_s0_fallback
        M_cand_s1 = M_cand_s1_fallback
        M_full_s1 = M_full_s1_fallback
        b_evict_lo = b_evict_lo_fallback
        b_evict_hi = b_evict_hi_fallback
        shift_s1 = shift_s1_fallback

    offs_f = tl.arange(0, BLOCK_FULL)
    offs_k = tl.arange(0, BLOCK_N)
    eff_k_top = tl.minimum(K_top, M_cand)
    mask_k = offs_k < eff_k_top
    min_cand = tl.minimum(4, M_cand)

    row_offset = pid_h * stride_outh + pid_m * stride_outm

    if WRITE_SRC:
        t_ptrs_src = (
            Top_Idx + pid_h * stride_th + pid_m * stride_tm + offs_k * stride_tk
        )
        b_src = tl.load(t_ptrs_src, mask=mask_k, other=0).to(tl.int32)
        if USE_PRICE_PI:
            v_ptrs_src = (
                Top_Val + pid_h * stride_th + pid_m * stride_tm + offs_k * stride_tk
            )
            v_src = (
                tl.load(v_ptrs_src, mask=mask_k, other=-1.0e30) * 0.08838834764831845
            )
            v_max_src = tl.max(v_src, axis=0)
            exp_src = tl.where(mask_k, tl.exp(v_src - v_max_src), 0.0)
            prob_src = exp_src / tl.maximum(tl.sum(exp_src, axis=0), 1e-12)
            pass_src = (offs_k < min_cand) | (prob_src >= PRICE_PI)
            b_src = tl.where(pass_src, b_src, -1)
        src_row_ptr = Out_src + row_offset
        tl.store(
            src_row_ptr + offs_f,
            (M_cand + offs_f).to(tl.int32),
            mask=offs_f < M_full_src,
        )
        kc_src = tl.minimum(tl.load(K_cand_src_ptr + pid_h), M_cand)
        tl.store(src_row_ptr + M_full_src + offs_k, b_src, mask=offs_k < kc_src)

    if WRITE_S0 or WRITE_S1:
        act_h = (H_heads if HAS_PAIR else 0) + pid_h
        t_ptrs_act = (
            Top_Idx + act_h * stride_th + pid_m * stride_tm + offs_k * stride_tk
        )
        b_act = tl.load(t_ptrs_act, mask=mask_k, other=0).to(tl.int32)
        if USE_PRICE_PI:
            v_ptrs_act = (
                Top_Val + act_h * stride_th + pid_m * stride_tm + offs_k * stride_tk
            )
            v_act = (
                tl.load(v_ptrs_act, mask=mask_k, other=-1.0e30) * 0.08838834764831845
            )
            v_max_act = tl.max(v_act, axis=0)
            exp_act = tl.where(mask_k, tl.exp(v_act - v_max_act), 0.0)
            prob_act = exp_act / tl.maximum(tl.sum(exp_act, axis=0), 1e-12)
            pass_act = (offs_k < min_cand) | (prob_act >= PRICE_PI)
        else:
            pass_act = mask_k

        if WRITE_S0:
            s0_row_ptr = Out_s0 + row_offset
            tl.store(
                s0_row_ptr + offs_f,
                (M_cand + offs_f).to(tl.int32),
                mask=offs_f < M_full_s0,
            )
            kc_s0 = tl.minimum(tl.load(K_cand_s0_ptr + pid_h), M_cand)
            b_s0_val = tl.where(pass_act, b_act, -1) if USE_PRICE_PI else b_act
            tl.store(s0_row_ptr + M_full_s0 + offs_k, b_s0_val, mask=offs_k < kc_s0)

        if WRITE_S1:
            s1_row_ptr = Out_s1 + row_offset
            tl.store(
                s1_row_ptr + offs_f,
                (M_cand_s1 + offs_f).to(tl.int32),
                mask=offs_f < M_full_s1,
            )
            kc_s1 = tl.minimum(tl.load(K_cand_s1_ptr + pid_h), M_cand_s1)
            tl.store(s1_row_ptr + M_full_s1 + offs_k, -1, mask=offs_k < kc_s1)
            b1 = tl.where(b_act < b_evict_lo, b_act, b_act - shift_s1)
            keep = (
                mask_k
                & pass_act
                & ((b_act < b_evict_lo) | (b_act >= b_evict_hi))
                & (b1 >= 0)
                & (b1 < M_cand_s1)
            )
            pos = tl.cumsum(keep.to(tl.int32), axis=0) - 1
            write_s1 = keep & (pos < kc_s1)
            tl.store(s1_row_ptr + M_full_s1 + pos, b1, mask=write_s1)


@triton.jit
def _zing_pi_filter_and_pack_masks_kernel(
    Blk_Scores,  # float32 [total_heads, M_q, M_cand_cap]
    Out_src,  # int32 [H, M_q, MAX_ROW_STRIDE]
    Out_s0,  # int32 [H, M_q, MAX_ROW_STRIDE]
    Out_s1,  # int32 [H, M_q, MAX_ROW_STRIDE]
    K_cand_src_ptr,  # int32 [H]
    K_cand_s0_ptr,  # int32 [H]
    K_cand_s1_ptr,  # int32 [H]
    Meta_ptr,  # Optional int32 [32]
    stride_bsh,
    stride_bsm,
    stride_bsc,
    stride_outh,
    stride_outm,
    M_cand_fallback,
    M_full_src_fallback,
    M_full_s0_fallback,
    M_cand_s1_fallback,
    M_full_s1_fallback,
    b_evict_lo_fallback,
    b_evict_hi_fallback,
    shift_s1_fallback,
    H_heads,
    PRICE_PI,
    HAS_META_PTR: tl.constexpr,
    HAS_PAIR: tl.constexpr,
    WRITE_SRC: tl.constexpr,
    WRITE_S0: tl.constexpr,
    WRITE_S1: tl.constexpr,
    BLOCK_FULL: tl.constexpr,
    BLOCK_C: tl.constexpr,
):
    pid_m = tl.program_id(0)  # 0 .. M_q - 1
    pid_h = tl.program_id(1)  # 0 .. H - 1

    if HAS_META_PTR:
        M_cand = tl.load(Meta_ptr + 0)
        M_full_src = tl.load(Meta_ptr + 4)
        M_full_s0 = tl.load(Meta_ptr + 7)
        M_cand_s1 = tl.load(Meta_ptr + 10)
        M_full_s1 = tl.load(Meta_ptr + 11)
        b_evict_lo = tl.load(Meta_ptr + 12)
        b_evict_hi = tl.load(Meta_ptr + 13)
        shift_s1 = tl.load(Meta_ptr + 14)
    else:
        M_cand = M_cand_fallback
        M_full_src = M_full_src_fallback
        M_full_s0 = M_full_s0_fallback
        M_cand_s1 = M_cand_s1_fallback
        M_full_s1 = M_full_s1_fallback
        b_evict_lo = b_evict_lo_fallback
        b_evict_hi = b_evict_hi_fallback
        shift_s1 = shift_s1_fallback

    offs_f = tl.arange(0, BLOCK_FULL)
    offs_c = tl.arange(0, BLOCK_C)
    mask_c = offs_c < M_cand
    min_cand = tl.minimum(4, M_cand)

    row_offset = pid_h * stride_outh + pid_m * stride_outm

    if WRITE_SRC:
        v_ptrs_src = (
            Blk_Scores + pid_h * stride_bsh + pid_m * stride_bsm + offs_c * stride_bsc
        )
        v_src = tl.load(v_ptrs_src, mask=mask_c, other=-1.0e30) * 0.08838834764831845
        v_max_src = tl.max(v_src, axis=0)
        v_rel_src = v_src - v_max_src
        exp_src = tl.where(mask_c, tl.exp(v_rel_src), 0.0)
        prob_src = exp_src / tl.maximum(tl.sum(exp_src, axis=0), 1e-12)

        kc_src = tl.minimum(tl.load(K_cand_src_ptr + pid_h), M_cand)
        pass_pi_src = mask_c & (prob_src >= PRICE_PI)
        cnt_pi_src = tl.sum(pass_pi_src.to(tl.int32), axis=0)

        if (cnt_pi_src >= min_cand) & (cnt_pi_src <= kc_src):
            keep_src = pass_pi_src
        else:
            target_src = tl.where(cnt_pi_src < min_cand, min_cand, kc_src)
            lo_s = -20.0
            hi_s = 0.0
            for _ in tl.static_range(0, 8):
                mid_s = 0.5 * (lo_s + hi_s)
                c_mid = tl.sum((mask_c & (v_rel_src >= mid_s)).to(tl.int32), axis=0)
                lo_s = tl.where(c_mid > target_src, mid_s, lo_s)
                hi_s = tl.where(c_mid > target_src, hi_s, mid_s)
            keep_strict_s = mask_c & (v_rel_src >= hi_s)
            n_strict_s = tl.sum(keep_strict_s.to(tl.int32), axis=0)
            keep_loose_s = mask_c & (v_rel_src >= lo_s) & (~keep_strict_s)
            pos_loose_s = tl.cumsum(keep_loose_s.to(tl.int32), axis=0) - 1
            keep_src = keep_strict_s | (
                keep_loose_s & (n_strict_s + pos_loose_s < target_src)
            )

        src_row_ptr = Out_src + row_offset
        tl.store(
            src_row_ptr + offs_f,
            (M_cand + offs_f).to(tl.int32),
            mask=offs_f < M_full_src,
        )
        tl.store(src_row_ptr + M_full_src + offs_c, -1, mask=offs_c < kc_src)
        pos_src = tl.cumsum(keep_src.to(tl.int32), axis=0) - 1
        tl.store(
            src_row_ptr + M_full_src + pos_src,
            offs_c.to(tl.int32),
            mask=keep_src & (pos_src < kc_src),
        )

    if WRITE_S0 or WRITE_S1:
        act_h = (H_heads if HAS_PAIR else 0) + pid_h
        v_ptrs_act = (
            Blk_Scores + act_h * stride_bsh + pid_m * stride_bsm + offs_c * stride_bsc
        )
        v_act = tl.load(v_ptrs_act, mask=mask_c, other=-1.0e30) * 0.08838834764831845
        v_max_act = tl.max(v_act, axis=0)
        v_rel_act = v_act - v_max_act
        exp_act = tl.where(mask_c, tl.exp(v_rel_act), 0.0)
        prob_act = exp_act / tl.maximum(tl.sum(exp_act, axis=0), 1e-12)
        pass_pi_act = mask_c & (prob_act >= PRICE_PI)
        cnt_pi_act = tl.sum(pass_pi_act.to(tl.int32), axis=0)

        if WRITE_S0:
            kc_s0 = tl.minimum(tl.load(K_cand_s0_ptr + pid_h), M_cand)
            if (cnt_pi_act >= min_cand) & (cnt_pi_act <= kc_s0):
                keep_s0 = pass_pi_act
            else:
                target_s0 = tl.where(cnt_pi_act < min_cand, min_cand, kc_s0)
                lo_0 = -20.0
                hi_0 = 0.0
                for _ in tl.static_range(0, 8):
                    mid_0 = 0.5 * (lo_0 + hi_0)
                    c_mid = tl.sum((mask_c & (v_rel_act >= mid_0)).to(tl.int32), axis=0)
                    lo_0 = tl.where(c_mid > target_s0, mid_0, lo_0)
                    hi_0 = tl.where(c_mid > target_s0, hi_0, mid_0)
                keep_strict_0 = mask_c & (v_rel_act >= hi_0)
                n_strict_0 = tl.sum(keep_strict_0.to(tl.int32), axis=0)
                keep_loose_0 = mask_c & (v_rel_act >= lo_0) & (~keep_strict_0)
                pos_loose_0 = tl.cumsum(keep_loose_0.to(tl.int32), axis=0) - 1
                keep_s0 = keep_strict_0 | (
                    keep_loose_0 & (n_strict_0 + pos_loose_0 < target_s0)
                )

            s0_row_ptr = Out_s0 + row_offset
            tl.store(
                s0_row_ptr + offs_f,
                (M_cand + offs_f).to(tl.int32),
                mask=offs_f < M_full_s0,
            )
            tl.store(s0_row_ptr + M_full_s0 + offs_c, -1, mask=offs_c < kc_s0)
            pos_s0 = tl.cumsum(keep_s0.to(tl.int32), axis=0) - 1
            tl.store(
                s0_row_ptr + M_full_s0 + pos_s0,
                offs_c.to(tl.int32),
                mask=keep_s0 & (pos_s0 < kc_s0),
            )

        if WRITE_S1:
            kc_s1 = tl.minimum(tl.load(K_cand_s1_ptr + pid_h), M_cand_s1)
            b1 = tl.where(offs_c < b_evict_lo, offs_c, offs_c - shift_s1)
            valid_s1 = (
                mask_c
                & ((offs_c < b_evict_lo) | (offs_c >= b_evict_hi))
                & (b1 >= 0)
                & (b1 < M_cand_s1)
            )
            min_cand_s1 = tl.minimum(4, M_cand_s1)
            pass_pi_s1 = valid_s1 & pass_pi_act
            cnt_pi_s1 = tl.sum(pass_pi_s1.to(tl.int32), axis=0)

            if (cnt_pi_s1 >= min_cand_s1) & (cnt_pi_s1 <= kc_s1):
                keep_s1 = pass_pi_s1
            else:
                target_s1 = tl.where(cnt_pi_s1 < min_cand_s1, min_cand_s1, kc_s1)
                lo_1 = -20.0
                hi_1 = 0.0
                for _ in tl.static_range(0, 8):
                    mid_1 = 0.5 * (lo_1 + hi_1)
                    c_mid = tl.sum(
                        (valid_s1 & (v_rel_act >= mid_1)).to(tl.int32), axis=0
                    )
                    lo_1 = tl.where(c_mid > target_s1, mid_1, lo_1)
                    hi_1 = tl.where(c_mid > target_s1, hi_1, mid_1)
                keep_strict_1 = valid_s1 & (v_rel_act >= hi_1)
                n_strict_1 = tl.sum(keep_strict_1.to(tl.int32), axis=0)
                keep_loose_1 = valid_s1 & (v_rel_act >= lo_1) & (~keep_strict_1)
                pos_loose_1 = tl.cumsum(keep_loose_1.to(tl.int32), axis=0) - 1
                keep_s1 = keep_strict_1 | (
                    keep_loose_1 & (n_strict_1 + pos_loose_1 < target_s1)
                )

            s1_row_ptr = Out_s1 + row_offset
            tl.store(
                s1_row_ptr + offs_f,
                (M_cand_s1 + offs_f).to(tl.int32),
                mask=offs_f < M_full_s1,
            )
            tl.store(s1_row_ptr + M_full_s1 + offs_c, -1, mask=offs_c < kc_s1)
            pos_s1 = tl.cumsum(keep_s1.to(tl.int32), axis=0) - 1
            tl.store(
                s1_row_ptr + M_full_s1 + pos_s1,
                b1.to(tl.int32),
                mask=keep_s1 & (pos_s1 < kc_s1),
            )


@triton.jit
def _zing_build_cand_bitmask_kernel(
    num_full_ptr,  # int32 [H]
    blk_idx_ptr,  # int32 [H, M_q, row_stride]
    Meta_branch_ptr,  # Optional int32 [4]: (L_k, M_cand, M_k, M_full)
    bitmask_ptr,  # int32 [H, M_q, 64]
    stride_bh,
    stride_bm,
    stride_bm_h,
    stride_bm_m,
    M_cand_fallback,
    M_k_fallback,
    HAS_META_PTR: tl.constexpr,
    BLOCK_S: tl.constexpr,
):
    pid_m = tl.program_id(0)
    pid_h = tl.program_id(1)
    M_cand = tl.load(Meta_branch_ptr + 1) if HAS_META_PTR else M_cand_fallback
    M_k = tl.load(Meta_branch_ptr + 2) if HAS_META_PTR else M_k_fallback
    m_full_cur = tl.maximum(0, M_k - 1 - M_cand)
    num_full = tl.load(num_full_ptr + pid_h)
    k_cand = tl.maximum(0, num_full - m_full_cur)

    bm_row = bitmask_ptr + pid_h * stride_bm_h + pid_m * stride_bm_m
    offs_w = tl.arange(0, 64)
    tl.store(bm_row + offs_w, 0)
    tl.debug_barrier()

    offs_s = tl.arange(0, BLOCK_S)
    mask_s = offs_s < k_cand
    row_ptr = blk_idx_ptr + pid_h * stride_bh + pid_m * stride_bm + m_full_cur
    sel_b = tl.load(row_ptr + offs_s, mask=mask_s, other=-1)
    valid = mask_s & (sel_b >= 0) & (sel_b < M_cand)
    word_idx = tl.where(valid, sel_b >> 5, 0)
    bit_mask = tl.where(valid, 1 << (sel_b & 31), 0).to(tl.int32)
    tl.atomic_or(bm_row + word_idx, bit_mask, mask=valid)


@triton.jit
def _zing_block_sparse_attn_fwd_kernel(
    Q,
    K,
    V,
    Out,
    num_full_ptr,  # int32 [H]
    blk_idx_ptr,  # int32 [H, M_q, row_stride]
    head_order_ptr,  # int32 [H]
    Meta_branch_ptr,  # Optional int32 [4]: (L_k, M_cand, M_k, M_full)
    K_mean_ptr,  # [H, M_cand_cap, D] bf16
    V_mean_ptr,  # [H, M_cand_cap, D] bf16
    Tau_k_ptr,  # [H, M_cand_cap] float32
    Cand_bitmask_ptr,  # [H, M_q, 64] int32
    stride_qm,
    stride_qh,
    stride_qd,
    stride_kn,
    stride_kh,
    stride_kd,
    stride_vn,
    stride_vh,
    stride_vd,
    stride_om,
    stride_oh,
    stride_od,
    stride_bh,
    stride_bm,
    stride_km_h,
    stride_km_b,
    stride_km_d,
    stride_vm_h,
    stride_vm_b,
    stride_vm_d,
    stride_tk_h,
    stride_tk_b,
    stride_cbm_h,
    stride_cbm_m,
    L_q,
    L_k_fallback,
    M_cand_fallback,
    M_k_fallback,
    qk_scale,
    raw_scale,
    HAS_META_PTR: tl.constexpr,
    ENABLE_VIRTUAL_MEAN: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    HEAD_DIM: tl.constexpr,
):
    pid_m = tl.program_id(0)
    pid_h = tl.program_id(1)
    h_idx = tl.load(head_order_ptr + pid_h)
    L_k = tl.load(Meta_branch_ptr + 0) if HAS_META_PTR else L_k_fallback
    M_cand = tl.load(Meta_branch_ptr + 1) if HAS_META_PTR else M_cand_fallback
    M_k = tl.load(Meta_branch_ptr + 2) if HAS_META_PTR else M_k_fallback

    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    offs_d = tl.arange(0, HEAD_DIM)
    mask_m = offs_m < L_q

    q_ptrs = (
        Q
        + offs_m[:, None] * stride_qm
        + h_idx * stride_qh
        + offs_d[None, :] * stride_qd
    )
    q = tl.load(q_ptrs, mask=mask_m[:, None], other=0.0)

    num_full = tl.load(num_full_ptr + h_idx)
    row_idx_ptr = blk_idx_ptr + h_idx * stride_bh + pid_m * stride_bm

    m_i = tl.zeros([BLOCK_M], dtype=tl.float32) - float("inf")
    l_i = tl.zeros([BLOCK_M], dtype=tl.float32)
    acc = tl.zeros([BLOCK_M, HEAD_DIM], dtype=tl.float32)

    k_base = K + h_idx * stride_kh + offs_d[None, :] * stride_kd
    v_base = V + h_idx * stride_vh + offs_d[None, :] * stride_vd

    actual_valid = 0
    for i in range(0, num_full):
        raw_blk_idx = tl.load(row_idx_ptr + i)
        if raw_blk_idx >= 0:
            actual_valid += 1
            blk_idx = tl.minimum(raw_blk_idx, M_k - 1)
            offs_n = blk_idx * BLOCK_N + tl.arange(0, BLOCK_N)
            k = tl.load(k_base + offs_n[:, None] * stride_kn)
            qk = tl.dot(q, tl.trans(k)) * qk_scale
            m_ij = tl.maximum(m_i, tl.max(qk, 1))
            p = tl.math.exp2(qk - m_ij[:, None])
            alpha = tl.math.exp2(m_i - m_ij)
            l_i = l_i * alpha + tl.sum(p, 1)
            v = tl.load(v_base + offs_n[:, None] * stride_vn)
            acc = acc * alpha[:, None] + tl.dot(p.to(tl.bfloat16), v)
            m_i = m_ij

    # Epilogue block blk_idx = M_k - 1
    blk_idx = M_k - 1
    offs_n = blk_idx * BLOCK_N + tl.arange(0, BLOCK_N)
    mask_n = offs_n < L_k
    k = tl.load(k_base + offs_n[:, None] * stride_kn, mask=mask_n[:, None], other=0.0)
    qk = tl.dot(q, tl.trans(k)) * qk_scale
    qk = tl.where(mask_n[None, :], qk, -1.0e20)
    m_ij = tl.maximum(m_i, tl.max(qk, 1))
    p = tl.math.exp2(qk - m_ij[:, None])
    alpha = tl.math.exp2(m_i - m_ij)
    l_i = l_i * alpha + tl.sum(p, 1)
    v = tl.load(v_base + offs_n[:, None] * stride_vn, mask=mask_n[:, None], other=0.0)
    acc = acc * alpha[:, None] + tl.dot(p.to(tl.bfloat16), v)
    m_i = m_ij

    if ENABLE_VIRTUAL_MEAN:
        q_f32 = q.to(tl.float32)
        q_sq_s2 = tl.sum(q_f32 * q_f32, axis=1) * (raw_scale * raw_scale)
        m_full_cur = tl.maximum(0, M_k - 1 - M_cand)
        k_sel_cand = tl.maximum(0, actual_valid - m_full_cur)
        if k_sel_cand < M_cand:
            km_base = K_mean_ptr + h_idx * stride_km_h + offs_d[None, :] * stride_km_d
            vm_base = V_mean_ptr + h_idx * stride_vm_h + offs_d[None, :] * stride_vm_d
            tk_base = Tau_k_ptr + h_idx * stride_tk_h
            bm_base = Cand_bitmask_ptr + h_idx * stride_cbm_h + pid_m * stride_cbm_m
            offs_64 = tl.arange(0, BLOCK_N)
            half_sel = offs_64 >> 5
            bit_shift = offs_64 & 31
            for b_start in range(0, M_cand, BLOCK_N):
                w_idx = b_start >> 5
                w_lo = tl.load(bm_base + w_idx)
                w_hi = tl.load(bm_base + w_idx + 1)
                rem_lo = tl.minimum(tl.maximum(M_cand - b_start, 0), 32)
                rem_hi = tl.minimum(tl.maximum(M_cand - b_start - 32, 0), 32)
                v_mask_lo = tl.where(rem_lo == 32, -1, (1 << rem_lo) - 1)
                v_mask_hi = tl.where(rem_hi == 32, -1, (1 << rem_hi) - 1)
                if (((~w_lo) & v_mask_lo) | ((~w_hi) & v_mask_hi)) != 0:
                    offs_b = b_start + offs_64
                    word_val = tl.where(half_sel == 0, w_lo, w_hi)
                    is_sel = ((word_val >> bit_shift) & 1) != 0
                    valid_b = (offs_b < M_cand) & (~is_sel)
                    km_blk = tl.load(
                        km_base + offs_b[:, None] * stride_km_b,
                        mask=valid_b[:, None],
                        other=0.0,
                    )
                    vm_blk = tl.load(
                        vm_base + offs_b[:, None] * stride_vm_b,
                        mask=valid_b[:, None],
                        other=0.0,
                    )
                    tk_blk = tl.load(
                        tk_base + offs_b * stride_tk_b, mask=valid_b, other=0.0
                    )
                    qk_vm = tl.dot(q, tl.trans(km_blk)) * qk_scale
                    j_bias = (
                        tl.minimum(q_sq_s2[:, None] * tk_blk[None, :], 4.0)
                        * 1.4426950408889634
                    )
                    qk_vm = tl.where(valid_b[None, :], qk_vm + 6.0 + j_bias, -1.0e20)
                    m_ij = tl.maximum(m_i, tl.max(qk_vm, 1))
                    p_vm = tl.math.exp2(qk_vm - m_ij[:, None])
                    alpha = tl.math.exp2(m_i - m_ij)
                    l_i = l_i * alpha + tl.sum(p_vm, 1)
                    acc = acc * alpha[:, None] + tl.dot(p_vm.to(tl.bfloat16), vm_blk)
                    m_i = m_ij

    acc = acc / tl.maximum(l_i[:, None], 1.0e-20)
    out_ptrs = (
        Out
        + offs_m[:, None] * stride_om
        + h_idx * stride_oh
        + offs_d[None, :] * stride_od
    )
    tl.store(out_ptrs, acc.to(tl.bfloat16), mask=mask_m[:, None])


def _exact_block_sparse_sdpa_reference(
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    scale: float,
    L_k: int,
    M_cand: int,
    M_k: int,
    cand_cnt: torch.Tensor,
    cand_idx: torch.Tensor,
    head_order: torch.Tensor,
    *,
    enable_virtual_mean: bool = False,
    k_blk_mean: torch.Tensor | None = None,
    v_blk_mean: torch.Tensor | None = None,
    tau_k: torch.Tensor | None = None,
) -> torch.Tensor:
    """Exact FP32 PyTorch reference supporting both Hard-Drop and P0 Virtual Mean Tiles."""
    L_q, H, D = q.shape
    device = q.device
    M_q = (L_q + BLOCK_SIZE - 1) // BLOCK_SIZE
    out = torch.empty((L_q, H, D), dtype=q.dtype, device=device)

    if enable_virtual_mean and (
        k_blk_mean is None or v_blk_mean is None or tau_k is None
    ):
        k_blk_mean, v_blk_mean, tau_k, _ = compute_kv_block_stats(
            k, v, num_blocks=M_cand
        )

    for h in range(H):
        n_full = int(cand_cnt[h].item())
        qh_all = q[:, h, :].float()  # [L_q, D]
        kh_all = k[:L_k, h, :].float()  # [L_k, D]
        vh_all = v[:L_k, h, :].float()  # [L_k, D]

        for m in range(M_q):
            qs = m * BLOCK_SIZE
            qe = min(L_q, (m + 1) * BLOCK_SIZE)
            if qs >= qe:
                continue
            if cand_idx.dim() == 2:
                raw_blks = [int(cand_idx[h, i].item()) for i in range(n_full)]
            else:
                raw_blks = [int(cand_idx[h, m, i].item()) for i in range(n_full)]
            active_blocks = set(b for b in raw_blks if b >= 0)
            active_blocks.add(M_k - 1)

            tok_indices = []
            for blk in sorted(active_blocks):
                s_blk = blk * BLOCK_SIZE
                e_blk = min(L_k, s_blk + BLOCK_SIZE)
                if s_blk < e_blk:
                    tok_indices.append(
                        torch.arange(s_blk, e_blk, device=device, dtype=torch.long)
                    )
            tok_idx = torch.cat(tok_indices, dim=0)
            q_tile = qh_all[qs:qe]  # [q_len, D]
            logits_fine = torch.matmul(q_tile, kh_all[tok_idx].T) * scale
            vals_fine = vh_all[tok_idx]

            if enable_virtual_mean and M_cand > 0:
                skipped_cands = [b for b in range(M_cand) if b not in active_blocks]
                if skipped_cands:
                    sk_idx = torch.tensor(
                        skipped_cands, device=device, dtype=torch.long
                    )
                    km_sk = k_blk_mean[h, sk_idx].float()  # [S, D]
                    vm_sk = v_blk_mean[h, sk_idx].float()  # [S, D]
                    tk_sk = tau_k[h, sk_idx].float()  # [S]
                    q_sq_s2 = (q_tile * q_tile).sum(dim=-1, keepdim=True) * (
                        scale * scale
                    )
                    j_bias = torch.clamp(q_sq_s2 * tk_sk.unsqueeze(0), max=4.0)
                    logits_vm = (
                        torch.matmul(q_tile, km_sk.T) * scale
                        + math.log(float(BLOCK_SIZE))
                        + j_bias
                    )
                    logits_all = torch.cat([logits_fine, logits_vm], dim=-1)
                    vals_all = torch.cat([vals_fine, vm_sk], dim=0)
                    probs = torch.softmax(logits_all, dim=-1)
                    out[qs:qe, h, :] = torch.matmul(probs, vals_all).to(q.dtype)
                    continue

            probs = torch.softmax(logits_fine, dim=-1)
            out[qs:qe, h, :] = torch.matmul(probs, vals_fine).to(q.dtype)

    return out


_KERNEL_NUM_WARPS = 4
_KERNEL_NUM_STAGES = 3
_K_POOL_SUB_SAMPLES = 16
_K_POOL_SUB_STEP = 1


def _three_tier_compressed_sdpa_reference(
    q: torch.Tensor,
    k: torch.Tensor | None,
    v: torch.Tensor | None,
    scale: float,
    L_k: int,
    M_cand: int,
    M_k: int,
    cand_cnt: torch.Tensor,
    cand_idx: torch.Tensor,
    head_order: torch.Tensor,
    *,
    skim_cnt: torch.Tensor | None = None,
    skim_idx: torch.Tensor | None = None,
    compressed_kv: dict[str, torch.Tensor] | None = None,
    q_win: torch.Tensor | None = None,
    enable_virtual_mean: bool = True,
    block_valid_len: torch.Tensor | None = None,
) -> torch.Tensor:
    """Exact Three-Tier All-FP8 (Refine / Skim / Skip) reference on compressed resident KV cache."""
    device = q.device
    L_q, H, D = q.shape
    M_q = (L_q + BLOCK_SIZE - 1) // BLOCK_SIZE

    if compressed_kv is None:
        if k is None or v is None:
            raise ValueError("Either compressed_kv or (k, v) must be provided.")
        store = ZingCompressedKVStore(
            max_blocks=max(1, M_k), num_heads=H, head_dim=D, device=device
        )
        store.append_chunk(k[:L_k], v[:L_k], chunk_id=0)
        compressed_kv = store.as_kernel_dict()

    k_blk_mean = compressed_kv["k_blk_mean"]
    v_blk_mean = compressed_kv.get("v_blk_mean")
    k_blk_mean_fp8 = compressed_kv["k_blk_mean_fp8"]
    v_blk_mean_fp8 = compressed_kv["v_blk_mean_fp8"]
    k_blk_scale = compressed_kv["k_blk_scale"]
    v_blk_scale = compressed_kv["v_blk_scale"]
    k_sub_mean_fp8 = compressed_kv["k_sub_mean_fp8"]
    v_sub_mean_fp8 = compressed_kv["v_sub_mean_fp8"]
    k_sub_scale = compressed_kv["k_sub_scale"]
    v_sub_scale = compressed_kv["v_sub_scale"]
    k_res_fp8 = compressed_kv["k_res_fp8"]
    v_res_fp8 = compressed_kv["v_res_fp8"]
    k_res_scale = compressed_kv.get("k_res_scale", compressed_kv.get("k_scale"))
    v_res_scale = compressed_kv.get("v_res_scale", compressed_kv.get("v_scale"))
    tau_k = compressed_kv["tau_k"]
    b_valid_len = compressed_kv.get("block_valid_len", block_valid_len)
    b_is_shifted = compressed_kv.get("block_is_shifted")

    out = torch.zeros_like(q, dtype=torch.float32)

    for h in range(H):
        n_full = int(cand_cnt[h].item())
        n_skim = int(skim_cnt[h].item()) if skim_cnt is not None else 0
        for m_q in range(M_q):
            q_s = m_q * BLOCK_SIZE
            q_e = min(L_q, q_s + BLOCK_SIZE)
            if q_s >= q_e:
                continue
            q_blk = q[q_s:q_e, h, :]
            q_fp8_t, q_sc_t = _quantize_fp8_with_scale(q_blk)
            q_fp8 = q_fp8_t.float()
            q_sc = float(q_sc_t.item())

            if q_win is not None:
                qw_blk = q_win[q_s:q_e, h, :]
                qw_fp8_t, qw_sc_t = _quantize_fp8_with_scale(qw_blk)
                qw_fp8 = qw_fp8_t.float()
                qw_sc = float(qw_sc_t.item())
            else:
                qw_fp8 = q_fp8
                qw_sc = q_sc

            logits_list: list[torch.Tensor] = []
            vals_list: list[torch.Tensor] = []
            seen_refine: set[int] = set()
            seen_skim: set[int] = set()

            # Phase 1: Refine (64 pts/blk, BF16 DC + FP8 residual)
            max_cols = min(n_full, int(cand_idx.shape[-1]))
            refine_seq = [int(cand_idx[h, m_q, c].item()) for c in range(max_cols)]
            if M_k > 0 and (M_k - 1) not in refine_seq:
                refine_seq.append(M_k - 1)

            for b in refine_seq:
                if (
                    b < 0
                    or b >= M_k
                    or b in seen_refine
                    or (k_blk_mean is not None and b >= k_blk_mean.shape[1])
                ):
                    continue
                seen_refine.add(b)
                n_val = (
                    int(b_valid_len[b].item())
                    if (b_valid_len is not None and b < b_valid_len.shape[0])
                    else min(BLOCK_SIZE, max(0, L_k - b * BLOCK_SIZE))
                )
                if n_val <= 0:
                    continue
                s_dc = (q_blk.float() @ k_blk_mean[h, b].float().unsqueeze(-1)) * float(
                    scale
                )
                is_sh = b_is_shifted is not None and int(b_is_shifted[b].item()) != 0
                q_u = qw_fp8 if is_sh else q_fp8
                qs_u = qw_sc if is_sh else q_sc
                k_res_b = k_res_fp8[b, h, :n_val, :].float()
                s_ac = (q_u @ k_res_b.T) * (
                    qs_u * float(k_res_scale[h, b].item()) * float(scale)
                )
                logits_list.append(s_dc + s_ac)

                if v_blk_mean is not None:
                    v_dc = v_blk_mean[h, b].float()
                else:
                    v_dc = v_blk_mean_fp8[h, :, b].float() * float(
                        v_blk_scale[h, b].item()
                    )
                v_ac = v_res_fp8[b, h, :, :n_val].float().T * float(
                    v_res_scale[h, b].item()
                )
                vals_list.append(v_dc.unsqueeze(0) + v_ac)

            # Phase 2: Skim (4 pts/blk, resident 1/16 sub-block FP8 means)
            if skim_idx is not None and n_skim > 0:
                max_sk = min(n_skim, int(skim_idx.shape[-1]))
                for c in range(max_sk):
                    b = int(skim_idx[h, m_q, c].item())
                    if (
                        b < 0
                        or b >= M_cand
                        or b in seen_refine
                        or b in seen_skim
                        or (b_valid_len is not None and b >= b_valid_len.shape[0])
                    ):
                        continue
                    seen_skim.add(b)
                    n_val = (
                        int(b_valid_len[b].item())
                        if (b_valid_len is not None and b < b_valid_len.shape[0])
                        else min(BLOCK_SIZE, max(0, L_k - b * BLOCK_SIZE))
                    )
                    for s_i in range(SUB_PER_BLK):
                        sub_val = min(16, max(0, n_val - s_i * 16))
                        if sub_val <= 0:
                            continue
                        g_sub = b * SUB_PER_BLK + s_i
                        if (
                            k_sub_mean_fp8 is not None
                            and g_sub >= k_sub_mean_fp8.shape[1]
                        ):
                            continue
                        k_sm_fp8 = k_sub_mean_fp8[h, g_sub : g_sub + 1].float()
                        k_sm_sc = float(k_sub_scale[h, g_sub].item())
                        s_sk = (q_fp8 @ k_sm_fp8.T) * (
                            q_sc * k_sm_sc * float(scale)
                        ) + math.log(float(sub_val))
                        v_sk = (
                            v_sub_mean_fp8[h, :, g_sub].float()
                            * float(v_sub_scale[h, g_sub].item())
                        ).unsqueeze(0)
                        logits_list.append(s_sk)
                        vals_list.append(v_sk)

            # Phase 3: Skip (1 pt/blk Virtual Tile, resident 1/64 block FP8 means)
            if enable_virtual_mean:
                q_norm_sq = (q_blk.float() ** 2).sum(dim=-1, keepdim=True)
                for b in range(M_cand):
                    if (
                        b in seen_refine
                        or b in seen_skim
                        or (k_blk_mean_fp8 is not None and b >= k_blk_mean_fp8.shape[1])
                    ):
                        continue
                    n_val = (
                        int(b_valid_len[b].item())
                        if (b_valid_len is not None and b < b_valid_len.shape[0])
                        else min(BLOCK_SIZE, max(0, L_k - b * BLOCK_SIZE))
                    )
                    if n_val <= 0:
                        continue
                    k_bm_fp8 = k_blk_mean_fp8[h, b : b + 1].float()
                    k_bm_sc = float(k_blk_scale[h, b].item())
                    j_bias = torch.clamp(
                        q_norm_sq
                        * (float(scale) * float(scale) * float(D))
                        * float(tau_k[h, b].item()),
                        max=4.0,
                    )
                    s_vt = (
                        (q_fp8 @ k_bm_fp8.T) * (q_sc * k_bm_sc * float(scale))
                        + math.log(float(n_val))
                        + j_bias
                    )
                    v_vt = (
                        v_blk_mean_fp8[h, :, b].float()
                        * float(v_blk_scale[h, b].item())
                    ).unsqueeze(0)
                    logits_list.append(s_vt)
                    vals_list.append(v_vt)

            if logits_list:
                all_logits = torch.cat(logits_list, dim=-1)
                all_vals = torch.cat(vals_list, dim=0)
                probs = torch.softmax(all_logits, dim=-1)
                out[q_s:q_e, h, :] = probs @ all_vals

    return out.to(q.dtype)


def _native_attention_input(tensor: torch.Tensor | None) -> torch.Tensor | None:
    """The native kernel requires contiguous inputs starting at storage offset zero."""
    if tensor is None:
        return None
    # A contiguous slice of a layer or parity slot can still have a nonzero offset.
    if tensor.storage_offset() != 0:
        return tensor.clone(memory_format=torch.contiguous_format)
    return tensor.contiguous()


def launch_zing_block_sparse_attn(
    q: torch.Tensor,
    k: torch.Tensor | None,
    v: torch.Tensor | None,
    scale: float,
    L_k: int,
    M_cand: int,
    M_k: int,
    cand_cnt: torch.Tensor,
    cand_idx: torch.Tensor,
    head_order: torch.Tensor,
    out: torch.Tensor | None = None,
    *,
    meta_branch_gpu: torch.Tensor | None = None,
    enable_virtual_mean: bool = False,
    k_blk_mean: torch.Tensor | None = None,
    v_blk_mean: torch.Tensor | None = None,
    tau_k: torch.Tensor | None = None,
    cand_bitmask: torch.Tensor | None = None,
    skim_cnt: torch.Tensor | None = None,
    skim_idx: torch.Tensor | None = None,
    compressed_kv: dict[str, torch.Tensor] | None = None,
    q_win: torch.Tensor | None = None,
    enable_three_tier: bool = False,
    block_valid_len: torch.Tensor | None = None,
    require_native_compressed: bool = False,
) -> torch.Tensor:
    """Launch _zing_block_sparse_attn_fwd_kernel on [L_q, H, D] tensors (or CPU reference)."""
    if (
        meta_branch_gpu is not None
        and meta_branch_gpu.numel() >= 3
        and (q.device.type != "cuda" or not HAS_TRITON)
    ):
        L_k = int(meta_branch_gpu[0].item())
        M_cand = int(meta_branch_gpu[1].item())
        M_k = int(meta_branch_gpu[2].item())

    if compressed_kv is not None or (
        (skim_cnt is not None or enable_three_tier) and q.device.type != "cuda"
    ):
        if compressed_kv is None and k is not None and v is not None:
            _store = ZingCompressedKVStore(
                max_blocks=max(1, M_k),
                num_heads=q.shape[1],
                head_dim=q.shape[2],
                device=q.device,
            )
            _store.append_chunk(k[:L_k], v[:L_k], chunk_id=0)
            compressed_kv = _store.as_kernel_dict()
        if q.device.type == "cuda":
            try:
                from seedleap_kernels.ops.block_sparse_attention import (
                    block_sparse_attention as _slk_bsa,
                )

                ckv_arg = None
                if compressed_kv is not None:
                    ckv_arg = dict(compressed_kv)
                    if (
                        "k_blk_mean" in ckv_arg
                        and ckv_arg["k_blk_mean"].shape[0] == q.shape[1]
                    ):
                        ckv_arg["k_blk_mean"] = (
                            ckv_arg["k_blk_mean"].transpose(0, 1).contiguous()
                        )
                    if (
                        "v_blk_mean" in ckv_arg
                        and ckv_arg["v_blk_mean"].shape[0] == q.shape[1]
                    ):
                        ckv_arg["v_blk_mean"] = (
                            ckv_arg["v_blk_mean"].transpose(0, 1).contiguous()
                        )
                    if "k_scale" not in ckv_arg and "k_res_scale" in ckv_arg:
                        ckv_arg["k_scale"] = ckv_arg["k_res_scale"]
                    if "v_scale" not in ckv_arg and "v_res_scale" in ckv_arg:
                        ckv_arg["v_scale"] = ckv_arg["v_res_scale"]

                return _slk_bsa(
                    _native_attention_input(q),
                    _native_attention_input(k),
                    _native_attention_input(v),
                    cand_idx=_native_attention_input(cand_idx),
                    exempt_start=M_cand * BLOCK_SIZE,
                    total_kv_len=L_k,
                    softmax_scale=scale,
                    out=out,
                    num_full=cand_cnt,
                    head_order=head_order,
                    sparse_meta=meta_branch_gpu,
                    enable_virtual_mean=enable_virtual_mean,
                    compressed_kv=ckv_arg,
                    skim_idx=_native_attention_input(skim_idx),
                    num_skim=_native_attention_input(skim_cnt),
                    enable_skim=skim_idx is not None and skim_cnt is not None,
                    block_valid_len=block_valid_len,
                    q_win=_native_attention_input(q_win),
                )
            except (ImportError, TypeError) as error:
                if require_native_compressed:
                    raise RuntimeError(
                        "Native compressed attention kernel is unavailable or incompatible"
                    ) from error
        return _three_tier_compressed_sdpa_reference(
            q,
            k,
            v,
            scale,
            L_k,
            M_cand,
            M_k,
            cand_cnt,
            cand_idx,
            head_order,
            skim_cnt=skim_cnt,
            skim_idx=skim_idx,
            compressed_kv=compressed_kv,
            q_win=q_win,
            enable_virtual_mean=enable_virtual_mean,
            block_valid_len=block_valid_len,
        )

    if q.device.type != "cuda" or not HAS_TRITON:
        return _exact_block_sparse_sdpa_reference(
            q,
            k,
            v,
            scale,
            L_k,
            M_cand,
            M_k,
            cand_cnt,
            cand_idx,
            head_order,
            enable_virtual_mean=enable_virtual_mean,
            k_blk_mean=k_blk_mean,
            v_blk_mean=v_blk_mean,
            tau_k=tau_k,
        )

    L_q, H, D = q.shape
    M_q = (L_q + BLOCK_SIZE - 1) // BLOCK_SIZE
    if out is None:
        out = torch.empty_like(q)
    qk_scale = float(scale) * LOG2_E
    grid = (M_q, H)
    has_meta = meta_branch_gpu is not None

    if enable_virtual_mean:
        k_cap_blks = int(k.shape[0]) // BLOCK_SIZE
        res_cap = (
            512 if (infer_tokens_per_frame(L_q) <= 390 and k_cap_blks <= 512) else 1024
        )
        mc_cap = (
            max(M_cand, min(max(M_cand, k_cap_blks), res_cap)) if has_meta else M_cand
        )
        ws = _get_workspace(
            q.device, num_heads=H, req_m_q=M_q, req_m_cand=max(1, mc_cap)
        )
        if k_blk_mean is None or v_blk_mean is None or tau_k is None:
            k_blk_mean, v_blk_mean, tau_k, _ = compute_kv_block_stats(
                k,
                v,
                num_blocks=M_cand,
                ws=ws,
                meta_m_cand_ptr=meta_branch_gpu[1:2] if has_meta else None,
                m_cand_cap=mc_cap,
            )
        if cand_bitmask is None:
            cand_bitmask = ws.cand_bitmask_flat[: H * M_q * 64].view(H, M_q, 64)
            row_stride = int(cand_idx.shape[-1])
            block_s = (
                512 if row_stride <= 512 else (1024 if row_stride <= 1024 else 2048)
            )
            _zing_build_cand_bitmask_kernel[grid](
                cand_cnt,
                cand_idx,
                meta_branch_gpu if has_meta else cand_cnt,
                cand_bitmask,
                cand_idx.stride(0),
                cand_idx.stride(1),
                cand_bitmask.stride(0),
                cand_bitmask.stride(1),
                M_cand,
                M_k,
                HAS_META_PTR=has_meta,
                BLOCK_S=block_s,
                num_warps=2,
            )

    km_arg = k_blk_mean if (enable_virtual_mean and k_blk_mean is not None) else q
    vm_arg = v_blk_mean if (enable_virtual_mean and v_blk_mean is not None) else q
    tk_arg = tau_k if (enable_virtual_mean and tau_k is not None) else cand_cnt
    cbm_arg = (
        cand_bitmask if (enable_virtual_mean and cand_bitmask is not None) else cand_cnt
    )

    _zing_block_sparse_attn_fwd_kernel[grid](
        q,
        k,
        v,
        out,
        cand_cnt,
        cand_idx,
        head_order,
        meta_branch_gpu if has_meta else cand_cnt,
        km_arg,
        vm_arg,
        tk_arg,
        cbm_arg,
        q.stride(0),
        q.stride(1),
        q.stride(2),
        k.stride(0),
        k.stride(1),
        k.stride(2),
        v.stride(0),
        v.stride(1),
        v.stride(2),
        out.stride(0),
        out.stride(1),
        out.stride(2),
        cand_idx.stride(0),
        cand_idx.stride(1),
        km_arg.stride(0) if enable_virtual_mean else 0,
        km_arg.stride(1) if enable_virtual_mean else 0,
        km_arg.stride(2) if enable_virtual_mean else 0,
        vm_arg.stride(0) if enable_virtual_mean else 0,
        vm_arg.stride(1) if enable_virtual_mean else 0,
        vm_arg.stride(2) if enable_virtual_mean else 0,
        tk_arg.stride(0) if enable_virtual_mean else 0,
        tk_arg.stride(1) if enable_virtual_mean else 0,
        cbm_arg.stride(0) if enable_virtual_mean else 0,
        cbm_arg.stride(1) if enable_virtual_mean else 0,
        L_q,
        L_k,
        M_cand,
        M_k,
        qk_scale,
        float(scale),
        HAS_META_PTR=has_meta,
        ENABLE_VIRTUAL_MEAN=enable_virtual_mean,
        BLOCK_M=BLOCK_SIZE,
        BLOCK_N=BLOCK_SIZE,
        HEAD_DIM=D,
        num_warps=_KERNEL_NUM_WARPS,
        num_stages=_KERNEL_NUM_STAGES,
    )
    return out


class _StaticRouterWorkspace:
    """Pre-allocated static GPU buffers for zero-allocation router & mask storage across 50 layers."""

    def __init__(
        self,
        device: torch.device,
        num_heads: int = NUM_HEADS,
        max_m_q: int = DEFAULT_MAX_M_Q,
        max_m_cand: int = DEFAULT_MAX_M_CAND,
    ):
        self.device = device
        self.num_heads = num_heads
        self.max_m_q = max_m_q
        self.max_m_cand = max_m_cand
        H = num_heads

        self.q_sub_flat = torch.zeros(
            H * (2 * max_m_q * SUB_PER_BLK) * HEAD_DIM,
            dtype=torch.bfloat16,
            device=device,
        )
        self.k_sub_flat = torch.zeros(
            H * (max_m_cand * SUB_PER_BLK) * HEAD_DIM,
            dtype=torch.bfloat16,
            device=device,
        )
        self.q_norm_flat = torch.zeros(
            H * (2 * max_m_q * SUB_PER_BLK),
            dtype=torch.float32,
            device=device,
        )
        self.k_norm_flat = torch.zeros(
            H * (max_m_cand * SUB_PER_BLK),
            dtype=torch.float32,
            device=device,
        )
        self.k_blk_mean_flat = torch.zeros(
            H * max_m_cand * HEAD_DIM,
            dtype=torch.bfloat16,
            device=device,
        )
        self.v_blk_mean_flat = torch.zeros(
            H * max_m_cand * HEAD_DIM,
            dtype=torch.bfloat16,
            device=device,
        )
        self.tau_k_flat = torch.zeros(
            H * max_m_cand,
            dtype=torch.float32,
            device=device,
        )
        self.rho_kv_flat = torch.zeros(
            H * max_m_cand,
            dtype=torch.float32,
            device=device,
        )
        self.cand_bitmask_flat = torch.zeros(
            H * max_m_q * 64,
            dtype=torch.int32,
            device=device,
        )
        self.sub_logits_flat = torch.zeros(
            H * (2 * max_m_q * SUB_PER_BLK) * (max_m_cand * SUB_PER_BLK),
            dtype=torch.bfloat16,
            device=device,
        )
        self.blk_scores_flat = torch.zeros(
            2 * H * max_m_q * max_m_cand,
            dtype=torch.float32,
            device=device,
        )
        self.top_val_flat = torch.zeros(
            2 * H * max_m_q * max_m_cand,
            dtype=torch.float32,
            device=device,
        )
        self.top_idx_flat = torch.zeros(
            2 * H * max_m_q * max_m_cand,
            dtype=torch.int64,
            device=device,
        )
        self.cand_idx_src = torch.zeros(
            (NUM_LAYERS, H, max_m_q, max_m_cand),
            dtype=torch.int32,
            device=device,
        )
        self.cand_idx_s0 = torch.zeros(
            (NUM_LAYERS, H, max_m_q, max_m_cand),
            dtype=torch.int32,
            device=device,
        )
        # Double-buffered (slot 0 used for zero-recapture CUDAGraphs via snapshot restore;
        # slot chunk_id % 2 supported for legacy callers).
        self.cand_idx_s1 = torch.zeros(
            (2, NUM_LAYERS, H, max_m_q, max_m_cand),
            dtype=torch.int32,
            device=device,
        )
        self.skim_idx_src = torch.full(
            (NUM_LAYERS, H, max_m_q, max_m_cand),
            -1,
            dtype=torch.int32,
            device=device,
        )
        self.skim_idx_s0 = torch.full(
            (NUM_LAYERS, H, max_m_q, max_m_cand),
            -1,
            dtype=torch.int32,
            device=device,
        )
        self.skim_idx_s1 = torch.full(
            (2, NUM_LAYERS, H, max_m_q, max_m_cand),
            -1,
            dtype=torch.int32,
            device=device,
        )
        self.skim_cnt_src = torch.zeros(
            (NUM_LAYERS, H),
            dtype=torch.int32,
            device=device,
        )
        self.skim_cnt_s0 = torch.zeros(
            (NUM_LAYERS, H),
            dtype=torch.int32,
            device=device,
        )
        self.skim_cnt_s1 = torch.zeros(
            (2, NUM_LAYERS, H),
            dtype=torch.int32,
            device=device,
        )


def compute_kv_block_stats(
    k: torch.Tensor,
    v: torch.Tensor,
    num_blocks: int | None = None,
    *,
    start_block: int = 0,
    exempt_start: int | None = None,
    ws: _StaticRouterWorkspace | None = None,
    meta_m_cand_ptr: torch.Tensor | None = None,
    m_cand_cap: int | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    """Compute per-block KV mean and second-order variance/cross-variation statistics."""
    device = k.device
    L_k, H, D = k.shape
    if num_blocks is None:
        if exempt_start is not None:
            num_blocks = int(exempt_start) // BLOCK_SIZE
        else:
            num_blocks = L_k // BLOCK_SIZE
    M_cand = max(0, int(num_blocks))
    mc_cap = max(M_cand, int(m_cand_cap) if m_cand_cap is not None else M_cand)
    s_blk = max(0, min(int(start_block), mc_cap))

    if mc_cap == 0:
        empty_mean = torch.empty((H, 0, D), dtype=k.dtype, device=device)
        empty_stat = torch.empty((H, 0), dtype=torch.float32, device=device)
        return empty_mean, empty_mean.clone(), empty_stat, empty_stat.clone()

    if ws is None or mc_cap > ws.max_m_cand or H != ws.num_heads:
        ws = _get_workspace(
            device, num_heads=H, req_m_q=DEFAULT_MAX_M_Q, req_m_cand=mc_cap
        )

    k_blk_mean = ws.k_blk_mean_flat.view(H, ws.max_m_cand, D)[:, :mc_cap, :]
    v_blk_mean = ws.v_blk_mean_flat.view(H, ws.max_m_cand, D)[:, :mc_cap, :]
    tau_k = ws.tau_k_flat.view(H, ws.max_m_cand)[:, :mc_cap]
    rho_kv = ws.rho_kv_flat.view(H, ws.max_m_cand)[:, :mc_cap]

    has_meta = meta_m_cand_ptr is not None
    if device.type == "cuda" and HAS_TRITON:
        num_blks_to_compute = max(0, mc_cap - s_blk)
        if num_blks_to_compute > 0:
            _zing_kv_block_stats_kernel[(num_blks_to_compute, H)](
                k,
                v,
                k_blk_mean,
                v_blk_mean,
                tau_k,
                rho_kv,
                meta_m_cand_ptr if has_meta else tau_k,
                k.stride(0),
                k.stride(1),
                k.stride(2),
                v.stride(0),
                v.stride(1),
                v.stride(2),
                k_blk_mean.stride(0),
                k_blk_mean.stride(1),
                k_blk_mean.stride(2),
                v_blk_mean.stride(0),
                v_blk_mean.stride(1),
                v_blk_mean.stride(2),
                tau_k.stride(0),
                tau_k.stride(1),
                rho_kv.stride(0),
                rho_kv.stride(1),
                s_blk,
                M_cand,
                L_k,
                HAS_META_PTR=has_meta,
                HEAD_DIM=D,
                num_warps=4,
            )
        return (
            k_blk_mean[:, :M_cand] if not has_meta else k_blk_mean,
            v_blk_mean[:, :M_cand] if not has_meta else v_blk_mean,
            tau_k[:, :M_cand] if not has_meta else tau_k,
            rho_kv[:, :M_cand] if not has_meta else rho_kv,
        )

    eff_mc = int(meta_m_cand_ptr.item()) if has_meta else M_cand
    s_eff = min(s_blk, eff_mc)
    if eff_mc > s_eff:
        offs_r = (
            torch.arange(s_eff, eff_mc, device=device)[:, None] * BLOCK_SIZE
            + torch.arange(BLOCK_SIZE, device=device)[None, :]
        ).clamp(max=max(0, L_k - 1))
        k_blks = k[offs_r].float().permute(2, 0, 1, 3)  # [H, eff_mc - s_eff, 64, D]
        v_blks = v[offs_r].float().permute(2, 0, 1, 3)  # [H, eff_mc - s_eff, 64, D]
        km_f = k_blks.mean(dim=2)
        vm_f = v_blks.mean(dim=2)
        k_blk_mean[:, s_eff:eff_mc].copy_(km_f.to(k_blk_mean.dtype))
        v_blk_mean[:, s_eff:eff_mc].copy_(vm_f.to(v_blk_mean.dtype))

        dk = k_blks - km_f.unsqueeze(2)
        dv = v_blks - vm_f.unsqueeze(2)
        dk_sq = (dk * dk).sum(dim=-1)
        dv_sq = (dv * dv).sum(dim=-1)
        tr_sigma_k = dk_sq.mean(dim=-1)
        tr_sigma_v = dv_sq.mean(dim=-1)
        tk_f = tr_sigma_k / (2.0 * float(D))
        cross_kv = (torch.sqrt(dk_sq + 1e-12) * torch.sqrt(dv_sq + 1e-12)).mean(dim=-1)
        v_mean_norm = torch.sqrt((vm_f * vm_f).sum(dim=-1) + 1e-12)
        sigma_v = torch.sqrt(tr_sigma_v + 1e-12)
        rk_f = cross_kv / (float(D) * (v_mean_norm + sigma_v + 1e-5))
        tau_k[:, s_eff:eff_mc].copy_(tk_f)
        rho_kv[:, s_eff:eff_mc].copy_(rk_f)
        if k.dtype != k_blk_mean.dtype and s_eff == 0:
            return (
                km_f.to(k.dtype),
                vm_f.to(v.dtype),
                tau_k[:, :eff_mc],
                rho_kv[:, :eff_mc],
            )

    return (
        k_blk_mean[:, :eff_mc],
        v_blk_mean[:, :eff_mc],
        tau_k[:, :eff_mc],
        rho_kv[:, :eff_mc],
    )


_WORKSPACES: dict[tuple[torch.device, int], _StaticRouterWorkspace] = {}


def get_active_s1_mask_buffer(stores: Any) -> torch.Tensor | None:
    """Return ws.cand_idx_s1[0] for snapshot/restore during CUDAGraph capture."""
    if not stores or len(stores) == 0 or len(stores[0]) == 0:
        return None
    sample_k = stores[0][0]
    if not isinstance(sample_k, torch.Tensor) or sample_k.dim() < 2:
        return None
    ws = _WORKSPACES.get((sample_k.device, int(sample_k.shape[1])))
    if ws is None:
        return None
    return ws.cand_idx_s1[0]


def _get_workspace(
    device: torch.device,
    num_heads: int = NUM_HEADS,
    req_m_q: int = DEFAULT_MAX_M_Q,
    req_m_cand: int = DEFAULT_MAX_M_CAND,
) -> _StaticRouterWorkspace:
    key = (device, num_heads)
    ws = _WORKSPACES.get(key)
    if (
        ws is None
        or req_m_q > ws.max_m_q
        or req_m_cand > ws.max_m_cand
        or num_heads != ws.num_heads
    ):
        if (
            device.type == "cuda"
            and torch.cuda.is_available()
            and torch.cuda.is_current_stream_capturing()
        ):
            raise RuntimeError(
                f"_StaticRouterWorkspace capacity exceeded during stream capture: "
                f"need ({num_heads}, {req_m_q}, {req_m_cand}) vs "
                f"({ws.num_heads if ws else 0}, {ws.max_m_q if ws else 0}, {ws.max_m_cand if ws else 0})"
            )
        had_ws = ws is not None
        new_mq = max(DEFAULT_MAX_M_Q, req_m_q, ws.max_m_q if ws else 0)
        new_mc = max(DEFAULT_MAX_M_CAND, req_m_cand, ws.max_m_cand if ws else 0)
        ws = _StaticRouterWorkspace(
            device, num_heads=num_heads, max_m_q=new_mq, max_m_cand=new_mc
        )
        _WORKSPACES[key] = ws
        if had_ws:
            clear_sparse_caches()
    return ws


@dataclass
class PrebuiltSparseMask:
    L_q: int
    L_k: int
    M_q: int
    M_k: int
    M_cand: int
    cand_cnt: torch.Tensor
    cand_idx: torch.Tensor
    head_order: torch.Tensor
    active_ratio: float
    k_blk_mean: torch.Tensor | None = None
    v_blk_mean: torch.Tensor | None = None
    tau_k: torch.Tensor | None = None
    skim_cnt: torch.Tensor | None = None
    skim_idx: torch.Tensor | None = None
    compressed_kv: dict[str, torch.Tensor] | None = None


@dataclass
class HeadBudgetSpec:
    k_cand_gpu: torch.Tensor
    num_full_gpu: torch.Tensor
    head_order_gpu: torch.Tensor
    K_max: int
    M_full_cur: int
    is_dense: bool
    active_ratio: float


@dataclass
class SparseBranchSpec:
    mode: str
    tau: str
    case_id: str
    chunk_id: int
    b_phase: str
    step_idx: int
    step_1000: int
    q_start: int
    q_stop: int
    L_q: int
    L_k: int
    s_cur_chunk: int
    M_q: int
    M_k: int
    M_cand: int
    M_cur: int
    M_prefix: int
    safety_scale: float = 1.0
    s_evict: int = 0
    L_evict: int = 0
    s_cur_chunk_step1: int = 0
    L_k_step1: int = 0
    M_k_step1: int = 0
    M_cand_step1: int = 0
    M_cur_step1: int = 0
    companion_step0_spec: SparseBranchSpec | None = None
    record_layer_events: bool = False
    blk_kind_sig: tuple[Any, ...] | None = None

    @property
    def block_kinds_sig(self) -> tuple[Any, ...]:
        return self.blk_kind_sig if self.blk_kind_sig is not None else ()


_BUDGET_CACHE: dict[tuple[Any, ...], HeadBudgetSpec] = {}
_STEP0_READY_MASKS: dict[tuple[int, int], PrebuiltSparseMask] = {}
_STEP1_READY_MASKS: dict[tuple[int, int], PrebuiltSparseMask] = {}
_STEP0_PARITY_MASKS: dict[tuple[int, int, int], PrebuiltSparseMask] = {}
_STEP1_PARITY_MASKS: dict[tuple[int, int, int], PrebuiltSparseMask] = {}


def clear_sparse_caches():
    _STEP0_READY_MASKS.clear()
    _STEP1_READY_MASKS.clear()
    _STEP0_PARITY_MASKS.clear()
    _STEP1_PARITY_MASKS.clear()
    _LAST_STEP1_NUM_FULL.clear()


def _get_ratio_tensor(step_key: str, tau: str) -> torch.Tensor:
    """Return cached [NUM_LAYERS, NUM_HEADS] float64 CPU tensor of head budget ratios."""
    tau_key = "0.90" if ("090" in tau or "0.90" in tau) else "0.95"
    norm_step = step_key if step_key in HEAD_BUDGET_RATIOS else "target_t1000"
    cache_key = (norm_step, tau_key)
    t = _RATIO_TENSOR_CACHE.get(cache_key)
    if t is None:
        t = torch.tensor(HEAD_BUDGET_RATIOS[norm_step][tau_key], dtype=torch.float64)
        _RATIO_TENSOR_CACHE[cache_key] = t
    return t


def _compute_vectorized_k_cand_cpu(
    step_key: str,
    tau: str,
    M_cand: int,
    M_prefix: int,
    M_q: int,
    safety_scale: float,
    head_start: int,
    num_heads: int,
) -> torch.Tensor:
    """Compute [NUM_LAYERS, num_heads] int32 k_cand tensor on CPU across all 50 layers."""
    if M_cand <= 0:
        return torch.zeros((NUM_LAYERS, num_heads), dtype=torch.int32)
    ratios_2d = _get_ratio_tensor(step_key, tau)[:, head_start : head_start + num_heads]
    if M_prefix > 0:
        steady_win_blks = 12 * max(1, M_q)
        eff_M_cand = min(M_prefix, M_cand) + max(
            max(0, M_cand - M_prefix), steady_win_blks
        )
    else:
        eff_M_cand = M_cand
    kc = (
        torch.ceil(ratios_2d * (float(eff_M_cand) * float(safety_scale)))
        .to(torch.int32)
        .clamp(
            min=min(MIN_CAND_BLOCKS_PER_HEAD, M_cand),
            max=max(1, M_cand),
        )
    )
    kc[0].zero_()
    return kc


def _get_head_budget_spec(
    device: torch.device,
    step_key: str,
    tau: str,
    layer_idx: int,
    M_k: int,
    M_cand: int,
    M_cur: int,
    safety_scale: float = 1.0,
    head_start: int = 0,
    num_heads: int = NUM_HEADS,
    M_prefix: int = 0,
    M_q: int = 13,
) -> HeadBudgetSpec:
    """Return cached per-head candidate budget tensors on device with resolution-proportional scaling."""
    key = (
        device,
        step_key,
        tau,
        layer_idx,
        M_k,
        M_cand,
        M_cur,
        round(safety_scale, 4),
        head_start,
        num_heads,
        M_prefix,
        M_q,
    )
    cached = _BUDGET_CACHE.get(key)
    if cached is not None:
        return cached

    M_full_cur = max(0, M_k - 1 - M_cand)
    if layer_idx == 0 or M_cand <= 8:
        dummy = torch.empty(0, dtype=torch.int32, device=device)
        res = HeadBudgetSpec(dummy, dummy, dummy, M_cand, M_full_cur, True, 1.0)
        _BUDGET_CACHE[key] = res
        return res

    tau_key = "0.90" if ("090" in tau or "0.90" in tau) else "0.95"
    step_dict = HEAD_BUDGET_RATIOS.get(step_key, HEAD_BUDGET_RATIOS["target_t1000"])
    ratios = step_dict[tau_key][layer_idx][head_start : head_start + num_heads]
    if M_prefix > 0:
        steady_win_blks = 12 * max(1, M_q)
        eff_M_cand = min(M_prefix, M_cand) + max(
            max(0, M_cand - M_prefix), steady_win_blks
        )
    else:
        eff_M_cand = M_cand

    k_cand_list = []
    for r in ratios:
        kc = int(math.ceil(r * eff_M_cand * safety_scale))
        kc = max(MIN_CAND_BLOCKS_PER_HEAD, min(M_cand, kc))
        k_cand_list.append(kc)

    K_max = max(k_cand_list)
    mean_total = (sum(k_cand_list) / float(num_heads)) + M_cur
    active_ratio = mean_total / float(max(1, M_k))
    mean_base_ratio = (sum(ratios) / float(max(1, len(ratios)))) * safety_scale
    if mean_base_ratio >= 0.92:
        dummy = torch.empty(0, dtype=torch.int32, device=device)
        res = HeadBudgetSpec(dummy, dummy, dummy, M_cand, M_full_cur, True, 1.0)
        _BUDGET_CACHE[key] = res
        return res

    head_order_list = sorted(range(num_heads), key=lambda h: ratios[h], reverse=True)
    num_full_list = [M_full_cur + kc for kc in k_cand_list]
    k_cand_gpu = torch.tensor(k_cand_list, dtype=torch.int32, device=device)
    num_full_gpu = torch.tensor(num_full_list, dtype=torch.int32, device=device)
    head_order_gpu = torch.tensor(head_order_list, dtype=torch.int32, device=device)

    res = HeadBudgetSpec(
        k_cand_gpu=k_cand_gpu,
        num_full_gpu=num_full_gpu,
        head_order_gpu=head_order_gpu,
        K_max=K_max,
        M_full_cur=M_full_cur,
        is_dense=False,
        active_ratio=active_ratio,
    )
    if len(_BUDGET_CACHE) >= 65536:
        _BUDGET_CACHE.clear()
    _BUDGET_CACHE[key] = res
    return res


def fused_route_and_build_masks(
    q_first: torch.Tensor,
    q_second: torch.Tensor | None,
    k: torch.Tensor,
    layer_idx: int,
    tau: str,
    L_q: int,
    M_q: int,
    M_cand: int,
    M_prefix: int,
    safety_scale: float,
    build_src: bool,
    L_k_src: int,
    M_k_src: int,
    M_cur_src: int,
    build_s0: bool,
    L_k_s0: int,
    M_k_s0: int,
    M_cur_s0: int,
    build_s1: bool,
    s_evict: int,
    L_k_s1: int,
    M_k_s1: int,
    M_cand_s1: int,
    M_cur_s1: int,
    *,
    head_start: int = 0,
    num_heads: int | None = None,
    s1_parity: int = 0,
    L_evict: int = 0,
    blk_kind_sig: tuple[Any, ...] | None = None,
    sparse_meta_gpu: torch.Tensor | None = None,
    sparse_blk_kind_gpu: torch.Tensor | None = None,
    sparse_k_cand_gpu: torch.Tensor | None = None,
    sparse_num_full_gpu: torch.Tensor | None = None,
    k_cand_src_gpu: torch.Tensor | None = None,
    num_full_src_gpu: torch.Tensor | None = None,
    k_cand_s0_gpu: torch.Tensor | None = None,
    num_full_s0_gpu: torch.Tensor | None = None,
    k_cand_s1_gpu: torch.Tensor | None = None,
    num_full_s1_gpu: torch.Tensor | None = None,
    src_branch_idx: int = 1,
    s0_branch_idx: int = 2,
    v: torch.Tensor | None = None,
    k_blk_mean: torch.Tensor | None = None,
    v_blk_mean: torch.Tensor | None = None,
    tau_k: torch.Tensor | None = None,
    rho_kv: torch.Tensor | None = None,
    enable_triage_score: bool = False,
    enable_virtual_mean: bool = False,
    price_pi: float = 0.0,
    fast_pi_filter: bool = True,
    enable_three_tier: bool = False,
    c_rf: float = 12.0,
    alpha_triage: float = 0.22,
    compressed_kv: dict[str, torch.Tensor] | None = None,
) -> tuple[
    PrebuiltSparseMask | None, PrebuiltSparseMask | None, PrebuiltSparseMask | None
]:
    """Run Fused Triton Router once and populate static masks for (source_t0, active_t1000, active_t500/final_t1)."""
    device = q_first.device
    H = q_first.shape[1] if num_heads is None else num_heads
    has_meta = sparse_meta_gpu is not None and sparse_meta_gpu.numel() >= 16

    if has_meta and (device.type != "cuda" or not HAS_TRITON):
        M_cand = int(sparse_meta_gpu[META_M_CAND].item())
        M_prefix = int(sparse_meta_gpu[META_M_PREFIX].item())
        if build_src:
            L_k_src = int(sparse_meta_gpu[META_L_K_SRC].item())
            M_k_src = int(sparse_meta_gpu[META_M_K_SRC].item())
            M_cur_src = M_k_src - M_cand
        if build_s0:
            L_k_s0 = int(sparse_meta_gpu[META_L_K_S0].item())
            M_k_s0 = int(sparse_meta_gpu[META_M_K_S0].item())
            M_cur_s0 = M_k_s0 - M_cand
        if build_s1:
            L_k_s1 = int(sparse_meta_gpu[META_L_K_S1].item())
            M_k_s1 = int(sparse_meta_gpu[META_M_K_S1].item())
            M_cand_s1 = int(sparse_meta_gpu[META_M_CAND_S1].item())
            M_cur_s1 = M_k_s1 - M_cand_s1

    k_cap_blks = int(k.shape[0]) // BLOCK_SIZE
    res_cap = (
        512 if (infer_tokens_per_frame(L_q) <= 390 and k_cap_blks <= 512) else 1024
    )
    M_cand_cap = (
        max(M_cand, min(max(M_cand, k_cap_blks), res_cap)) if has_meta else M_cand
    )

    ws = _get_workspace(
        device,
        num_heads=H,
        req_m_q=M_q,
        req_m_cand=max(M_cand_cap, M_cand, M_k_s0, M_k_src),
    )

    b_src = (
        _get_head_budget_spec(
            device,
            "source_t0",
            tau,
            layer_idx,
            M_k_src,
            M_cand,
            M_cur_src,
            safety_scale,
            head_start=head_start,
            num_heads=H,
            M_prefix=M_prefix,
            M_q=M_q,
        )
        if build_src
        else None
    )
    b_s0 = (
        _get_head_budget_spec(
            device,
            "target_t1000",
            tau,
            layer_idx,
            M_k_s0,
            M_cand,
            M_cur_s0,
            safety_scale,
            head_start=head_start,
            num_heads=H,
            M_prefix=M_prefix,
            M_q=M_q,
        )
        if build_s0
        else None
    )
    eff_l_evict = (
        L_evict if L_evict > 0 else (max(0, L_k_s0 - L_k_s1) if build_s1 else 0)
    )
    shift_s1_est = (
        (eff_l_evict + (BLOCK_SIZE // 2)) // BLOCK_SIZE
        if (build_s1 and eff_l_evict > 0)
        else 0
    )
    eff_M_cand_s1 = min(M_cand_s1, max(0, M_cand - shift_s1_est))

    b_s1 = (
        _get_head_budget_spec(
            device,
            "target_t500",
            tau,
            layer_idx,
            M_k_s1,
            eff_M_cand_s1,
            M_cur_s1 + (M_cand_s1 - eff_M_cand_s1),
            safety_scale,
            head_start=head_start,
            num_heads=H,
            M_prefix=min(M_prefix, eff_M_cand_s1),
            M_q=M_q,
        )
        if (build_s1 and (eff_M_cand_s1 > 8 or has_meta))
        else None
    )

    write_src = b_src is not None and not b_src.is_dense
    write_s0 = b_s0 is not None and not b_s0.is_dense
    write_s1 = b_s1 is not None and not b_s1.is_dense

    if not (write_src or write_s0 or write_s1):
        return None, None, None

    if compressed_kv is not None:
        if k_blk_mean is None:
            k_blk_mean = compressed_kv.get("k_blk_mean")
        if v_blk_mean is None:
            v_blk_mean = compressed_kv.get("v_blk_mean")
        if rho_kv is None:
            rho_kv = compressed_kv.get("rho_kv")
        if tau_k is None:
            tau_k = compressed_kv.get("tau_k")
        if (
            rho_kv is None
            and "sigma_k_sq" in compressed_kv
            and "sigma_v" in compressed_kv
        ):
            rho_kv = (
                torch.sqrt(compressed_kv["sigma_k_sq"].clamp_min(0.0))
                * compressed_kv["sigma_v"]
                / float(HEAD_DIM)
            )

    need_triage = (enable_triage_score or enable_three_tier) and (
        tau_k is None or rho_kv is None
    )
    need_vm = (enable_virtual_mean or enable_three_tier) and (
        k_blk_mean is None or v_blk_mean is None or tau_k is None
    )
    if need_triage or need_vm:
        if v is None:
            if need_triage:
                raise ValueError(
                    "v or (tau_k, rho_kv) must be provided when enable_triage_score=True."
                )
        else:
            k_blk_mean, v_blk_mean, tau_k, rho_kv = compute_kv_block_stats(
                k,
                v,
                num_blocks=M_cand,
                ws=ws,
                meta_m_cand_ptr=sparse_meta_gpu[0:1] if has_meta else None,
                m_cand_cap=M_cand_cap,
            )

    has_pair = q_second is not None
    n_mult = 2 if has_pair else 1
    total_heads = n_mult * H
    M_q_sub = M_q * SUB_PER_BLK
    M_cand_sub = M_cand * SUB_PER_BLK
    M_cand_cap_sub = M_cand_cap * SUB_PER_BLK

    q_sub = ws.q_sub_flat[: H * (n_mult * M_q_sub) * HEAD_DIM].view(
        H, n_mult * M_q_sub, HEAD_DIM
    )
    k_sub = ws.k_sub_flat[: H * M_cand_cap_sub * HEAD_DIM].view(
        H, M_cand_cap_sub, HEAD_DIM
    )
    q_norm = ws.q_norm_flat[: H * (n_mult * M_q_sub)].view(H, n_mult * M_q_sub)
    k_norm = ws.k_norm_flat[: H * M_cand_cap_sub].view(H, M_cand_cap_sub)
    sub_logits = ws.sub_logits_flat[: H * (n_mult * M_q_sub) * M_cand_cap_sub].view(
        H, n_mult * M_q_sub, M_cand_cap_sub
    )
    blk_scores = ws.blk_scores_flat[: total_heads * M_q * M_cand_cap].view(
        total_heads, M_q, M_cand_cap
    )

    q_act_in = q_second if has_pair else q_first

    if device.type == "cuda" and HAS_TRITON:
        _zing_subblock16_pool_q_pair_kernel[(M_q_sub, H)](
            q_first,
            q_act_in,
            q_sub,
            q_norm,
            q_first.stride(0),
            q_first.stride(1),
            q_first.stride(2),
            q_act_in.stride(0),
            q_act_in.stride(1),
            q_act_in.stride(2),
            q_sub.stride(0),
            q_sub.stride(1),
            q_sub.stride(2),
            q_norm.stride(0),
            q_norm.stride(1),
            L_q,
            M_q_sub,
            HAS_PAIR=has_pair,
            HEAD_DIM=HEAD_DIM,
            num_warps=2,
        )
        _zing_subblock16_pool_k_kernel[(M_cand_cap_sub, H)](
            k,
            k_sub,
            k_norm,
            sparse_meta_gpu if has_meta else k_norm,
            k.stride(0),
            k.stride(1),
            k.stride(2),
            k_sub.stride(0),
            k_sub.stride(1),
            k_sub.stride(2),
            k_norm.stride(0),
            k_norm.stride(1),
            M_cand,
            HAS_META_PTR=has_meta,
            HEAD_DIM=HEAD_DIM,
            SUB_SAMPLES=_K_POOL_SUB_SAMPLES,
            SUB_STEP=_K_POOL_SUB_STEP,
            num_warps=2,
        )
        torch.bmm(q_sub, k_sub.transpose(1, 2), out=sub_logits)

        blk_kind_gpu = (
            sparse_blk_kind_gpu
            if (has_meta and sparse_blk_kind_gpu is not None)
            else _get_blk_kind_gpu(device, M_cand, M_prefix, blk_kind_sig)
        )
        block_c = 512 if M_cand_cap <= 512 else (1024 if M_cand_cap <= 1024 else 2048)
        tk_arg = tau_k if (enable_triage_score and tau_k is not None) else k_norm
        rk_arg = rho_kv if (enable_triage_score and rho_kv is not None) else k_norm
        _zing_reduce_4x4_dualpool_kernel[(M_q, H)](
            sub_logits,
            blk_scores,
            q_norm,
            k_norm,
            blk_kind_gpu,
            sparse_meta_gpu if has_meta else blk_kind_gpu,
            tk_arg,
            rk_arg,
            sub_logits.stride(0),
            sub_logits.stride(1),
            sub_logits.stride(2),
            blk_scores.stride(0),
            blk_scores.stride(1),
            blk_scores.stride(2),
            q_norm.stride(0),
            q_norm.stride(1),
            k_norm.stride(0),
            k_norm.stride(1),
            tk_arg.stride(0) if enable_triage_score else 0,
            tk_arg.stride(1) if enable_triage_score else 0,
            rk_arg.stride(0) if enable_triage_score else 0,
            rk_arg.stride(1) if enable_triage_score else 0,
            M_q_sub,
            M_cand,
            M_prefix,
            M_cand_cap,
            H,
            HAS_META_PTR=has_meta,
            HAS_PAIR=has_pair,
            HAS_TRIAGE=enable_triage_score,
            BLOCK_C=block_c,
            num_warps=4,
        )
    else:
        # High-precision CPU reference for test/CPU environments
        offs_rq = (
            torch.arange(M_q_sub, device=device)[:, None] * 16
            + torch.arange(16, device=device)[None, :]
        ).clamp(max=L_q - 1)
        q1_sub = q_first[offs_rq].mean(dim=1).permute(1, 0, 2)
        q1_norm = torch.rsqrt((q1_sub.float() ** 2).sum(dim=-1) + 1e-6)
        if has_pair:
            q2_sub = q_act_in[offs_rq].mean(dim=1).permute(1, 0, 2)
            q2_norm = torch.rsqrt((q2_sub.float() ** 2).sum(dim=-1) + 1e-6)
            q_sub_ref = torch.cat([q1_sub, q2_sub], dim=1)
            q_norm_ref = torch.cat([q1_norm, q2_norm], dim=1)
        else:
            q_sub_ref = q1_sub
            q_norm_ref = q1_norm

        offs_rk = (
            torch.arange(M_cand_sub, device=device)[:, None] * 16
            + torch.arange(16, device=device)[None, :]
        ).clamp(max=k.shape[0] - 1)
        k_sub_ref = k[offs_rk].mean(dim=1).permute(1, 0, 2)
        k_norm_ref = torch.rsqrt((k_sub_ref.float() ** 2).sum(dim=-1) + 1e-6)

        logits_ref = torch.bmm(q_sub_ref, k_sub_ref.transpose(1, 2))
        sub_logits[:, :, :M_cand_sub].copy_(logits_ref)
        cos_ref = logits_ref.float() * q_norm_ref.unsqueeze(2) * k_norm_ref.unsqueeze(1)

        logits_5d = logits_ref.view(H, n_mult, M_q, 4, M_cand, 4)
        s_5d = logits_5d.float().max(dim=5).values.max(dim=3).values
        s0 = s_5d[:, 0]

        cos_5d = cos_ref.view(H, n_mult, M_q, 4, M_cand, 4)
        c_5d = cos_5d.float().max(dim=5).values.max(dim=3).values
        c0 = c_5d[:, 0]

        if has_meta and sparse_blk_kind_gpu is not None:
            blk_kind = sparse_blk_kind_gpu[:M_cand]
        else:
            blk_kind = _get_blk_kind_gpu(device, M_cand, M_prefix, blk_kind_sig)
        is_ref = blk_kind == KIND_REF_VIS
        is_sink = blk_kind == KIND_SINK
        is_wsrc = blk_kind == KIND_WIN_SRC
        is_wfin = blk_kind == KIND_WIN_FIN
        is_win = is_wsrc | is_wfin

        n_win = is_win.sum().item()
        m_w0 = (
            is_win if n_win >= 4 else (torch.arange(M_cand, device=device) >= M_prefix)
        )
        n_w0 = max(1.0, float(m_w0.sum().item()))

        mu_w0 = (s0 * m_w0).sum(dim=-1, keepdim=True) / n_w0
        dw0 = torch.where(m_w0, s0 - mu_w0, torch.zeros_like(s0))
        std_w0 = torch.sqrt((dw0 * dw0).sum(dim=-1, keepdim=True) / n_w0 + 1e-6)

        mu_cw0 = (c0 * m_w0).sum(dim=-1, keepdim=True) / n_w0
        dcw0 = torch.where(m_w0, c0 - mu_cw0, torch.zeros_like(c0))
        std_cw0 = torch.sqrt((dcw0 * dcw0).sum(dim=-1, keepdim=True) / n_w0 + 1e-6)

        n_r = is_ref.sum().item()
        n_rf = max(1.0, float(n_r))
        has_ref0 = (n_r >= 2) and (n_w0 >= 4.0)
        if has_ref0:
            mu_r0 = (s0 * is_ref).sum(dim=-1, keepdim=True) / n_rf
            dr0 = torch.where(is_ref, s0 - mu_r0, torch.zeros_like(s0))
            std_r0 = torch.sqrt((dr0 * dr0).sum(dim=-1, keepdim=True) / n_rf + 1e-6)

            mu_cr0 = (c0 * is_ref).sum(dim=-1, keepdim=True) / n_rf
            dcr0 = torch.where(is_ref, c0 - mu_cr0, torch.zeros_like(c0))
            std_cr0 = torch.sqrt((dcr0 * dcr0).sum(dim=-1, keepdim=True) / n_rf + 1e-6)

            c_thr0 = torch.clamp(
                torch.minimum(mu_cr0 - 1.15 * std_cr0, mu_cw0 - 1.10 * std_cw0),
                min=0.05,
            )
            gate_r0 = torch.clamp((c0 - c_thr0) / (std_cr0 + 1e-4), 0.0, 1.0)
            shift_r0 = torch.minimum(torch.clamp(mu_w0 - mu_r0, min=0.0), 1.25 * std_w0)
            scale_r0 = torch.clamp(std_w0 / std_r0, 1.0, 1.25)
            boost_r0 = torch.clamp(shift_r0 + (s0 - mu_r0) * (scale_r0 - 1.0), min=0.0)
            s0_cal = torch.where(is_ref, s0 + gate_r0 * boost_r0, s0)
        else:
            s0_cal = s0
            mu_cr0 = torch.zeros_like(mu_w0)

        std_cw0_eff = torch.clamp(std_cw0, min=0.05)
        z_c0 = (c0 - mu_cw0) / (std_cw0_eff + 1e-4)
        d0_sink = torch.clamp(-0.35 - z_c0, 0.0, 2.0)
        g0_sink = torch.clamp(d0_sink / 0.65, 0.0, 1.0)
        ev0_sink = mu_w0 - (1.5 + 2.0 * d0_sink) * std_w0
        s0_sink = (1.0 - g0_sink) * s0_cal + g0_sink * torch.minimum(s0_cal, ev0_sink)
        ev0_s = (n_win >= 4) & is_sink & (c0 < 0.05) & (z_c0 < -0.35)
        s0_cal = torch.where(ev0_s, s0_sink, s0_cal)
        if has_ref0:
            d0_ref = torch.clamp(-0.50 - z_c0, 0.0, 2.0)
            g0_ref = torch.clamp(d0_ref / 0.70, 0.0, 1.0)
            ev0_ref = mu_w0 - (1.25 + 1.75 * d0_ref) * std_w0
            s0_ref = (1.0 - g0_ref) * s0_cal + g0_ref * torch.minimum(s0_cal, ev0_ref)
            ev0_r = is_ref & (c0 < 0.05) & (c0 < mu_cr0) & (z_c0 < -0.50)
            s0_cal = torch.where(ev0_r, s0_ref, s0_cal)
        else:
            ev0_r = torch.zeros_like(ev0_s)
        ev0 = ev0_s | ev0_r | (is_ref & (c0 < 0.0))
        ch0 = is_ref & (c0 > 0.05)

        if enable_triage_score and tau_k is not None and rho_kv is not None:
            q0_rms_sq = (q1_sub.float() ** 2).sum(dim=-1).view(
                H, M_q, SUB_PER_BLK
            ).mean(dim=-1, keepdim=True) / float(HEAD_DIM)
            j0 = torch.clamp(q0_rms_sq * tau_k[:, :M_cand].unsqueeze(1), max=4.0)
            r0 = torch.clamp(
                torch.sqrt(q0_rms_sq) * rho_kv[:, :M_cand].unsqueeze(1), max=4.0
            )
            comp0 = j0 + r0 + 0.05
            comp0 = torch.where(
                ev0,
                torch.full_like(comp0, 0.05),
                torch.where(ch0, torch.clamp(comp0, min=1.0), comp0),
            )
            s0_cal = s0_cal * comp0

        blk_scores.fill_(-1.0e30)
        if has_pair:
            s1 = s_5d[:, 1]
            c1 = c_5d[:, 1]
            n_wfin = is_wfin.sum().item()
            if n_wfin >= 4:
                m_w1 = is_wfin
            elif n_win >= 4:
                m_w1 = is_win
            else:
                m_w1 = torch.arange(M_cand, device=device) >= M_prefix
            n_w1 = max(1.0, float(m_w1.sum().item()))

            mu_w1 = (s1 * m_w1).sum(dim=-1, keepdim=True) / n_w1
            dw1 = torch.where(m_w1, s1 - mu_w1, torch.zeros_like(s1))
            std_w1 = torch.sqrt((dw1 * dw1).sum(dim=-1, keepdim=True) / n_w1 + 1e-6)

            mu_cw1 = (c1 * m_w1).sum(dim=-1, keepdim=True) / n_w1
            dcw1 = torch.where(m_w1, c1 - mu_cw1, torch.zeros_like(c1))
            std_cw1 = torch.sqrt((dcw1 * dcw1).sum(dim=-1, keepdim=True) / n_w1 + 1e-6)

            has_ref1 = (n_r >= 2) and (n_w1 >= 4.0)
            if has_ref1:
                mu_r1 = (s1 * is_ref).sum(dim=-1, keepdim=True) / n_rf
                dr1 = torch.where(is_ref, s1 - mu_r1, torch.zeros_like(s1))
                std_r1 = torch.sqrt((dr1 * dr1).sum(dim=-1, keepdim=True) / n_rf + 1e-6)

                mu_cr1 = (c1 * is_ref).sum(dim=-1, keepdim=True) / n_rf
                dcr1 = torch.where(is_ref, c1 - mu_cr1, torch.zeros_like(c1))
                std_cr1 = torch.sqrt(
                    (dcr1 * dcr1).sum(dim=-1, keepdim=True) / n_rf + 1e-6
                )

                c_thr1 = torch.clamp(
                    torch.minimum(mu_cr1 - 1.15 * std_cr1, mu_cw1 - 1.10 * std_cw1),
                    min=0.05,
                )
                gate_r1 = torch.clamp((c1 - c_thr1) / (std_cr1 + 1e-4), 0.0, 1.0)
                shift_r1 = torch.minimum(
                    torch.clamp(mu_w1 - mu_r1, min=0.0), 1.25 * std_w1
                )
                scale_r1 = torch.clamp(std_w1 / std_r1, 1.0, 1.25)
                boost_r1 = torch.clamp(
                    shift_r1 + (s1 - mu_r1) * (scale_r1 - 1.0), min=0.0
                )
                s1_cal = torch.where(is_ref, s1 + gate_r1 * boost_r1, s1)
            else:
                s1_cal = s1
                mu_cr1 = torch.zeros_like(mu_w1)

            std_cw1_eff = torch.clamp(std_cw1, min=0.05)
            z_c1 = (c1 - mu_cw1) / (std_cw1_eff + 1e-4)
            has_dual_decay = (n_win >= 4) and (n_w1 >= 4.0) and (n_w0 >= 4.0)
            if has_dual_decay:
                z_c_sink = torch.minimum(z_c0, 0.25 * z_c1 + 0.75 * z_c0)
                d1_sink = torch.clamp(-0.35 - z_c_sink, 0.0, 2.0)
                g1_sink = torch.clamp(d1_sink / 0.65, 0.0, 1.0)
                ev1_sink = mu_w1 - (1.5 + 2.0 * d1_sink) * std_w1
                s1_sink = (1.0 - g1_sink) * s1_cal + g1_sink * torch.minimum(
                    s1_cal, ev1_sink
                )
                ev1_s = is_sink & ((c0 < 0.05) | (c1 < 0.05)) & (z_c_sink < -0.35)
                s1_cal = torch.where(ev1_s, s1_sink, s1_cal)
                if has_ref1:
                    z_c_ref = torch.minimum(z_c0, 0.40 * z_c1 + 0.60 * z_c0)
                    d1_ref = torch.clamp(-0.50 - z_c_ref, 0.0, 2.0)
                    g1_ref = torch.clamp(d1_ref / 0.70, 0.0, 1.0)
                    ev1_ref = mu_w1 - (1.25 + 1.75 * d1_ref) * std_w1
                    s1_ref = (1.0 - g1_ref) * s1_cal + g1_ref * torch.minimum(
                        s1_cal, ev1_ref
                    )
                    ev1_r = (
                        is_ref
                        & ((c0 < 0.05) | (c1 < 0.05))
                        & (c1 < mu_cr1)
                        & (z_c_ref < -0.50)
                    )
                    s1_cal = torch.where(ev1_r, s1_ref, s1_cal)
                else:
                    ev1_r = torch.zeros_like(ev1_s)
            else:
                ev1_s = torch.zeros_like(z_c1, dtype=torch.bool)
                ev1_r = torch.zeros_like(z_c1, dtype=torch.bool)
            ev1 = ev1_s | ev1_r | (is_ref & ((c1 < 0.0) | (c0 < 0.0)))
            ch1 = is_ref & ((c1 > 0.05) | (c0 > 0.05))

            mu_s0_w = (s0_cal * m_w0).sum(dim=-1, keepdim=True) / n_w0
            ds0_w = torch.where(m_w0, s0_cal - mu_s0_w, torch.zeros_like(s0_cal))
            std_s0_w = torch.sqrt(
                (ds0_w * ds0_w).sum(dim=-1, keepdim=True) / n_w0 + 1e-6
            )

            s0_on_w1 = mu_w1 + (s0_cal - mu_s0_w) * (std_w1 / std_s0_w)
            s_wsrc = torch.maximum(s1_cal, 0.35 * s1_cal + 0.65 * s0_on_w1)
            s_wfin = torch.maximum(s1_cal, 0.80 * s1_cal + 0.20 * s0_on_w1)
            s_sink = torch.maximum(s1_cal, 0.65 * s1_cal + 0.35 * s0_on_w1)
            s_ref = torch.maximum(s1_cal, 0.50 * s1_cal + 0.50 * s0_on_w1)
            s_act = torch.where(
                is_wsrc,
                s_wsrc,
                torch.where(
                    is_wfin,
                    s_wfin,
                    torch.where(
                        is_sink & (~ev1_s),
                        s_sink,
                        torch.where(ch1 & (~ev1), s_ref, s1_cal),
                    ),
                ),
            )

            if enable_triage_score and tau_k is not None and rho_kv is not None:
                q1_rms_sq = (q2_sub.float() ** 2).sum(dim=-1).view(
                    H, M_q, SUB_PER_BLK
                ).mean(dim=-1, keepdim=True) / float(HEAD_DIM)
                j1 = torch.clamp(q1_rms_sq * tau_k[:, :M_cand].unsqueeze(1), max=4.0)
                r1 = torch.clamp(
                    torch.sqrt(q1_rms_sq) * rho_kv[:, :M_cand].unsqueeze(1), max=4.0
                )
                comp1 = j1 + r1 + 0.05
                comp1 = torch.where(
                    ev1,
                    torch.full_like(comp1, 0.05),
                    torch.where(ch1, torch.clamp(comp1, min=1.0), comp1),
                )
                s_act = s_act * comp1

            blk_scores[:H, :, :M_cand].copy_(s0_cal)
            blk_scores[H : 2 * H, :, :M_cand].copy_(s_act)
        else:
            blk_scores[:H, :, :M_cand].copy_(s0_cal)

    if has_meta and (device.type != "cuda" or not HAS_TRITON):
        b_evict_lo = int(sparse_meta_gpu[META_B_EVICT_LO].item())
        b_evict_hi = int(sparse_meta_gpu[META_B_EVICT_HI].item())
        shift_s1 = int(sparse_meta_gpu[META_SHIFT_S1].item())
    else:
        eff_l_evict = (
            L_evict if L_evict > 0 else (max(0, L_k_s0 - L_k_s1) if write_s1 else 0)
        )
        if write_s1 and eff_l_evict > 0:
            shift_s1 = (eff_l_evict + (BLOCK_SIZE // 2)) // BLOCK_SIZE
            b_evict_lo = min(M_cand_s1, s_evict // BLOCK_SIZE)
            b_evict_hi = b_evict_lo + shift_s1
        else:
            shift_s1 = 0
            b_evict_lo = M_cand
            b_evict_hi = M_cand

    if has_meta:
        K_top = M_cand_cap
    elif enable_three_tier:
        K_top = max(1, M_cand)
    else:
        req_k = 0
        if write_src and b_src is not None:
            req_k = max(req_k, b_src.K_max)
        if write_s0 and b_s0 is not None:
            req_k = max(req_k, b_s0.K_max)
        if write_s1 and b_s1 is not None:
            max_discard = max(shift_s1, max(0, M_cand - M_cand_s1))
            req_k = max(req_k, b_s1.K_max + max_discard + 16)
        K_top = min(M_cand, max(1, req_k))

    out_src_buf = ws.cand_idx_src[layer_idx, :H]
    out_s0_buf = ws.cand_idx_s0[layer_idx, :H]
    out_s1_buf = ws.cand_idx_s1[s1_parity % 2, layer_idx, :H]

    s1_kc_idx = (
        3 if (sparse_k_cand_gpu is not None and sparse_k_cand_gpu.shape[0] > 3) else 2
    )
    kc_src_ptr = (
        k_cand_src_gpu
        if k_cand_src_gpu is not None
        else (
            sparse_k_cand_gpu[src_branch_idx, layer_idx, :H]
            if (has_meta and sparse_k_cand_gpu is not None)
            else (b_src.k_cand_gpu if write_src and b_src is not None else None)
        )
    )
    kc_s0_ptr = (
        k_cand_s0_gpu
        if k_cand_s0_gpu is not None
        else (
            sparse_k_cand_gpu[s0_branch_idx, layer_idx, :H]
            if (has_meta and sparse_k_cand_gpu is not None)
            else (b_s0.k_cand_gpu if write_s0 and b_s0 is not None else None)
        )
    )
    kc_s1_ptr = (
        k_cand_s1_gpu
        if k_cand_s1_gpu is not None
        else (
            sparse_k_cand_gpu[s1_kc_idx, layer_idx, :H]
            if (has_meta and sparse_k_cand_gpu is not None)
            else (b_s1.k_cand_gpu if write_s1 and b_s1 is not None else None)
        )
    )
    dummy_kc = (
        kc_src_ptr
        if kc_src_ptr is not None
        else (kc_s0_ptr if kc_s0_ptr is not None else kc_s1_ptr)
    )

    use_price_pi = price_pi > 0.0
    if device.type == "cuda" and HAS_TRITON:
        if has_meta:
            block_full = 128
        else:
            max_m_full = max(
                b_src.M_full_cur if write_src and b_src is not None else 0,
                b_s0.M_full_cur if write_s0 and b_s0 is not None else 0,
                b_s1.M_full_cur if write_s1 and b_s1 is not None else 0,
            )
            block_full = 64 if max_m_full <= 64 else (128 if max_m_full <= 128 else 256)
        if use_price_pi and fast_pi_filter:
            block_c_pi = (
                512 if M_cand_cap <= 512 else (1024 if M_cand_cap <= 1024 else 2048)
            )
            _zing_pi_filter_and_pack_masks_kernel[(M_q, H)](
                blk_scores,
                out_src_buf,
                out_s0_buf,
                out_s1_buf,
                kc_src_ptr if write_src and kc_src_ptr is not None else dummy_kc,
                kc_s0_ptr if write_s0 and kc_s0_ptr is not None else dummy_kc,
                kc_s1_ptr if write_s1 and kc_s1_ptr is not None else dummy_kc,
                sparse_meta_gpu if has_meta else dummy_kc,
                blk_scores.stride(0),
                blk_scores.stride(1),
                blk_scores.stride(2),
                out_src_buf.stride(0),
                out_src_buf.stride(1),
                M_cand,
                b_src.M_full_cur if write_src and b_src is not None else 0,
                b_s0.M_full_cur if write_s0 and b_s0 is not None else 0,
                M_cand_s1,
                b_s1.M_full_cur if write_s1 and b_s1 is not None else 0,
                b_evict_lo,
                b_evict_hi,
                shift_s1,
                H,
                float(price_pi),
                HAS_META_PTR=has_meta,
                HAS_PAIR=has_pair,
                WRITE_SRC=write_src,
                WRITE_S0=write_s0,
                WRITE_S1=write_s1,
                BLOCK_FULL=block_full,
                BLOCK_C=block_c_pi,
                num_warps=4,
            )
        else:
            top_val = ws.top_val_flat[: total_heads * M_q * K_top].view(
                total_heads, M_q, K_top
            )
            top_idx = ws.top_idx_flat[: total_heads * M_q * K_top].view(
                total_heads, M_q, K_top
            )
            torch.topk(
                blk_scores,
                k=K_top,
                dim=-1,
                largest=True,
                sorted=True,
                out=(top_val, top_idx),
            )
            block_n = 512 if K_top <= 512 else (1024 if K_top <= 1024 else 2048)
            _zing_pack_and_shift_all_masks_kernel[(M_q, H)](
                top_idx,
                top_val,
                out_src_buf,
                out_s0_buf,
                out_s1_buf,
                kc_src_ptr if write_src and kc_src_ptr is not None else dummy_kc,
                kc_s0_ptr if write_s0 and kc_s0_ptr is not None else dummy_kc,
                kc_s1_ptr if write_s1 and kc_s1_ptr is not None else dummy_kc,
                sparse_meta_gpu if has_meta else dummy_kc,
                top_idx.stride(0),
                top_idx.stride(1),
                top_idx.stride(2),
                out_src_buf.stride(0),
                out_src_buf.stride(1),
                M_cand,
                b_src.M_full_cur if write_src and b_src is not None else 0,
                b_s0.M_full_cur if write_s0 and b_s0 is not None else 0,
                M_cand_s1,
                b_s1.M_full_cur if write_s1 and b_s1 is not None else 0,
                b_evict_lo,
                b_evict_hi,
                shift_s1,
                K_top,
                H,
                float(price_pi),
                HAS_META_PTR=has_meta,
                HAS_PAIR=has_pair,
                WRITE_SRC=write_src,
                WRITE_S0=write_s0,
                WRITE_S1=write_s1,
                USE_PRICE_PI=use_price_pi,
                BLOCK_FULL=block_full,
                BLOCK_N=block_n,
                num_warps=4,
            )
    else:
        top_val = ws.top_val_flat[: total_heads * M_q * K_top].view(
            total_heads, M_q, K_top
        )
        top_idx = ws.top_idx_flat[: total_heads * M_q * K_top].view(
            total_heads, M_q, K_top
        )
        torch.topk(
            blk_scores,
            k=K_top,
            dim=-1,
            largest=True,
            sorted=True,
            out=(top_val, top_idx),
        )
        act_offset = H if has_pair else 0
        eff_k_top = min(K_top, M_cand)
        min_cand = min(MIN_CAND_BLOCKS_PER_HEAD, M_cand)
        inv_sqrt_d = 1.0 / math.sqrt(float(HEAD_DIM))
        if write_src:
            out_src_buf[:, :M_q, :].fill_(-1)
        if write_s0:
            out_s0_buf[:, :M_q, :].fill_(-1)
        if write_s1:
            out_s1_buf[:, :M_q, :].fill_(-1)
        mf_src = (
            int(sparse_meta_gpu[META_M_FULL_SRC].item())
            if has_meta
            else (b_src.M_full_cur if b_src is not None else 0)
        )
        mf_s0 = (
            int(sparse_meta_gpu[META_M_FULL_S0].item())
            if has_meta
            else (b_s0.M_full_cur if b_s0 is not None else 0)
        )
        mf_s1 = (
            int(sparse_meta_gpu[META_M_FULL_S1].item())
            if has_meta
            else (b_s1.M_full_cur if b_s1 is not None else 0)
        )
        for h in range(H):
            for m in range(M_q):
                if write_src and b_src is not None and kc_src_ptr is not None:
                    b_src_idx = top_idx[h, m].to(torch.int32).clone()
                    if use_price_pi and eff_k_top > 0:
                        v_src = top_val[h, m, :eff_k_top].float() * inv_sqrt_d
                        prob_src = torch.softmax(v_src, dim=-1)
                        for idx_p in range(min_cand, eff_k_top):
                            if float(prob_src[idx_p].item()) < price_pi:
                                b_src_idx[idx_p] = -1
                    kc_src = min(M_cand, int(kc_src_ptr[h].item()))
                    for i in range(mf_src):
                        out_src_buf[h, m, i] = M_cand + i
                    out_src_buf[h, m, mf_src : mf_src + kc_src] = b_src_idx[:kc_src]
                if (write_s0 or write_s1) and eff_k_top > 0:
                    b_act_raw = top_idx[act_offset + h, m].to(torch.int32).clone()
                    pass_act_list = [True] * eff_k_top
                    if use_price_pi:
                        v_act = (
                            top_val[act_offset + h, m, :eff_k_top].float() * inv_sqrt_d
                        )
                        prob_act = torch.softmax(v_act, dim=-1)
                        for idx_p in range(min_cand, eff_k_top):
                            if float(prob_act[idx_p].item()) < price_pi:
                                pass_act_list[idx_p] = False
                if write_s0 and b_s0 is not None and kc_s0_ptr is not None:
                    b_s0_idx = b_act_raw.clone()
                    if use_price_pi:
                        for idx_p in range(eff_k_top):
                            if not pass_act_list[idx_p]:
                                b_s0_idx[idx_p] = -1
                    kc_s0 = min(M_cand, int(kc_s0_ptr[h].item()))
                    for i in range(mf_s0):
                        out_s0_buf[h, m, i] = M_cand + i
                    out_s0_buf[h, m, mf_s0 : mf_s0 + kc_s0] = b_s0_idx[:kc_s0]
                if write_s1 and b_s1 is not None and kc_s1_ptr is not None:
                    kc_s1 = min(M_cand_s1, int(kc_s1_ptr[h].item()))
                    for i in range(mf_s1):
                        out_s1_buf[h, m, i] = M_cand_s1 + i
                    filtered = []
                    seen = set()
                    for idx_p, x in enumerate(b_act_raw[:eff_k_top]):
                        if use_price_pi and not pass_act_list[idx_p]:
                            continue
                        val = int(x.item())
                        if val < b_evict_lo:
                            b1 = val
                        elif val >= b_evict_hi:
                            b1 = val - shift_s1
                        else:
                            continue
                        if 0 <= b1 < M_cand_s1 and b1 not in seen:
                            filtered.append(b1)
                            seen.add(b1)
                    if not use_price_pi and len(filtered) < kc_s1:
                        for b1 in range(M_cand_s1):
                            if b1 not in seen:
                                filtered.append(b1)
                                seen.add(b1)
                                if len(filtered) >= kc_s1:
                                    break
                    for idx_f in range(kc_s1):
                        out_s1_buf[h, m, mf_s1 + idx_f] = (
                            filtered[idx_f] if idx_f < len(filtered) else -1
                        )

    skim_src_buf: torch.Tensor | None = None
    skim_s0_buf: torch.Tensor | None = None
    skim_s1_buf: torch.Tensor | None = None
    skim_cnt_src: torch.Tensor | None = None
    skim_cnt_s0: torch.Tensor | None = None
    skim_cnt_s1: torch.Tensor | None = None

    if enable_three_tier and (
        not has_meta or compressed_kv is not None or device.type != "cuda"
    ):
        skim_src_buf = ws.skim_idx_src[layer_idx, :H]
        skim_s0_buf = ws.skim_idx_s0[layer_idx, :H]
        skim_s1_buf = ws.skim_idx_s1[s1_parity % 2, layer_idx, :H]
        skim_cnt_src = ws.skim_cnt_src[layer_idx, :H]
        skim_cnt_s0 = ws.skim_cnt_s0[layer_idx, :H]
        skim_cnt_s1 = ws.skim_cnt_s1[s1_parity % 2, layer_idx, :H]
        skim_src_buf.fill_(-1)
        skim_s0_buf.fill_(-1)
        skim_s1_buf.fill_(-1)
        skim_cnt_src.zero_()
        skim_cnt_s0.zero_()
        skim_cnt_s1.zero_()

        top_val_3t = ws.top_val_flat[: total_heads * M_q * K_top].view(
            total_heads, M_q, K_top
        )
        top_idx_3t = ws.top_idx_flat[: total_heads * M_q * K_top].view(
            total_heads, M_q, K_top
        )
        if device.type == "cuda" and HAS_TRITON and use_price_pi and fast_pi_filter:
            torch.topk(
                blk_scores,
                k=K_top,
                dim=-1,
                largest=True,
                sorted=True,
                out=(top_val_3t, top_idx_3t),
            )
        act_offset = H if has_pair else 0
        eff_k_top = min(K_top, M_cand)
        inv_sqrt_d = 1.0 / math.sqrt(float(HEAD_DIM))
        alpha_eff = max(float(alpha_triage), 1e-6)
        c_rf_eff = max(float(c_rf), 1.0)
        sk_cap = (
            max(1, int(math.ceil(alpha_eff * float(M_cand))))
            if alpha_eff < 1.0
            else M_cand
        )
        mf_src = b_src.M_full_cur if b_src is not None else 0
        mf_s0 = b_s0.M_full_cur if b_s0 is not None else 0
        mf_s1 = b_s1.M_full_cur if b_s1 is not None else 0

        if eff_k_top > 0:
            v_top = top_val_3t[:, :, :eff_k_top].float() * inv_sqrt_d
            b_top = top_idx_3t[:, :, :eff_k_top].to(torch.int32)
            valid_b = (b_top >= 0) & (b_top < M_cand)
            v_masked = torch.where(valid_b, v_top, -1.0e30)
            prob_top = torch.softmax(v_masked, dim=-1)
            rel_p = torch.where(valid_b, prob_top * float(max(1, eff_k_top)), 0.0)
            b_clamped = b_top.clamp(0, max(0, M_cand_cap - 1)).to(torch.long)

            alpha_k_use = (
                compressed_kv.get("alpha_k") if compressed_kv is not None else None
            )
            if alpha_k_use is None and k_blk_mean is not None and tau_k is not None:
                k_sub_src = (
                    k_sub[:, : M_cand * SUB_PER_BLK, :]
                    if (device.type == "cuda" and HAS_TRITON)
                    else k_sub_ref[:, : M_cand * SUB_PER_BLK, :]
                )
                ks_4d = k_sub_src.view(H, M_cand, SUB_PER_BLK, HEAD_DIM).float()
                km_3d = k_blk_mean[:, :M_cand, None, :].float()
                tk_tot = tau_k[:, :M_cand].float()
                tk_between = (ks_4d - km_3d).pow(2).sum(dim=-1).mean(dim=-1) / (
                    2.0 * float(HEAD_DIM)
                )
                tk_within = (tk_tot - tk_between).clamp_min(0.0)
                alpha_k_use = ((tk_within + 0.95e-5) / (tk_tot + 1.0e-5)).clamp(
                    0.05, 0.95
                )

            if tau_k is not None and rho_kv is not None:
                tk_pad = F.pad(
                    tau_k[:, :M_cand_cap].float(),
                    (0, max(0, M_cand_cap - tau_k.shape[1])),
                )
                rk_pad = F.pad(
                    rho_kv[:, :M_cand_cap].float(),
                    (0, max(0, M_cand_cap - rho_kv.shape[1])),
                )
                comp_2d = (2.0 * tk_pad + rk_pad).repeat(n_mult, 1)
                comp_top = torch.gather(
                    comp_2d[:, None, :].expand(total_heads, M_q, -1), 2, b_clamped
                )
                base_u_all = rel_p * comp_top
            else:
                base_u_all = rel_p

            if alpha_k_use is not None:
                ak_pad = F.pad(
                    alpha_k_use[:, :M_cand_cap].float(),
                    (0, max(0, M_cand_cap - alpha_k_use.shape[1])),
                    value=0.5,
                )
                alpha_2d = ak_pad.repeat(n_mult, 1)
                alpha_top = torch.gather(
                    alpha_2d[:, None, :].expand(total_heads, M_q, -1), 2, b_clamped
                )
                u_rf_all = torch.where(
                    alpha_top >= 0.25, base_u_all * (alpha_top / 0.5), 0.0
                )
                u_sk_all = base_u_all * torch.clamp(2.0 * (1.0 - alpha_top), min=1.0)
            else:
                u_rf_all = base_u_all
                u_sk_all = base_u_all

            def _compute_branch_thresholds(
                base_u_br: torch.Tensor, kc_cap_t: torch.Tensor
            ) -> tuple[torch.Tensor, torch.Tensor]:
                if price_pi > 0.0:
                    pi_val = float(price_pi)
                    rf_t = torch.full(
                        (H, M_q, 1),
                        c_rf_eff * pi_val,
                        dtype=torch.float32,
                        device=device,
                    )
                    sk_t = torch.full(
                        (H, M_q, 1),
                        pi_val * (0.22 / alpha_eff),
                        dtype=torch.float32,
                        device=device,
                    )
                    return rf_t, sk_t
                # Theorem 4 quota-anchored shadow price: pi_{l,h,m} = S_{(K_{l,h})} / c_rf
                k_ord = (
                    (kc_cap_t[:H].clamp(1, max(1, eff_k_top)) - 1)
                    .to(torch.long)[:, None, None]
                    .expand(H, M_q, 1)
                )
                sorted_u = torch.sort(base_u_br, dim=-1, descending=True).values
                s_kth = torch.gather(sorted_u, 2, k_ord).clamp_min(1.0e-5)
                pi_quota = s_kth / c_rf_eff
                rf_t = c_rf_eff * pi_quota * 0.5
                sk_t = pi_quota * (0.22 / alpha_eff)
                return rf_t, sk_t

            def _pack_3tier_vectorized(
                b_br: torch.Tensor,
                val_br: torch.Tensor,
                u_rf_br: torch.Tensor,
                u_sk_br: torch.Tensor,
                rf_t: torch.Tensor,
                sk_t: torch.Tensor,
                kc_cap_t: torch.Tensor,
                m_cand_br: int,
                m_full_br: int,
                out_cand: torch.Tensor,
                out_skim: torch.Tensor,
                out_skim_cnt: torch.Tensor,
            ) -> None:
                out_cand.fill_(-1)
                out_skim.fill_(-1)
                if m_full_br > 0:
                    full_ids = torch.arange(
                        m_cand_br,
                        m_cand_br + m_full_br,
                        dtype=torch.int32,
                        device=device,
                    )
                    out_cand[:, :M_q, :m_full_br] = full_ids[None, None, :]

                kc_lim = kc_cap_t[:H].clamp(min=0, max=m_cand_br)[:, None, None]
                pass_rf_raw = val_br & (u_rf_br > rf_t)
                rf_rank = torch.cumsum(pass_rf_raw.to(torch.int32), dim=-1) - 1
                is_rf = pass_rf_raw & (rf_rank < kc_lim)

                rf_order = torch.argsort((~is_rf).to(torch.int32), dim=-1, stable=True)
                rf_valid = torch.gather(is_rf, 2, rf_order)
                rf_b = torch.gather(b_br, 2, rf_order)
                max_rf_cols = min(eff_k_top, int(out_cand.shape[-1]) - m_full_br)
                if max_rf_cols > 0:
                    out_cand[:, :M_q, m_full_br : m_full_br + max_rf_cols] = (
                        torch.where(
                            rf_valid[:, :, :max_rf_cols], rf_b[:, :, :max_rf_cols], -1
                        )
                    )

                pass_sk_raw = val_br & (~is_rf) & (u_sk_br > sk_t)
                sk_rank = torch.cumsum(pass_sk_raw.to(torch.int32), dim=-1) - 1
                is_sk = pass_sk_raw & (sk_rank < sk_cap)

                sk_order = torch.argsort((~is_sk).to(torch.int32), dim=-1, stable=True)
                sk_valid = torch.gather(is_sk, 2, sk_order)
                sk_b = torch.gather(b_br, 2, sk_order)
                max_sk_cols = min(eff_k_top, int(out_skim.shape[-1]))
                if max_sk_cols > 0:
                    out_skim[:, :M_q, :max_sk_cols] = torch.where(
                        sk_valid[:, :, :max_sk_cols], sk_b[:, :, :max_sk_cols], -1
                    )
                out_skim_cnt.copy_(is_sk.sum(dim=-1).amax(dim=-1).to(torch.int32))

            if write_src and b_src is not None and kc_src_ptr is not None:
                rf_t_src, sk_t_src = _compute_branch_thresholds(
                    base_u_all[:H], kc_src_ptr
                )
                _pack_3tier_vectorized(
                    b_top[:H],
                    valid_b[:H],
                    u_rf_all[:H],
                    u_sk_all[:H],
                    rf_t_src,
                    sk_t_src,
                    kc_src_ptr,
                    M_cand,
                    mf_src,
                    out_src_buf,
                    skim_src_buf,
                    skim_cnt_src,
                )

            if write_s0 or write_s1:
                b_act = b_top[act_offset : act_offset + H]
                val_act = valid_b[act_offset : act_offset + H]
                u_rf_act = u_rf_all[act_offset : act_offset + H]
                u_sk_act = u_sk_all[act_offset : act_offset + H]
                base_u_act = base_u_all[act_offset : act_offset + H]

                if write_s0 and b_s0 is not None and kc_s0_ptr is not None:
                    rf_t_s0, sk_t_s0 = _compute_branch_thresholds(base_u_act, kc_s0_ptr)
                    _pack_3tier_vectorized(
                        b_act,
                        val_act,
                        u_rf_act,
                        u_sk_act,
                        rf_t_s0,
                        sk_t_s0,
                        kc_s0_ptr,
                        M_cand,
                        mf_s0,
                        out_s0_buf,
                        skim_s0_buf,
                        skim_cnt_s0,
                    )

                if write_s1 and b_s1 is not None and kc_s1_ptr is not None:
                    b1_act = torch.where(
                        b_act < b_evict_lo,
                        b_act,
                        torch.where(b_act >= b_evict_hi, b_act - shift_s1, -1),
                    )
                    val_s1_raw = (
                        val_act
                        & ((b_act < b_evict_lo) | (b_act >= b_evict_hi))
                        & (b1_act >= 0)
                        & (b1_act < M_cand_s1)
                    )
                    # Vectorized deduplication across candidate positions if shift_s1 causes overlap
                    if shift_s1 > 0 and eff_k_top > 1:
                        upper_tri = torch.triu(
                            torch.ones(
                                (eff_k_top, eff_k_top),
                                dtype=torch.bool,
                                device=device,
                            ),
                            diagonal=1,
                        )
                        dup = (
                            (b1_act[:, :, :, None] == b1_act[:, :, None, :])
                            & val_s1_raw[:, :, :, None]
                            & val_s1_raw[:, :, None, :]
                            & upper_tri[None, None, :, :]
                        )
                        val_s1 = val_s1_raw & (~dup.any(dim=-2))
                    else:
                        val_s1 = val_s1_raw
                    rf_t_s1, sk_t_s1 = _compute_branch_thresholds(base_u_act, kc_s1_ptr)
                    _pack_3tier_vectorized(
                        b1_act,
                        val_s1,
                        u_rf_act,
                        u_sk_act,
                        rf_t_s1,
                        sk_t_s1,
                        kc_s1_ptr,
                        M_cand_s1,
                        mf_s1,
                        out_s1_buf,
                        skim_s1_buf,
                        skim_cnt_s1,
                    )
        else:
            if write_src and mf_src > 0:
                out_src_buf[:, :, :mf_src] = torch.arange(
                    M_cand, M_cand + mf_src, dtype=torch.int32, device=device
                )[None, None, :]
            if write_s0 and mf_s0 > 0:
                out_s0_buf[:, :, :mf_s0] = torch.arange(
                    M_cand, M_cand + mf_s0, dtype=torch.int32, device=device
                )[None, None, :]
            if write_s1 and mf_s1 > 0:
                out_s1_buf[:, :, :mf_s1] = torch.arange(
                    M_cand_s1, M_cand_s1 + mf_s1, dtype=torch.int32, device=device
                )[None, None, :]

    s1_nf_idx = (
        3
        if (sparse_num_full_gpu is not None and sparse_num_full_gpu.shape[0] > 3)
        else 2
    )
    cnt_src = (
        num_full_src_gpu
        if num_full_src_gpu is not None
        else (
            sparse_num_full_gpu[src_branch_idx, layer_idx, :H]
            if (has_meta and sparse_num_full_gpu is not None)
            else (b_src.num_full_gpu if b_src is not None else None)
        )
    )
    cnt_s0 = (
        num_full_s0_gpu
        if num_full_s0_gpu is not None
        else (
            sparse_num_full_gpu[s0_branch_idx, layer_idx, :H]
            if (has_meta and sparse_num_full_gpu is not None)
            else (b_s0.num_full_gpu if b_s0 is not None else None)
        )
    )
    cnt_s1 = (
        num_full_s1_gpu
        if num_full_s1_gpu is not None
        else (
            sparse_num_full_gpu[s1_nf_idx, layer_idx, :H]
            if (has_meta and sparse_num_full_gpu is not None)
            else (b_s1.num_full_gpu if b_s1 is not None else None)
        )
    )

    s1_same_cand = (shift_s1 == 0) and (M_cand_s1 == M_cand)
    mask_src = (
        PrebuiltSparseMask(
            L_q=L_q,
            L_k=L_k_src,
            M_q=M_q,
            M_k=M_k_src,
            M_cand=M_cand,
            cand_cnt=cnt_src,
            cand_idx=out_src_buf,
            head_order=b_src.head_order_gpu,
            active_ratio=b_src.active_ratio,
            k_blk_mean=k_blk_mean,
            v_blk_mean=v_blk_mean,
            tau_k=tau_k,
            skim_cnt=skim_cnt_src,
            skim_idx=skim_src_buf,
            compressed_kv=compressed_kv,
        )
        if write_src and b_src is not None and cnt_src is not None
        else None
    )
    mask_s0 = (
        PrebuiltSparseMask(
            L_q=L_q,
            L_k=L_k_s0,
            M_q=M_q,
            M_k=M_k_s0,
            M_cand=M_cand,
            cand_cnt=cnt_s0,
            cand_idx=out_s0_buf,
            head_order=b_s0.head_order_gpu,
            active_ratio=b_s0.active_ratio,
            k_blk_mean=k_blk_mean,
            v_blk_mean=v_blk_mean,
            tau_k=tau_k,
            skim_cnt=skim_cnt_s0,
            skim_idx=skim_s0_buf,
            compressed_kv=compressed_kv,
        )
        if write_s0 and b_s0 is not None and cnt_s0 is not None
        else None
    )
    mask_s1 = (
        PrebuiltSparseMask(
            L_q=L_q,
            L_k=L_k_s1,
            M_q=M_q,
            M_k=M_k_s1,
            M_cand=M_cand_s1,
            cand_cnt=cnt_s1,
            cand_idx=out_s1_buf,
            head_order=b_s1.head_order_gpu,
            active_ratio=b_s1.active_ratio,
            k_blk_mean=k_blk_mean if s1_same_cand else None,
            v_blk_mean=v_blk_mean if s1_same_cand else None,
            tau_k=tau_k if s1_same_cand else None,
            skim_cnt=skim_cnt_s1,
            skim_idx=skim_s1_buf,
            compressed_kv=compressed_kv if s1_same_cand else None,
        )
        if write_s1 and b_s1 is not None and cnt_s1 is not None
        else None
    )
    return mask_src, mask_s0, mask_s1


def _run_dense_branch(
    query: torch.Tensor,
    keys: torch.Tensor,
    values: torch.Tensor,
    scale: float,
    fixed_tensors: dict[str, Any],
    branch: int,
    optimized: bool,
    target_736p: bool = False,
) -> torch.Tensor:
    """Execute dense attention fallback via FA4 on CUDA or SDPA on CPU."""
    if query.device.type == "cuda":
        from sglang.multimodal_gen.runtime.models.dits.zing_h3 import (
            _fixed_fa4_attention,
            _FixedFA4Metadata,
        )

        return _fixed_fa4_attention(
            query,
            keys,
            values,
            scale,
            _FixedFA4Metadata(fixed_tensors, branch),
            optimized=optimized,
            target_736p=target_736p,
        )

    cu_k = fixed_tensors[f"cu_k.{branch}"]
    valid_len = int(cu_k[1].item())
    valid = torch.arange(keys.shape[0], device=keys.device) < valid_len
    return F.scaled_dot_product_attention(
        query.transpose(0, 1)[None],
        keys.transpose(0, 1)[None],
        values.transpose(0, 1)[None],
        attn_mask=valid[None, None, None],
        scale=scale,
    )[0].transpose(0, 1)


def execute_branch_attention(
    orig_fixed_fa4,
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    scale: float,
    metadata: Any,
    optimized: bool,
    layer_idx: int,
    spec: SparseBranchSpec,
    *,
    ulysses_rank: int = 0,
    fixed_tensors: dict[str, Any] | None = None,
    branch: int = 0,
    q_full: torch.Tensor | None = None,
    target_736p: bool = False,
) -> torch.Tensor:
    """Execute either Dense FA4 or Step C 4D Block-Sparse Attention for one branch and layer."""
    min_chunk = get_min_sparse_chunk()
    H_local = q.shape[1]
    head_start = ulysses_rank * H_local
    use_three_tier = is_three_tier_enabled(spec.mode)
    compressed_kv = None
    if use_three_tier and fixed_tensors:
        ckv_by_layer = fixed_tensors.get("compressed_kv_by_layer")
        if (
            ckv_by_layer is not None
            and isinstance(ckv_by_layer, (list, tuple))
            and layer_idx < len(ckv_by_layer)
        ):
            compressed_kv = ckv_by_layer[layer_idx]
        elif (
            ckv_by_layer is not None
            and isinstance(ckv_by_layer, dict)
            and layer_idx in ckv_by_layer
        ):
            compressed_kv = ckv_by_layer[layer_idx]
        else:
            raw_ckv = fixed_tensors.get("compressed_kv")
            if isinstance(raw_ckv, (list, tuple)) and layer_idx < len(raw_ckv):
                compressed_kv = raw_ckv[layer_idx]
            elif (
                isinstance(raw_ckv, dict)
                and "k_blk_mean" not in raw_ckv
                and layer_idx in raw_ckv
            ):
                compressed_kv = raw_ckv[layer_idx]
            else:
                compressed_kv = raw_ckv
    q_win = fixed_tensors.get("q_win") if fixed_tensors else None

    # 1. Dense mode or Layer 0 or startup warmup chunks or tiny candidate pool
    if (
        spec.mode == "dense"
        or layer_idx == 0
        or spec.chunk_id < min_chunk
        or spec.M_cand <= 8
    ):
        if (
            use_three_tier
            and spec.mode != "dense"
            and (compressed_kv is not None or q.device.type != "cuda")
        ):
            # SPEC Rev 6 §3.4: Dense Protection = 100% Refine through Three-Tier All-FP8 kernel
            _LAST_3TIER_EXEC_META.clear()
            _LAST_3TIER_EXEC_META.update(
                {
                    "dense_protection_100pct_refine": True,
                    "layer_idx": layer_idx,
                    "chunk_id": spec.chunk_id,
                    "M_k": spec.M_k,
                    "M_cand": spec.M_cand,
                    "mode": spec.mode,
                }
            )
            sparse_meta_gpu = (
                fixed_tensors.get("sparse_meta") if fixed_tensors else None
            )
            meta_branch_gpu = (
                sparse_meta_gpu[
                    META_BRANCH_BASE + 4 * branch : META_BRANCH_BASE + 4 * branch + 4
                ]
                if sparse_meta_gpu is not None
                else None
            )
            cand_cnt_100 = torch.full(
                (H_local,), spec.M_k, dtype=torch.int32, device=q.device
            )
            cand_idx_100 = (
                torch.arange(spec.M_k, dtype=torch.int32, device=q.device)
                .view(1, 1, max(1, spec.M_k))
                .expand(H_local, spec.M_q, max(1, spec.M_k))
                .contiguous()
            )
            skim_cnt_0 = torch.zeros((H_local,), dtype=torch.int32, device=q.device)
            skim_idx_0 = torch.full(
                (H_local, spec.M_q, 1), -1, dtype=torch.int32, device=q.device
            )
            head_order_100 = torch.arange(H_local, dtype=torch.int32, device=q.device)
            return launch_zing_block_sparse_attn(
                q,
                k,
                v,
                scale,
                spec.L_k,
                spec.M_cand,
                spec.M_k,
                cand_cnt_100,
                cand_idx_100,
                head_order_100,
                meta_branch_gpu=meta_branch_gpu,
                enable_virtual_mean=False,
                skim_cnt=skim_cnt_0,
                skim_idx=skim_idx_0,
                compressed_kv=compressed_kv,
                q_win=q_win,
                enable_three_tier=True,
            )
        if orig_fixed_fa4 is not None:
            return orig_fixed_fa4(q, k, v, scale, metadata, optimized=optimized)
        return _run_dense_branch(
            q,
            k,
            v,
            scale,
            fixed_tensors or {},
            branch,
            optimized,
            target_736p=target_736p,
        )

    if use_three_tier:
        _LAST_3TIER_EXEC_META.clear()
        _LAST_3TIER_EXEC_META.update(
            {
                "dense_protection_100pct_refine": False,
                "layer_idx": layer_idx,
                "chunk_id": spec.chunk_id,
                "M_k": spec.M_k,
                "M_cand": spec.M_cand,
                "mode": spec.mode,
            }
        )

    sparse_meta_gpu = fixed_tensors.get("sparse_meta") if fixed_tensors else None
    sparse_blk_kind_gpu = (
        fixed_tensors.get("sparse_blk_kind") if fixed_tensors else None
    )
    sparse_k_cand_gpu = fixed_tensors.get("sparse_k_cand") if fixed_tensors else None
    sparse_num_full_gpu = (
        fixed_tensors.get("sparse_num_full") if fixed_tensors else None
    )
    has_sparse_meta = sparse_meta_gpu is not None
    meta_branch_gpu = (
        sparse_meta_gpu[
            META_BRANCH_BASE + 4 * branch : META_BRANCH_BASE + 4 * branch + 4
        ]
        if sparse_meta_gpu is not None
        else None
    )
    use_virtual_mean = is_virtual_mean_enabled(spec.mode)
    use_triage_score = is_triage_score_enabled(spec.mode)
    price_pi = get_sparse_price_pi(spec.mode)
    c_rf = get_sparse_c_rf()
    alpha_triage = get_sparse_alpha_triage()

    # 2. Source branch (branch 1 of joint): run Fused Triton Router ONCE for the entire chunk
    if spec.b_phase == "source":
        comp = spec.companion_step0_spec
        q_act = None
        if comp is not None:
            if q_full is not None and q_full.shape[0] >= comp.q_stop:
                q_act = q_full[comp.q_start : comp.q_stop]
            elif q.is_contiguous():
                req_end_elems = q.storage_offset() + (
                    comp.q_stop - spec.q_start
                ) * q.stride(0)
                if q.untyped_storage().nbytes() >= req_end_elems * q.element_size():
                    q_act = torch.as_strided(
                        q,
                        size=(comp.L_q, q.shape[1], q.shape[2]),
                        stride=q.stride(),
                        storage_offset=q.storage_offset()
                        + (comp.q_start - spec.q_start) * q.stride(0),
                    )

        if comp is not None:
            s1_par = 0 if has_sparse_meta else (comp.chunk_id % 2)
            mask_src, mask_s0, _ = fused_route_and_build_masks(
                q_first=q,
                q_second=q_act,
                k=k,
                layer_idx=layer_idx,
                tau=spec.tau,
                L_q=spec.L_q,
                M_q=spec.M_q,
                M_cand=spec.M_cand,
                M_prefix=spec.M_prefix,
                safety_scale=spec.safety_scale,
                build_src=True,
                L_k_src=spec.L_k,
                M_k_src=spec.M_k,
                M_cur_src=spec.M_cur,
                build_s0=True,
                L_k_s0=comp.L_k,
                M_k_s0=comp.M_k,
                M_cur_s0=comp.M_cur,
                build_s1=False,
                s_evict=0,
                L_k_s1=0,
                M_k_s1=0,
                M_cand_s1=0,
                M_cur_s1=0,
                head_start=head_start,
                num_heads=H_local,
                s1_parity=s1_par,
                L_evict=0,
                blk_kind_sig=spec.blk_kind_sig,
                sparse_meta_gpu=sparse_meta_gpu,
                sparse_blk_kind_gpu=sparse_blk_kind_gpu,
                sparse_k_cand_gpu=sparse_k_cand_gpu,
                sparse_num_full_gpu=sparse_num_full_gpu,
                src_branch_idx=branch,
                s0_branch_idx=branch + 1,
                v=v,
                enable_triage_score=use_triage_score,
                enable_virtual_mean=use_virtual_mean,
                price_pi=price_pi,
                enable_three_tier=use_three_tier,
                c_rf=c_rf,
                alpha_triage=alpha_triage,
                compressed_kv=compressed_kv,
            )
            if mask_s0 is not None:
                _STEP0_READY_MASKS[(comp.chunk_id, layer_idx)] = mask_s0
                _STEP0_PARITY_MASKS[(s1_par, comp.M_q, layer_idx)] = mask_s0
        else:
            s1_par = 0 if has_sparse_meta else (spec.chunk_id % 2)
            mask_src, _, _ = fused_route_and_build_masks(
                q_first=q,
                q_second=None,
                k=k,
                layer_idx=layer_idx,
                tau=spec.tau,
                L_q=spec.L_q,
                M_q=spec.M_q,
                M_cand=spec.M_cand,
                M_prefix=spec.M_prefix,
                safety_scale=spec.safety_scale,
                build_src=True,
                L_k_src=spec.L_k,
                M_k_src=spec.M_k,
                M_cur_src=spec.M_cur,
                build_s0=False,
                L_k_s0=0,
                M_k_s0=0,
                M_cur_s0=0,
                build_s1=False,
                s_evict=0,
                L_k_s1=0,
                M_k_s1=0,
                M_cand_s1=0,
                M_cur_s1=0,
                head_start=head_start,
                num_heads=H_local,
                s1_parity=s1_par,
                L_evict=0,
                blk_kind_sig=spec.blk_kind_sig,
                sparse_meta_gpu=sparse_meta_gpu,
                sparse_blk_kind_gpu=sparse_blk_kind_gpu,
                sparse_k_cand_gpu=sparse_k_cand_gpu,
                sparse_num_full_gpu=sparse_num_full_gpu,
                src_branch_idx=branch,
                s0_branch_idx=branch + 1,
                v=v,
                enable_triage_score=use_triage_score,
                enable_virtual_mean=use_virtual_mean,
                price_pi=price_pi,
                enable_three_tier=use_three_tier,
                c_rf=c_rf,
                alpha_triage=alpha_triage,
                compressed_kv=compressed_kv,
            )

        if mask_src is None:
            if orig_fixed_fa4 is not None:
                return orig_fixed_fa4(q, k, v, scale, metadata, optimized=optimized)
            return _run_dense_branch(
                q,
                k,
                v,
                scale,
                fixed_tensors or {},
                branch,
                optimized,
                target_736p=target_736p,
            )

        cand_cnt_use = (
            sparse_num_full_gpu[branch, layer_idx, :H_local]
            if sparse_num_full_gpu is not None
            else mask_src.cand_cnt
        )
        return launch_zing_block_sparse_attn(
            q,
            k,
            v,
            scale,
            spec.L_k,
            spec.M_cand,
            spec.M_k,
            cand_cnt_use,
            mask_src.cand_idx,
            mask_src.head_order,
            meta_branch_gpu=meta_branch_gpu,
            enable_virtual_mean=use_virtual_mean,
            k_blk_mean=mask_src.k_blk_mean,
            v_blk_mean=mask_src.v_blk_mean,
            tau_k=mask_src.tau_k,
            skim_cnt=mask_src.skim_cnt,
            skim_idx=mask_src.skim_idx,
            compressed_kv=mask_src.compressed_kv or compressed_kv,
            q_win=q_win,
            enable_three_tier=use_three_tier,
        )

    # 3. Target Step 0 (branch 2 of joint): zero-overhead reuse of _STEP0_READY_MASKS / _STEP0_PARITY_MASKS
    if spec.b_phase == "active" and spec.step_idx == 0:
        s1_par = 0 if has_sparse_meta else (spec.chunk_id % 2)
        prebuilt_s0 = _STEP0_READY_MASKS.get((spec.chunk_id, layer_idx))
        if prebuilt_s0 is None:
            prebuilt_s0 = _STEP0_PARITY_MASKS.get((s1_par, spec.M_q, layer_idx))
        if (
            prebuilt_s0 is not None
            and prebuilt_s0.L_q == spec.L_q
            and prebuilt_s0.M_q == spec.M_q
            and (
                has_sparse_meta
                or (prebuilt_s0.L_k == spec.L_k and prebuilt_s0.M_cand == spec.M_cand)
            )
        ):
            cand_cnt_use = (
                sparse_num_full_gpu[branch, layer_idx, :H_local]
                if sparse_num_full_gpu is not None
                else prebuilt_s0.cand_cnt
            )
            return launch_zing_block_sparse_attn(
                q,
                k,
                v,
                scale,
                spec.L_k,
                spec.M_cand,
                spec.M_k,
                cand_cnt_use,
                prebuilt_s0.cand_idx,
                prebuilt_s0.head_order,
                meta_branch_gpu=meta_branch_gpu,
                enable_virtual_mean=use_virtual_mean,
                k_blk_mean=prebuilt_s0.k_blk_mean,
                v_blk_mean=prebuilt_s0.v_blk_mean,
                tau_k=prebuilt_s0.tau_k,
                skim_cnt=prebuilt_s0.skim_cnt,
                skim_idx=prebuilt_s0.skim_idx,
                compressed_kv=prebuilt_s0.compressed_kv or compressed_kv,
                q_win=q_win,
                enable_three_tier=use_three_tier,
            )

        # Standalone Step 0 fallback
        _, mask_s0, mask_s1 = fused_route_and_build_masks(
            q_first=q,
            q_second=None,
            k=k,
            layer_idx=layer_idx,
            tau=spec.tau,
            L_q=spec.L_q,
            M_q=spec.M_q,
            M_cand=spec.M_cand,
            M_prefix=spec.M_prefix,
            safety_scale=spec.safety_scale,
            build_src=False,
            L_k_src=0,
            M_k_src=0,
            M_cur_src=0,
            build_s0=True,
            L_k_s0=spec.L_k,
            M_k_s0=spec.M_k,
            M_cur_s0=spec.M_cur,
            build_s1=True,
            s_evict=spec.s_evict,
            L_k_s1=spec.L_k_step1,
            M_k_s1=spec.M_k_step1,
            M_cand_s1=spec.M_cand_step1,
            M_cur_s1=spec.M_cur_step1,
            head_start=head_start,
            num_heads=H_local,
            s1_parity=s1_par,
            L_evict=spec.L_evict,
            blk_kind_sig=spec.blk_kind_sig,
            sparse_meta_gpu=sparse_meta_gpu,
            sparse_blk_kind_gpu=sparse_blk_kind_gpu,
            sparse_k_cand_gpu=sparse_k_cand_gpu,
            sparse_num_full_gpu=sparse_num_full_gpu,
            src_branch_idx=branch,
            s0_branch_idx=branch,
            v=v,
            enable_triage_score=use_triage_score,
            enable_virtual_mean=use_virtual_mean,
            price_pi=price_pi,
            enable_three_tier=use_three_tier,
            c_rf=c_rf,
            alpha_triage=alpha_triage,
            compressed_kv=compressed_kv,
        )
        if mask_s0 is not None:
            _STEP0_READY_MASKS[(spec.chunk_id, layer_idx)] = mask_s0
            _STEP0_PARITY_MASKS[(s1_par, spec.M_q, layer_idx)] = mask_s0
        if mask_s1 is not None:
            _STEP1_READY_MASKS[(spec.chunk_id, layer_idx)] = mask_s1
            _STEP1_PARITY_MASKS[(s1_par, spec.M_q, layer_idx)] = mask_s1

        if mask_s0 is None:
            if orig_fixed_fa4 is not None:
                return orig_fixed_fa4(q, k, v, scale, metadata, optimized=optimized)
            return _run_dense_branch(
                q,
                k,
                v,
                scale,
                fixed_tensors or {},
                branch,
                optimized,
                target_736p=target_736p,
            )

        cand_cnt_use = (
            sparse_num_full_gpu[branch, layer_idx, :H_local]
            if sparse_num_full_gpu is not None
            else mask_s0.cand_cnt
        )
        return launch_zing_block_sparse_attn(
            q,
            k,
            v,
            scale,
            spec.L_k,
            spec.M_cand,
            spec.M_k,
            cand_cnt_use,
            mask_s0.cand_idx,
            mask_s0.head_order,
            meta_branch_gpu=meta_branch_gpu,
            enable_virtual_mean=use_virtual_mean,
            k_blk_mean=mask_s0.k_blk_mean,
            v_blk_mean=mask_s0.v_blk_mean,
            tau_k=mask_s0.tau_k,
            skim_cnt=mask_s0.skim_cnt,
            skim_idx=mask_s0.skim_idx,
            compressed_kv=mask_s0.compressed_kv or compressed_kv,
            q_win=q_win,
            enable_three_tier=use_three_tier,
        )

    # 4. Target Step s >= 1 (t=500): route post-eviction, post-RoPE KV & denoised q(t=500), populate _STEP1_READY_MASKS for Final (t=1)
    s1_par = 0 if has_sparse_meta else (spec.chunk_id % 2)
    if spec.b_phase == "active" and spec.step_idx >= 1:
        _, _, mask_s1 = fused_route_and_build_masks(
            q_first=q,
            q_second=None,
            k=k,
            layer_idx=layer_idx,
            tau=spec.tau,
            L_q=spec.L_q,
            M_q=spec.M_q,
            M_cand=spec.M_cand,
            M_prefix=spec.M_prefix,
            safety_scale=spec.safety_scale,
            build_src=False,
            L_k_src=0,
            M_k_src=0,
            M_cur_src=0,
            build_s0=False,
            L_k_s0=0,
            M_k_s0=0,
            M_cur_s0=0,
            build_s1=True,
            s_evict=spec.s_cur_chunk,
            L_k_s1=spec.L_k,
            M_k_s1=spec.M_k,
            M_cand_s1=spec.M_cand,
            M_cur_s1=spec.M_cur,
            head_start=head_start,
            num_heads=H_local,
            s1_parity=s1_par,
            L_evict=0,
            blk_kind_sig=spec.blk_kind_sig,
            sparse_meta_gpu=sparse_meta_gpu,
            sparse_blk_kind_gpu=sparse_blk_kind_gpu,
            sparse_k_cand_gpu=sparse_k_cand_gpu,
            sparse_num_full_gpu=sparse_num_full_gpu,
            src_branch_idx=branch,
            s0_branch_idx=branch,
            v=v,
            enable_triage_score=use_triage_score,
            enable_virtual_mean=use_virtual_mean,
            price_pi=price_pi,
            enable_three_tier=use_three_tier,
            c_rf=c_rf,
            alpha_triage=alpha_triage,
            compressed_kv=compressed_kv,
        )
        if mask_s1 is None:
            if orig_fixed_fa4 is not None:
                return orig_fixed_fa4(q, k, v, scale, metadata, optimized=optimized)
            return _run_dense_branch(
                q,
                k,
                v,
                scale,
                fixed_tensors or {},
                branch,
                optimized,
                target_736p=target_736p,
            )
        mask_s1_for_final = PrebuiltSparseMask(
            L_q=mask_s1.L_q,
            L_k=mask_s1.L_k,
            M_q=mask_s1.M_q,
            M_k=mask_s1.M_k,
            M_cand=mask_s1.M_cand,
            cand_cnt=mask_s1.cand_cnt,
            cand_idx=mask_s1.cand_idx,
            head_order=mask_s1.head_order,
            active_ratio=mask_s1.active_ratio,
            k_blk_mean=mask_s1.k_blk_mean,
            v_blk_mean=mask_s1.v_blk_mean,
            tau_k=mask_s1.tau_k,
            skim_cnt=mask_s1.skim_cnt,
            skim_idx=mask_s1.skim_idx,
            compressed_kv=None,
        )
        _STEP1_READY_MASKS[(spec.chunk_id, layer_idx)] = mask_s1_for_final
        _STEP1_PARITY_MASKS[(s1_par, spec.M_q, layer_idx)] = mask_s1_for_final
        cand_cnt_use = (
            sparse_num_full_gpu[branch, layer_idx, :H_local]
            if sparse_num_full_gpu is not None
            else mask_s1.cand_cnt
        )
        return launch_zing_block_sparse_attn(
            q,
            k,
            v,
            scale,
            spec.L_k,
            spec.M_cand,
            spec.M_k,
            cand_cnt_use,
            mask_s1.cand_idx,
            mask_s1.head_order,
            meta_branch_gpu=meta_branch_gpu,
            enable_virtual_mean=use_virtual_mean,
            k_blk_mean=mask_s1.k_blk_mean,
            v_blk_mean=mask_s1.v_blk_mean,
            tau_k=mask_s1.tau_k,
            skim_cnt=mask_s1.skim_cnt,
            skim_idx=mask_s1.skim_idx,
            compressed_kv=mask_s1.compressed_kv or compressed_kv,
            q_win=q_win,
            enable_three_tier=use_three_tier,
        )

    # 5. Final (t=1): zero-overhead reuse of _STEP1_READY_MASKS / _STEP1_PARITY_MASKS built at Step 1 (t=500)
    prebuilt = _STEP1_READY_MASKS.get((spec.chunk_id, layer_idx))
    if prebuilt is None:
        prebuilt = _STEP1_PARITY_MASKS.get((s1_par, spec.M_q, layer_idx))
    if (
        prebuilt is not None
        and prebuilt.L_q == spec.L_q
        and prebuilt.M_q == spec.M_q
        and (
            has_sparse_meta
            or (prebuilt.L_k == spec.L_k and prebuilt.M_cand == spec.M_cand)
        )
    ):
        cand_cnt_use = (
            sparse_num_full_gpu[branch, layer_idx, :H_local]
            if sparse_num_full_gpu is not None
            else prebuilt.cand_cnt
        )
        return launch_zing_block_sparse_attn(
            q,
            k,
            v,
            scale,
            spec.L_k,
            spec.M_cand,
            spec.M_k,
            cand_cnt_use,
            prebuilt.cand_idx,
            prebuilt.head_order,
            meta_branch_gpu=meta_branch_gpu,
            enable_virtual_mean=use_virtual_mean,
            k_blk_mean=prebuilt.k_blk_mean,
            v_blk_mean=prebuilt.v_blk_mean,
            tau_k=prebuilt.tau_k,
            skim_cnt=prebuilt.skim_cnt,
            skim_idx=prebuilt.skim_idx,
            compressed_kv=prebuilt.compressed_kv or compressed_kv,
            q_win=q_win,
            enable_three_tier=use_three_tier,
        )

    # Standalone step fallback
    _, mask_fb, _ = fused_route_and_build_masks(
        q_first=q,
        q_second=None,
        k=k,
        layer_idx=layer_idx,
        tau=spec.tau,
        L_q=spec.L_q,
        M_q=spec.M_q,
        M_cand=spec.M_cand,
        M_prefix=spec.M_prefix,
        safety_scale=spec.safety_scale,
        build_src=False,
        L_k_src=0,
        M_k_src=0,
        M_cur_src=0,
        build_s0=True,
        L_k_s0=spec.L_k,
        M_k_s0=spec.M_k,
        M_cur_s0=spec.M_cur,
        build_s1=False,
        s_evict=0,
        L_k_s1=0,
        M_k_s1=0,
        M_cand_s1=0,
        M_cur_s1=0,
        head_start=head_start,
        num_heads=H_local,
        s1_parity=s1_par,
        blk_kind_sig=spec.blk_kind_sig,
        sparse_meta_gpu=sparse_meta_gpu,
        sparse_blk_kind_gpu=sparse_blk_kind_gpu,
        sparse_k_cand_gpu=sparse_k_cand_gpu,
        sparse_num_full_gpu=sparse_num_full_gpu,
        src_branch_idx=branch,
        s0_branch_idx=branch,
        v=v,
        enable_triage_score=use_triage_score,
        enable_virtual_mean=use_virtual_mean,
        price_pi=price_pi,
        enable_three_tier=use_three_tier,
        c_rf=c_rf,
        alpha_triage=alpha_triage,
        compressed_kv=compressed_kv,
    )
    if mask_fb is None:
        if orig_fixed_fa4 is not None:
            return orig_fixed_fa4(q, k, v, scale, metadata, optimized=optimized)
        return _run_dense_branch(
            q,
            k,
            v,
            scale,
            fixed_tensors or {},
            branch,
            optimized,
            target_736p=target_736p,
        )

    cand_cnt_use = (
        sparse_num_full_gpu[branch, layer_idx, :H_local]
        if sparse_num_full_gpu is not None
        else mask_fb.cand_cnt
    )
    return launch_zing_block_sparse_attn(
        q,
        k,
        v,
        scale,
        spec.L_k,
        spec.M_cand,
        spec.M_k,
        cand_cnt_use,
        mask_fb.cand_idx,
        mask_fb.head_order,
        meta_branch_gpu=meta_branch_gpu,
        enable_virtual_mean=use_virtual_mean,
        k_blk_mean=mask_fb.k_blk_mean,
        v_blk_mean=mask_fb.v_blk_mean,
        tau_k=mask_fb.tau_k,
        skim_cnt=mask_fb.skim_cnt,
        skim_idx=mask_fb.skim_idx,
        compressed_kv=mask_fb.compressed_kv or compressed_kv,
        q_win=q_win,
        enable_three_tier=use_three_tier,
    )


def _build_sparse_branches_if_needed(
    fixed: Any, fixed_tensors: dict[str, Any], mode: str
) -> dict[int, SparseBranchSpec]:
    """Populate default SparseBranchSpecs on fixed plan if attach_sparse_specs_to_plan was not called."""
    sparse_branches = getattr(fixed, "_sparse_branches", None)
    if sparse_branches is not None:
        return sparse_branches

    tau = get_sparse_budget_tau(mode)
    min_chunk = get_min_sparse_chunk()
    is_capturing = (
        torch.cuda.is_available() and torch.cuda.is_current_stream_capturing()
    )

    pos = fixed_tensors.get("current_positions")
    if pos is not None and pos.numel() > 0 and not is_capturing:
        u_cur = int(pos[0, 0].item())
    else:
        L_q_0 = fixed.ends[0]
        tpf = infer_tokens_per_frame(L_q_0)
        u_cur = fixed.write_start // max(1, 3 * tpf)

    effective_mode = (
        mode
        if is_three_tier_enabled(mode)
        else ("dense" if u_cur < min_chunk else mode)
    )
    num_branches = len(fixed.ends)
    if num_branches == 3:
        branch_phases = ("final", "source", "active")
    elif num_branches == 1:
        branch_phases = ("active",)
    else:
        branch_phases = tuple(f"branch_{i}" for i in range(num_branches))

    start = 0
    sparse_branches = {}
    M_prefix = min(fixed.write_start // BLOCK_SIZE, 20)

    for b_idx, (b_phase, stop) in enumerate(zip(branch_phases, fixed.ends)):
        L_q = stop - start
        cu_k = fixed_tensors.get(f"cu_k.{b_idx}")
        L_k = (
            int(cu_k[1].item())
            if (cu_k is not None and not is_capturing)
            else (fixed.write_start + stop)
        )
        M_q = (L_q + BLOCK_SIZE - 1) // BLOCK_SIZE
        M_k = (L_k + BLOCK_SIZE - 1) // BLOCK_SIZE
        M_cand = fixed.write_start // BLOCK_SIZE
        M_cur = M_k - M_cand

        sparse_branches[b_idx] = SparseBranchSpec(
            mode=effective_mode,
            tau=tau,
            case_id="runtime",
            chunk_id=u_cur,
            b_phase=b_phase,
            step_idx=0 if b_phase == "source" else (99 if b_phase == "final" else 0),
            step_1000=0 if b_phase == "source" else (1 if b_phase == "final" else 1000),
            q_start=start,
            q_stop=stop,
            L_q=L_q,
            L_k=L_k,
            s_cur_chunk=fixed.write_start,
            M_q=M_q,
            M_k=M_k,
            M_cand=M_cand,
            M_cur=M_cur,
            M_prefix=min(M_prefix, M_cand),
            safety_scale=1.0,
            s_evict=fixed.write_start,
            L_evict=0,
            s_cur_chunk_step1=fixed.write_start,
            L_k_step1=L_k,
            M_k_step1=M_k,
            M_cand_step1=M_cand,
            M_cur_step1=M_cur,
        )
        start = stop

    for b_idx, spec in sparse_branches.items():
        if spec.b_phase == "source" and (b_idx + 1) in sparse_branches:
            nxt = sparse_branches[b_idx + 1]
            if nxt.b_phase == "active" and nxt.chunk_id == spec.chunk_id:
                spec.companion_step0_spec = nxt

    fixed._sparse_branches = sparse_branches
    _populate_plan_sparse_tensors(fixed, sparse_branches, fixed_tensors=fixed_tensors)
    return sparse_branches


def execute_fixed_block_sparse_branches(
    q: torch.Tensor,
    keys: torch.Tensor,
    values: torch.Tensor,
    scale: float,
    index: int,
    fixed: Any,
    fixed_tensors: dict[str, Any],
    *,
    ulysses_rank: int = 0,
    optimized: bool = False,
    target_736p: bool = False,
) -> list[torch.Tensor]:
    """Route all fixed branches through Step C Block-Sparse Attention (or dense fallback)."""
    mode = get_sparse_mode()
    sparse_branches = getattr(fixed, "_sparse_branches", None)
    if sparse_branches is None and mode != "dense":
        sparse_branches = _build_sparse_branches_if_needed(fixed, fixed_tensors, mode)

    # SPEC Rev 7: Ensure compressed_kv is non-None in production fixed paths to execute Refine/Skim/Skip
    active_modes = (
        {sp.mode for sp in sparse_branches.values()} if sparse_branches else set()
    )
    use_three_tier = any(
        is_three_tier_enabled(m) for m in active_modes
    ) or is_three_tier_enabled(mode)
    if fixed_tensors is not None and use_three_tier:
        ckv_by_layer = getattr(fixed, "compressed_kv_by_layer", None)
        if ckv_by_layer is None and "compressed_kv_by_layer" in fixed_tensors:
            ckv_by_layer = fixed_tensors["compressed_kv_by_layer"]

        if ckv_by_layer is not None and index < len(ckv_by_layer):
            layer_ckv = ckv_by_layer[index]
            fixed_tensors["compressed_kv"] = layer_ckv
        elif (
            "compressed_kv" not in fixed_tensors
            or fixed_tensors["compressed_kv"] is None
        ):
            ckv = getattr(fixed, "compressed_kv", None)
            store = getattr(fixed, "_compressed_kv_store", None)
            if ckv is not None:
                fixed_tensors["compressed_kv"] = ckv
            elif store is not None:
                fixed_tensors["compressed_kv"] = store.as_kernel_dict()
            elif keys is not None and values is not None and use_three_tier:
                L_k = keys.shape[0]
                if L_k > 0:
                    M_k = max(1, (L_k + BLOCK_SIZE - 1) // BLOCK_SIZE)
                    auto_store = ZingCompressedKVStore(
                        max_blocks=max(M_k, 512),
                        num_heads=q.shape[1],
                        head_dim=q.shape[2],
                        device=q.device,
                    )
                    auto_store.append_chunk(keys[:L_k], values[:L_k], chunk_id=0)
                    try:
                        fixed._compressed_kv_store = auto_store
                    except Exception:
                        pass
                    fixed_tensors["compressed_kv"] = auto_store.as_kernel_dict()
    elif fixed_tensors is not None:
        fixed_tensors.pop("compressed_kv", None)
        fixed_tensors.pop("compressed_kv_by_layer", None)

    if (index == 0 and not is_three_tier_enabled(mode)) or not sparse_branches:
        results, start = [], 0
        for branch, stop in enumerate(fixed.ends):
            query = q[start:stop]
            out = _run_dense_branch(
                query,
                keys,
                values,
                scale,
                fixed_tensors,
                branch,
                optimized,
                target_736p=target_736p,
            )
            results.append(out)
            start = stop
        return results

    results, start = [], 0
    for branch, stop in enumerate(fixed.ends):
        query = q[start:stop] if start == 0 else q[start:stop].clone()
        spec = sparse_branches.get(branch)
        if spec is None:
            out = _run_dense_branch(
                query,
                keys,
                values,
                scale,
                fixed_tensors,
                branch,
                optimized,
                target_736p=target_736p,
            )
        else:
            out = execute_branch_attention(
                None,
                query,
                keys,
                values,
                scale,
                metadata=None,
                optimized=optimized,
                layer_idx=index,
                spec=spec,
                ulysses_rank=ulysses_rank,
                fixed_tensors=fixed_tensors,
                branch=branch,
                q_full=q,
                target_736p=target_736p,
            )
        results.append(out)
        start = stop
    return results


def _populate_plan_sparse_tensors(
    kv_plan: Any,
    sparse_branches: dict[int, SparseBranchSpec],
    *,
    plan: Any = None,
    fixed_tensors: dict[str, Any] | None = None,
) -> None:
    """Populate static-shape int32 device tensors on kv_plan.tensors & plan.tensors for zero-recapture CUDAGraphs."""
    tensors = (
        fixed_tensors
        if fixed_tensors is not None
        else getattr(kv_plan, "tensors", None)
    )
    if not isinstance(tensors, dict):
        return

    stores = getattr(kv_plan, "stores", None)
    dev = None
    h_local = NUM_HEADS
    if stores and len(stores) > 0 and len(stores[0]) > 0:
        sample_k = stores[0][0]
        if hasattr(sample_k, "device"):
            dev = sample_k.device
            h_local = int(sample_k.shape[1])
    if dev is None:
        for v in tensors.values():
            if isinstance(v, torch.Tensor):
                dev = v.device
                break
    if dev is None:
        return

    is_capturing = (
        dev.type == "cuda"
        and torch.cuda.is_available()
        and torch.cuda.is_current_stream_capturing()
    )
    if is_capturing:
        return

    u_rank = 0
    try:
        from sglang.multimodal_gen.runtime.models.dits import zing_h3

        _, u_rank = zing_h3.get_ulysses_ctx()
    except Exception:
        u_rank = 0
    h_start = u_rank * h_local

    meta_cpu = torch.zeros((SPARSE_META_SIZE,), dtype=torch.int32)
    blk_kind_cpu = torch.full((SPARSE_BLK_KIND_CAP,), KIND_WIN_FIN, dtype=torch.int32)
    k_cand_cpu = torch.zeros((4, NUM_LAYERS, h_local), dtype=torch.int32)
    num_full_cpu = torch.zeros((4, NUM_LAYERS, h_local), dtype=torch.int32)

    if sparse_branches:
        if dev.type == "cuda":
            max_mq = max(sp.M_q for sp in sparse_branches.values())
            max_mc = max(max(sp.M_cand, sp.M_k) for sp in sparse_branches.values())
            _get_workspace(dev, num_heads=h_local, req_m_q=max_mq, req_m_cand=max_mc)

        router_sp: SparseBranchSpec | None = None
        for b_idx, sp in sparse_branches.items():
            if 0 <= b_idx < 4:
                base = META_BRANCH_BASE + 4 * b_idx
                meta_cpu[base + 0] = sp.L_k
                meta_cpu[base + 1] = sp.M_cand
                meta_cpu[base + 2] = sp.M_k
                meta_cpu[base + 3] = max(0, sp.M_k - 1 - sp.M_cand)

            if sp.mode != "dense" and sp.M_cand > 8:
                if router_sp is None or sp.b_phase == "source":
                    router_sp = sp
                m_full_b = max(0, sp.M_k - 1 - sp.M_cand)
                step_k = (
                    "source_t0"
                    if sp.b_phase == "source"
                    else (
                        "target_t1000"
                        if (sp.b_phase == "active" and sp.step_idx == 0)
                        else "target_t500"
                    )
                )
                kc_b = _compute_vectorized_k_cand_cpu(
                    step_k,
                    sp.tau,
                    sp.M_cand,
                    sp.M_prefix,
                    sp.M_q,
                    sp.safety_scale,
                    h_start,
                    h_local,
                )
                if 0 <= b_idx < 4:
                    k_cand_cpu[b_idx] = kc_b
                    num_full_cpu[b_idx] = kc_b + m_full_b

        if router_sp is not None:
            M_cand = router_sp.M_cand
            M_prefix = min(max(0, router_sp.M_prefix), M_cand)
            m_full_src = max(0, router_sp.M_k - 1 - M_cand)
            comp = (
                router_sp.companion_step0_spec
                if router_sp.b_phase == "source"
                else router_sp
            )
            if comp is not None:
                m_full_s0 = max(0, comp.M_k - 1 - M_cand)
                has_step1_lookahead = comp.M_cand_step1 > 0 and comp.L_k_step1 > 0
                effective_l_evict = (
                    comp.L_evict
                    if comp.L_evict > 0
                    else (
                        max(0, comp.L_k - comp.L_k_step1) if has_step1_lookahead else 0
                    )
                )
                shift_blks = (
                    max(1, M_cand - comp.M_cand_step1)
                    if (has_step1_lookahead and effective_l_evict > 0)
                    else 0
                )
                effective_mc_s1 = (
                    min(comp.M_cand_step1, max(0, M_cand - shift_blks))
                    if has_step1_lookahead
                    else M_cand
                )
                L_k_s1 = comp.L_k_step1 if has_step1_lookahead else comp.L_k
                M_k_s1 = comp.M_k_step1 if has_step1_lookahead else comp.M_k
                m_full_s1 = max(0, M_k_s1 - 1 - effective_mc_s1)
                s_evict_blk = (
                    comp.s_evict // BLOCK_SIZE
                    if (has_step1_lookahead and effective_l_evict > 0)
                    else M_cand
                )
                L_k_s0 = comp.L_k
                M_k_s0 = comp.M_k
                if effective_mc_s1 > 8:
                    kc_s1 = _compute_vectorized_k_cand_cpu(
                        "target_t500",
                        router_sp.tau,
                        effective_mc_s1,
                        min(M_prefix, effective_mc_s1),
                        comp.M_q,
                        router_sp.safety_scale,
                        h_start,
                        h_local,
                    )
                    k_cand_cpu[3] = kc_s1
                    num_full_cpu[3] = kc_s1 + m_full_s1
            else:
                m_full_s0 = 0
                effective_mc_s1 = 0
                m_full_s1 = 0
                s_evict_blk = 0
                shift_blks = 0
                L_k_s0 = 0
                M_k_s0 = 0
                L_k_s1 = 0
                M_k_s1 = 0

            meta_cpu[META_M_CAND] = M_cand
            meta_cpu[META_M_PREFIX] = M_prefix
            meta_cpu[META_L_K_SRC] = router_sp.L_k
            meta_cpu[META_M_K_SRC] = router_sp.M_k
            meta_cpu[META_M_FULL_SRC] = m_full_src
            meta_cpu[META_L_K_S0] = L_k_s0
            meta_cpu[META_M_K_S0] = M_k_s0
            meta_cpu[META_M_FULL_S0] = m_full_s0
            meta_cpu[META_L_K_S1] = L_k_s1
            meta_cpu[META_M_K_S1] = M_k_s1
            meta_cpu[META_M_CAND_S1] = effective_mc_s1
            meta_cpu[META_M_FULL_S1] = m_full_s1
            meta_cpu[META_B_EVICT_LO] = s_evict_blk
            meta_cpu[META_B_EVICT_HI] = s_evict_blk + shift_blks
            meta_cpu[META_SHIFT_S1] = shift_blks
            k_cap_blks_meta = (
                int(stores[0][0].shape[0]) // BLOCK_SIZE
                if (stores and len(stores) > 0 and len(stores[0]) > 0)
                else 512
            )
            meta_cpu[META_M_CAND_CAP] = (
                512
                if (
                    infer_tokens_per_frame(router_sp.L_q) <= 390
                    and k_cap_blks_meta <= 512
                    and M_cand <= 512
                )
                else 1024
            )

            mc_cap = min(M_cand, SPARSE_BLK_KIND_CAP)
            if router_sp.blk_kind_sig is not None and len(router_sp.blk_kind_sig) == 4:
                _, role4_spans, sink_span, win_src_spans = router_sp.blk_kind_sig
                if M_prefix > 0:
                    blk_kind_cpu[: min(M_prefix, mc_cap)] = KIND_TEXT
                for s, e in role4_spans:
                    s_c, e_c = max(0, min(s, mc_cap)), max(0, min(e, mc_cap))
                    if e_c > s_c:
                        blk_kind_cpu[s_c:e_c] = KIND_REF_VIS
                if sink_span is not None:
                    sink_iter = (
                        sink_span
                        if (len(sink_span) > 0 and isinstance(sink_span[0], tuple))
                        else (sink_span,)
                    )
                    for s, e in sink_iter:
                        s_c, e_c = max(0, min(s, mc_cap)), max(0, min(e, mc_cap))
                        if e_c > s_c:
                            blk_kind_cpu[s_c:e_c] = KIND_SINK
                for s, e in win_src_spans:
                    s_c, e_c = max(0, min(s, mc_cap)), max(0, min(e, mc_cap))
                    if e_c > s_c:
                        blk_kind_cpu[s_c:e_c] = KIND_WIN_SRC
            else:
                p_end = min(M_prefix, mc_cap)
                if p_end > 0:
                    t_end = min(3, p_end)
                    blk_kind_cpu[:t_end] = KIND_TEXT
                    if p_end > t_end:
                        blk_kind_cpu[t_end:p_end] = KIND_REF_VIS
                s_end = min(M_prefix + 38, mc_cap)
                if s_end > p_end:
                    blk_kind_cpu[p_end:s_end] = KIND_SINK

    sparse_tensors = {
        "sparse_meta": meta_cpu.to(device=dev),
        "sparse_blk_kind": blk_kind_cpu.to(device=dev),
        "sparse_k_cand": k_cand_cpu.to(device=dev),
        "sparse_num_full": num_full_cpu.to(device=dev),
    }

    if getattr(kv_plan, "compressed_attention_layout", None) is not None:
        # The v2 adapter builds a complete, rotated layer view during execution.
        # Never expose uninitialized resident capacity as live attention rows.
        return

    # Ensure ZingCompressedKVStore instances are bound and passed to fixed_tensors per layer
    active_modes = (
        {sp.mode for sp in sparse_branches.values()} if sparse_branches else set()
    )
    use_three_tier = any(is_three_tier_enabled(m) for m in active_modes) or (
        len(active_modes) == 0 and is_three_tier_enabled()
    )

    compressed_stores = getattr(kv_plan, "_compressed_kv_stores", None)
    if compressed_stores is None and plan is not None:
        compressed_stores = getattr(plan, "_compressed_kv_stores", None)

    if compressed_stores is None and use_three_tier:
        max_mc = max(
            512,
            meta_cpu[META_M_CAND_CAP].item() if meta_cpu[META_M_CAND_CAP] > 0 else 512,
        )
        if stores and len(stores) > 0:
            compressed_stores = []
            for l_idx in range(len(stores)):
                if len(stores[l_idx]) >= 2:
                    sample_k, sample_v = stores[l_idx]
                    h_l = int(sample_k.shape[1]) if sample_k.ndim >= 2 else h_local
                    d_l = int(sample_k.shape[2]) if sample_k.ndim >= 3 else HEAD_DIM
                else:
                    h_l, d_l = h_local, HEAD_DIM
                c_s = ZingCompressedKVStore(
                    max_blocks=max_mc,
                    num_heads=h_l,
                    head_dim=d_l,
                    device=dev,
                )
                if len(stores[l_idx]) >= 2:
                    sample_k, sample_v = stores[l_idx]
                    w_start = getattr(kv_plan, "write_start", 0) or 0
                    if w_start > 0 and sample_k.shape[0] >= w_start:
                        c_s.append_chunk(
                            sample_k[:w_start], sample_v[:w_start], chunk_id=0
                        )
                compressed_stores.append(c_s)
            try:
                kv_plan._compressed_kv_stores = compressed_stores
                kv_plan._compressed_kv_store = compressed_stores[0]
            except Exception:
                pass
        else:
            single_store = getattr(kv_plan, "_compressed_kv_store", None)
            if single_store is None or single_store.max_blocks < max_mc:
                single_store = ZingCompressedKVStore(
                    max_blocks=max(max_mc, 512),
                    num_heads=h_local,
                    head_dim=HEAD_DIM,
                    device=dev,
                )
                try:
                    kv_plan._compressed_kv_store = single_store
                except Exception:
                    pass
            compressed_stores = [single_store]

    if use_three_tier and compressed_stores is not None and len(compressed_stores) > 0:
        ckv_by_layer = []
        for s in compressed_stores:
            if s is not None:
                max_mk = (
                    max((sp.M_k for sp in sparse_branches.values()), default=0)
                    if sparse_branches
                    else 0
                )
                m_k_active = max(max_mk, s.num_blocks) if max_mk > 0 else s.num_blocks
                ckv_by_layer.append(s.as_kernel_dict(num_blocks=max(1, m_k_active)))
            else:
                ckv_by_layer.append(None)
        try:
            kv_plan.compressed_kv_by_layer = ckv_by_layer
            kv_plan.compressed_kv = ckv_by_layer[0] if ckv_by_layer else None
        except Exception:
            pass
        if plan is not None:
            try:
                plan.compressed_kv_by_layer = ckv_by_layer
                plan.compressed_kv = ckv_by_layer[0] if ckv_by_layer else None
            except Exception:
                pass
        if fixed_tensors is not None:
            fixed_tensors["compressed_kv_by_layer"] = ckv_by_layer
            fixed_tensors["compressed_kv"] = ckv_by_layer[0] if ckv_by_layer else None

    tensors.update(sparse_tensors)
    if (
        fixed_tensors is None
        and hasattr(kv_plan, "tensors")
        and isinstance(kv_plan.tensors, dict)
    ):
        kv_plan.tensors.update(sparse_tensors)
    plan_tensors = getattr(plan, "tensors", None) if plan is not None else None
    if isinstance(plan_tensors, dict):
        for k_name, v_ten in sparse_tensors.items():
            if isinstance(v_ten, torch.Tensor):
                plan_tensors[f"kv.{k_name}"] = v_ten


def attach_sparse_specs_to_plan(
    sampler: Any,
    shadow_before_history: list[tuple[str, int, int, int]],
    window_policy: Any,
    packed: dict[str, Any],
    phase: str,
    kv_plan: Any,
    state_cfg: dict[str, Any],
    *,
    shadow: Any = None,
    plan: Any = None,
) -> dict[int, SparseBranchSpec]:
    """Attach SparseBranchSpec objects to fixed KV plan (called by ZingChunkGraphs)."""
    global _LAST_PREFIX_ROLE4_SPANS
    if shadow is not None:
        if getattr(shadow, "_compressed_kv_stores", None) is not None:
            try:
                if kv_plan is not None:
                    kv_plan._compressed_kv_stores = shadow._compressed_kv_stores
                    kv_plan._compressed_kv_store = shadow._compressed_kv_stores[0]
            except Exception:
                pass
        elif getattr(shadow, "_compressed_kv_store", None) is not None:
            try:
                if kv_plan is not None:
                    kv_plan._compressed_kv_store = shadow._compressed_kv_store
            except Exception:
                pass
    host = packed.get("_zing_host_layout")
    branch_phases = packed.get("_zing_joint_phases") if phase == "joint" else (phase,)
    has_prefix_branch = (phase == "prefix") or ("prefix" in branch_phases)
    has_history_branch = "history" in branch_phases

    if has_prefix_branch:
        if host is not None and hasattr(host, "row_role") and host.row_role is not None:
            role = host.row_role
            role_cpu = role.cpu() if hasattr(role, "cpu") else role
            if phase == "prefix":
                role_slice = role_cpu
            else:
                p_idx = list(branch_phases).index("prefix")
                p_start = 0 if p_idx == 0 else int(kv_plan.ends[p_idx - 1])
                p_stop = int(kv_plan.ends[p_idx])
                role_slice = role_cpu[p_start:p_stop]
            spans = tuple(_find_contiguous_spans(role_slice == 4))
            _LAST_PREFIX_ROLE4_SPANS = (int(role_slice.numel()), spans)
            pref_obj = getattr(shadow, "prefix", None) if shadow is not None else None
            pref_sig = getattr(pref_obj, "position_signature", None)
            if pref_sig is not None:
                if len(_PREFIX_ROLE4_BY_SIG) >= 64:
                    _PREFIX_ROLE4_BY_SIG.pop(next(iter(_PREFIX_ROLE4_BY_SIG)))
                _PREFIX_ROLE4_BY_SIG[pref_sig] = spans
    elif has_history_branch and shadow is not None:
        pref_obj = getattr(shadow, "prefix", None)
        if pref_obj is not None:
            pref_sig = getattr(pref_obj, "position_signature", None)
            pos = getattr(pref_obj, "host_positions", None)
            L_p = (
                int(pos.shape[0]) if (pos is not None and hasattr(pos, "shape")) else 0
            )
            if pref_sig is not None and pref_sig in _PREFIX_ROLE4_BY_SIG:
                _LAST_PREFIX_ROLE4_SPANS = (L_p, _PREFIX_ROLE4_BY_SIG[pref_sig])
            elif pos is not None and L_p > 0:
                spans = _infer_role4_spans_from_positions(pos)
                _LAST_PREFIX_ROLE4_SPANS = (L_p, spans)
                if pref_sig is not None:
                    _PREFIX_ROLE4_BY_SIG[pref_sig] = spans

    mode = str(state_cfg.get("mode", get_sparse_mode()))
    if phase == "prefix" or has_prefix_branch or has_history_branch or mode == "dense":
        if mode == "dense":
            clear_sparse_caches()
        else:
            _STEP0_READY_MASKS.clear()
            _STEP1_READY_MASKS.clear()
        kv_plan._sparse_branches = {}
        _populate_plan_sparse_tensors(kv_plan, {}, plan=plan)
        return {}

    tau = str(state_cfg.get("tau", get_sparse_budget_tau(mode)))
    case_id = str(state_cfg.get("case_id", "unknown"))
    safety_scale = float(state_cfg.get("safety_scale", 1.0))
    min_chunk = get_min_sparse_chunk()

    prefix_ends = [e for kind, _, _, e in shadow_before_history if kind == "prefix"]
    L_prefix = max(prefix_ends) if prefix_ends else 0
    M_prefix = L_prefix // BLOCK_SIZE

    host_t = packed.get("_zing_host_t")

    current_items: list[tuple[str, int, int, int, int, int]] = []
    for b_idx, (b_phase, stop) in enumerate(zip(branch_phases, kv_plan.ends)):
        start = 0 if b_idx == 0 else kv_plan.ends[b_idx - 1]
        s = int(kv_plan.write_start) + int(start)
        e = int(kv_plan.write_start) + int(stop)
        if host is not None and hasattr(host, "block_idx"):
            b_block = int(host.block_idx[start].item())
            if b_phase == "prefix":
                u = -1
            elif b_phase == "source":
                u = (b_block - 1) // 2
            else:
                u = b_block // 2 - 1
        else:
            u = int(kv_plan.write_start) // max(
                1, 3 * infer_tokens_per_frame(stop - start)
            )
        current_items.append((b_phase, u, s, e, int(start), int(stop)))

    sparse_branches: dict[int, SparseBranchSpec] = {}
    for b_idx, (b_phase, u_cur, s_cur, e_cur, q_start, q_stop) in enumerate(
        current_items
    ):
        if b_phase not in ("source", "active", "final") or u_cur < 0:
            continue
        effective_mode = "dense" if u_cur < min_chunk else mode

        if b_phase == "source":
            step_idx = 0
            step_1000 = 0
        elif b_phase == "final":
            step_idx = 99
            step_1000 = 1
        else:
            step_idx = 0
            step_1000 = 1000
            if host_t is not None and sampler is not None:
                t_val = float(host_t[q_start].item())
                init_cnt = getattr(sampler, "initial_block_count", 0) or 0
                if (
                    init_cnt > 0
                    and u_cur < init_cnt
                    and getattr(sampler, "initial_schedulers", None)
                ):
                    sched_t = sampler.initial_schedulers[0].timesteps
                    s_list = getattr(sampler, "initial_denoising_step_list", None)
                else:
                    sched = getattr(sampler, "video_scheduler", None)
                    sched_t = getattr(sched, "timesteps", None)
                    s_list = getattr(sampler, "denoising_step_list", None)
                if sched_t is not None:
                    diffs = [abs(float(x.item()) - t_val) for x in sched_t]
                    step_idx = int(min(range(len(diffs)), key=lambda i: diffs[i]))
                    if s_list is not None and step_idx < len(s_list):
                        step_1000 = int(s_list[step_idx])
                    else:
                        sigma = 1.0 - t_val
                        step_1000 = int(
                            round(1000.0 * sigma / max(1e-6, 5.0 - 4.0 * sigma))
                        )

        all_visible = list(shadow_before_history) + [
            (kind, u, s, e) for (kind, u, s, e, _, _) in current_items[: b_idx + 1]
        ]
        cur_starts = [s for _, u, s, _ in all_visible if u == u_cur]
        s_cur_chunk = min(cur_starts) if cur_starts else s_cur

        L_q = q_stop - q_start
        L_k = e_cur
        M_q = (L_q + BLOCK_SIZE - 1) // BLOCK_SIZE
        M_k = (L_k + BLOCK_SIZE - 1) // BLOCK_SIZE
        M_cand = s_cur_chunk // BLOCK_SIZE
        M_cur = M_k - M_cand

        s_evict = s_cur_chunk
        L_evict = 0
        s_cur_chunk_step1 = s_cur_chunk
        L_k_step1 = L_k
        M_k_step1 = M_k
        M_cand_step1 = M_cand
        M_cur_step1 = M_cur

        if b_phase == "active" and step_idx == 0 and window_policy is not None:
            evicted_spans = [
                (s, e)
                for _, u, s, e in all_visible
                if 0 <= u < u_cur and not window_policy.retains(u, u_cur)
            ]
            if evicted_spans:
                s_evict = min(s for s, _ in evicted_spans)
                e_evict = max(e for _, e in evicted_spans)
                L_evict = max(0, e_evict - s_evict)
            s_cur_chunk_step1 = s_cur_chunk - L_evict
            L_k_step1 = L_k - L_evict
            M_k_step1 = (L_k_step1 + BLOCK_SIZE - 1) // BLOCK_SIZE
            M_cand_step1 = s_cur_chunk_step1 // BLOCK_SIZE
            M_cur_step1 = M_k_step1 - M_cand_step1

            for k_old in list(_STEP1_READY_MASKS.keys()):
                if k_old[0] < u_cur - 1:
                    _STEP1_READY_MASKS.pop(k_old, None)
            for k_old in list(_STEP0_READY_MASKS.keys()):
                if k_old[0] < u_cur:
                    _STEP0_READY_MASKS.pop(k_old, None)

        # Determine 5-segment block kinds for M_cand candidate blocks
        blk_kinds: list[int] = [KIND_WIN_FIN] * M_cand
        sink_chunks = int(getattr(window_policy, "sink_chunks", 0) or 0)
        is_sink_fn = getattr(window_policy, "is_sink", None)

        pref_spans = ()
        if _LAST_PREFIX_ROLE4_SPANS[0] == L_prefix and _LAST_PREFIX_ROLE4_SPANS[1]:
            pref_spans = _LAST_PREFIX_ROLE4_SPANS[1]
        elif _LAST_SHADOW_META.get("role4_spans"):
            pref_spans = _LAST_SHADOW_META["role4_spans"]

        for b in range(M_cand):
            mid = b * BLOCK_SIZE + (BLOCK_SIZE // 2)
            if mid < L_prefix:
                if not pref_spans:
                    blk_kinds[b] = KIND_REF_VIS
                elif any(s <= mid < e for s, e in pref_spans):
                    blk_kinds[b] = KIND_REF_VIS
                else:
                    blk_kinds[b] = KIND_TEXT
            elif mid < s_cur_chunk:
                for ch_kind, ch_u, ch_s, ch_e in all_visible:
                    if ch_s <= mid < ch_e:
                        is_sink_chunk = (
                            bool(is_sink_fn(ch_u))
                            if callable(is_sink_fn)
                            else (0 <= ch_u < sink_chunks)
                        )
                        if (
                            ch_kind in ("committed", "source", "final")
                            and is_sink_chunk
                        ):
                            blk_kinds[b] = KIND_SINK
                        elif ch_kind == "source":
                            blk_kinds[b] = KIND_WIN_SRC
                        elif ch_kind == "final":
                            blk_kinds[b] = KIND_WIN_FIN
                        elif ch_kind == "committed" and not is_sink_chunk:
                            src_len = _LAST_SHADOW_META.get("chunk_src_lens", {}).get(
                                (ch_u, ch_s, ch_e), (ch_e - ch_s) // 2
                            )
                            if mid < ch_s + src_len:
                                blk_kinds[b] = KIND_WIN_SRC
                            else:
                                blk_kinds[b] = KIND_WIN_FIN
                        break

        role4_blk_spans = tuple(
            _find_contiguous_spans([k == KIND_REF_VIS for k in blk_kinds])
        )
        sink_blk_spans = tuple(
            _find_contiguous_spans([k == KIND_SINK for k in blk_kinds])
        )
        sink_blk_span = (
            (sink_blk_spans[0] if len(sink_blk_spans) == 1 else sink_blk_spans)
            if sink_blk_spans
            else None
        )
        win_src_blk_spans = tuple(
            _find_contiguous_spans([k == KIND_WIN_SRC for k in blk_kinds])
        )
        blk_kind_sig = (M_cand, role4_blk_spans, sink_blk_span, win_src_blk_spans)

        sparse_branches[b_idx] = SparseBranchSpec(
            mode=effective_mode,
            tau=tau,
            case_id=case_id,
            chunk_id=u_cur,
            b_phase=b_phase,
            step_idx=step_idx,
            step_1000=step_1000,
            q_start=q_start,
            q_stop=q_stop,
            L_q=L_q,
            L_k=L_k,
            s_cur_chunk=s_cur_chunk,
            M_q=M_q,
            M_k=M_k,
            M_cand=M_cand,
            M_cur=M_cur,
            M_prefix=min(M_prefix, M_cand),
            safety_scale=safety_scale,
            s_evict=s_evict,
            L_evict=L_evict,
            s_cur_chunk_step1=s_cur_chunk_step1,
            L_k_step1=L_k_step1,
            M_k_step1=M_k_step1,
            M_cand_step1=M_cand_step1,
            M_cur_step1=M_cur_step1,
            blk_kind_sig=blk_kind_sig,
        )

    for b_idx, spec in sparse_branches.items():
        if spec.b_phase == "source" and (b_idx + 1) in sparse_branches:
            nxt = sparse_branches[b_idx + 1]
            if (
                nxt.b_phase == "active"
                and nxt.step_idx == 0
                and nxt.chunk_id == spec.chunk_id
                and nxt.M_cand == spec.M_cand
                and nxt.L_q == spec.L_q
            ):
                spec.companion_step0_spec = nxt

    kv_plan._sparse_branches = sparse_branches
    if getattr(kv_plan, "compressed_attention_layout", None) is not None:
        from .zing_h3_compressed_view import branch_spec

        kv_plan._compressed_branch_specs = {
            branch: branch_spec(kv_plan, spec)
            for branch, spec in sparse_branches.items()
        }
    _populate_plan_sparse_tensors(kv_plan, sparse_branches, plan=plan)
    return sparse_branches


def extract_history_items(shadow: Any) -> list[tuple[str, int, int, int]]:
    """Extract (kind, u, s, e) tuples from a ZingH3KVCache / shadow instance prior to commit."""
    global _LAST_SHADOW_META, _LAST_PREFIX_ROLE4_SPANS
    _LAST_SHADOW_META = {"role4_spans": (), "chunk_src_lens": {}}

    pref = getattr(shadow, "prefix", None)
    if pref is not None:
        pref_sig = getattr(pref, "position_signature", None)
        pos = getattr(pref, "host_positions", None)
        L_p = int(pos.shape[0]) if (pos is not None and hasattr(pos, "shape")) else 0
        if pref_sig is not None and pref_sig in _PREFIX_ROLE4_BY_SIG:
            spans = _PREFIX_ROLE4_BY_SIG[pref_sig]
            if L_p > 0:
                _LAST_PREFIX_ROLE4_SPANS = (L_p, spans)
            _LAST_SHADOW_META["role4_spans"] = spans
        elif pos is not None and L_p > 0:
            if pos.dim() == 2 and pos.shape[1] >= 3:
                spans = _infer_role4_spans_from_positions(pos)
                _LAST_PREFIX_ROLE4_SPANS = (L_p, spans)
                _LAST_SHADOW_META["role4_spans"] = spans
                if pref_sig is not None:
                    _PREFIX_ROLE4_BY_SIG[pref_sig] = spans
            elif _LAST_PREFIX_ROLE4_SPANS[0] == L_p and _LAST_PREFIX_ROLE4_SPANS[1]:
                _LAST_SHADOW_META["role4_spans"] = _LAST_PREFIX_ROLE4_SPANS[1]

    items: list[tuple[str, int, int, int]] = []
    hist_attr = getattr(shadow, "_history", None)
    if callable(hist_attr):
        for c_hist in hist_attr():
            s = int(c_hist.offset)
            e = s + int(c_hist.positions.shape[0])
            if c_hist is getattr(shadow, "prefix", None) or (
                getattr(c_hist, "temporal_chunk_id", None) is None
                and getattr(c_hist, "block", None) is None
            ):
                items.append(("prefix", -1, s, e))
            elif c_hist is getattr(shadow, "pending_source", None):
                u = (int(c_hist.block) - 1) // 2
                items.append(("source", u, s, e))
            else:
                u = int(c_hist.temporal_chunk_id)
                items.append(("committed", u, s, e))
                rope_parts = getattr(c_hist, "rope_parts", None)
                if rope_parts is not None and len(rope_parts) >= 2:
                    src_len = int(rope_parts[0][1])
                elif rope_parts is not None and len(rope_parts) == 1:
                    src_len = 0
                else:
                    src_len = (e - s) // 2
                _LAST_SHADOW_META["chunk_src_lens"][(u, s, e)] = src_len
        return items

    pos = 0
    history = hist_attr if hist_attr is not None else getattr(shadow, "history", ())
    for item in history:
        if hasattr(item, "kind") and hasattr(item, "length"):
            s = pos
            e = pos + int(item.length)
            items.append((str(item.kind), int(item.u), s, e))
            pos = e
        elif hasattr(item, "positions"):
            s = int(item.positions[0, 0].item()) if item.positions.numel() > 0 else pos
            e = s + int(item.positions.shape[0])
            u = int(getattr(item, "temporal_chunk_id", 0))
            items.append(("committed", u, s, e))
            rope_parts = getattr(item, "rope_parts", None)
            if rope_parts is not None and len(rope_parts) >= 2:
                src_len = int(rope_parts[0][1])
            elif rope_parts is not None and len(rope_parts) == 1:
                src_len = 0
            else:
                src_len = (e - s) // 2
            _LAST_SHADOW_META["chunk_src_lens"][(u, s, e)] = src_len
            pos = e
    return items


def read_sparse_state() -> dict[str, Any]:
    """Read sparse attention runtime configuration from environment or state file."""
    state_file = os.environ.get("ZING_SPARSE_STATE_FILE", "").strip()
    if state_file and os.path.exists(state_file):
        try:
            with open(state_file, encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                return data
        except Exception:
            pass
    mode = get_sparse_mode()
    return {
        "mode": mode,
        "tau": get_sparse_budget_tau(mode),
        "case_id": os.environ.get("ZING_SPARSE_CASE_ID", "runtime"),
        "safety_scale": float(os.environ.get("ZING_SPARSE_SAFETY_SCALE", "1.0")),
    }


def is_sparse_runtime_enabled() -> bool:
    """Return True if sparse attention runtime or state-file control is enabled."""
    if get_sparse_mode() != "dense":
        return True
    if os.environ.get("ZING_SPARSE_STATE_FILE", "").strip():
        return True
    if os.environ.get("ZING_SPARSE_STATS_FILE", "").strip():
        return True
    return False


_INSTALLED = False


def install_zing_block_sparse_attention() -> None:
    """Monkeypatch ZingChunkGraphs for backward compatibility with external tarballs."""
    global _INSTALLED
    if _INSTALLED:
        return
    try:
        from sglang.multimodal_gen.runtime.models.dits import zing_h3_denoise_graph

        orig_forward_plan = zing_h3_denoise_graph.ZingChunkGraphs._forward_plan

        def _patched_forward_plan(sampler, shadow, packed, phase, after=None):
            history_before = extract_history_items(shadow)
            plan = orig_forward_plan(sampler, shadow, packed, phase, after=after)
            attach_sparse_specs_to_plan(
                sampler,
                history_before,
                getattr(shadow, "window_policy", None),
                packed,
                phase,
                plan.kv_plan,
                read_sparse_state(),
                shadow=shadow,
                plan=plan,
            )
            return plan

        zing_h3_denoise_graph.ZingChunkGraphs._forward_plan = staticmethod(
            _patched_forward_plan
        )
        _INSTALLED = True
    except Exception:
        pass


def install_zing_sparse_attn() -> None:
    """Alias for install_zing_block_sparse_attention."""
    install_zing_block_sparse_attention()


def run_kernel_and_router_selftest() -> dict[str, Any]:
    """Run GPU numerical & CUDA Graph verification across 480p/736p and SP=1/SP=2."""
    import time

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    torch.manual_seed(42)

    results: dict[str, Any] = {}
    for res_tag, L_q, L_k, M_cand, M_cur in [
        ("480p_sp1", 1170, 27684, 396, 37),
        ("480p_sp2", 1170, 27684, 396, 37),
        ("736p_sp1", 2760, 65296, 934, 87),
        ("736p_sp2", 2760, 65296, 934, 87),
    ]:
        H = 28 if "sp2" in res_tag else 56
        head_start = 28 if "sp2" in res_tag else 0
        M_q = (L_q + BLOCK_SIZE - 1) // BLOCK_SIZE
        M_k = M_cand + M_cur
        scale = 1.0 / math.sqrt(HEAD_DIM)

        q0 = torch.randn((L_q, H, HEAD_DIM), device=device, dtype=torch.bfloat16)
        q1 = torch.randn((L_q, H, HEAD_DIM), device=device, dtype=torch.bfloat16)
        k = torch.randn((L_k, H, HEAD_DIM), device=device, dtype=torch.bfloat16)
        v = torch.randn((L_k, H, HEAD_DIM), device=device, dtype=torch.bfloat16)

        mask_src, mask_s0, mask_s1 = fused_route_and_build_masks(
            q_first=q0,
            q_second=q1,
            k=k,
            layer_idx=12,
            tau="0.95",
            L_q=L_q,
            M_q=M_q,
            M_cand=M_cand,
            M_prefix=12 if "480p" in res_tag else 29,
            safety_scale=1.0,
            build_src=True,
            L_k_src=L_k - L_q,
            M_k_src=M_cand + M_q,
            M_cur_src=M_q,
            build_s0=True,
            L_k_s0=L_k,
            M_k_s0=M_k,
            M_cur_s0=M_cur,
            build_s1=True,
            s_evict=12 * BLOCK_SIZE if "480p" in res_tag else 29 * BLOCK_SIZE,
            L_k_s1=L_k - (19 * BLOCK_SIZE if "480p" in res_tag else 44 * BLOCK_SIZE),
            M_k_s1=M_k - (19 if "480p" in res_tag else 44),
            M_cand_s1=M_cand - (19 if "480p" in res_tag else 44),
            M_cur_s1=M_cur,
            head_start=head_start,
            num_heads=H,
            s1_parity=1,
        )
        assert mask_s0 is not None and mask_src is not None and mask_s1 is not None
        m_full_s0 = M_k - 1 - M_cand
        expected_cur = torch.arange(
            M_cand, M_cand + m_full_s0, device=device, dtype=torch.int32
        )
        assert torch.equal(mask_s0.cand_idx[0, 0, :m_full_s0], expected_cur), (
            f"Current-chunk full blocks missing in {res_tag}: m_full_s0={m_full_s0}"
        )

        out_triton = launch_zing_block_sparse_attn(
            q1,
            k,
            v,
            scale,
            L_k,
            M_cand,
            M_k,
            mask_s0.cand_cnt,
            mask_s0.cand_idx,
            mask_s0.head_order,
        )

        # Reference check on first 2 heads for speed
        q_f = q1[:, :2].float().transpose(0, 1)
        k_f = k[:, :2].float().transpose(0, 1)
        v_f = v[:, :2].float().transpose(0, 1)
        out_ref_h2 = torch.zeros_like(q_f)
        for h in range(2):
            cnt = int(mask_s0.cand_cnt[h].item())
            for m in range(M_q):
                qs = m * BLOCK_SIZE
                qe = min(L_q, (m + 1) * BLOCK_SIZE)
                if qs >= qe:
                    continue
                blks = mask_s0.cand_idx[h, m, :cnt]
                tok_idx = (
                    blks[:, None] * BLOCK_SIZE
                    + torch.arange(BLOCK_SIZE, device=device)[None, :]
                ).reshape(-1)
                tok_idx = tok_idx[tok_idx < L_k]
                scores = torch.matmul(q_f[h, qs:qe], k_f[h, tok_idx].T) * scale
                probs = torch.softmax(scores, dim=-1)
                out_ref_h2[h, qs:qe] = torch.matmul(probs, v_f[h, tok_idx])
        out_ref_bf16 = out_ref_h2.transpose(0, 1).to(torch.bfloat16)
        max_err = float((out_triton[:, :2] - out_ref_bf16).abs().max().item())

        # Step 1 Triage check: KV block stats + 2nd-order complexity routing + Virtual Mean Tiles
        k_bm_t, v_bm_t, tau_k_t, rho_kv_t = compute_kv_block_stats(
            k, v, num_blocks=M_cand
        )
        _, mask_s0_triage, _ = fused_route_and_build_masks(
            q_first=q0,
            q_second=q1,
            k=k,
            v=v,
            layer_idx=12,
            tau="0.95",
            L_q=L_q,
            M_q=M_q,
            M_cand=M_cand,
            M_prefix=12 if "480p" in res_tag else 29,
            safety_scale=1.0,
            build_src=False,
            L_k_src=0,
            M_k_src=0,
            M_cur_src=0,
            build_s0=True,
            L_k_s0=L_k,
            M_k_s0=M_k,
            M_cur_s0=M_cur,
            build_s1=False,
            s_evict=0,
            L_k_s1=0,
            M_k_s1=0,
            M_cand_s1=0,
            M_cur_s1=0,
            head_start=head_start,
            num_heads=H,
            s1_parity=1,
            tau_k=tau_k_t,
            rho_kv=rho_kv_t,
            enable_triage_score=True,
        )
        assert mask_s0_triage is not None
        out_triage = launch_zing_block_sparse_attn(
            q1,
            k,
            v,
            scale,
            L_k,
            M_cand,
            M_k,
            mask_s0_triage.cand_cnt,
            mask_s0_triage.cand_idx,
            mask_s0_triage.head_order,
            enable_virtual_mean=True,
            k_blk_mean=k_bm_t,
            v_blk_mean=v_bm_t,
            tau_k=tau_k_t,
        )
        out_triage_ref_h2 = _exact_block_sparse_sdpa_reference(
            q1[:, :2],
            k[:, :2],
            v[:, :2],
            scale,
            L_k,
            M_cand,
            M_k,
            mask_s0_triage.cand_cnt[:2],
            mask_s0_triage.cand_idx[:2],
            torch.arange(2, device=device, dtype=torch.int32),
            enable_virtual_mean=True,
            k_blk_mean=k_bm_t[:2],
            v_blk_mean=v_bm_t[:2] if v_bm_t is not None else None,
            tau_k=tau_k_t[:2],
        )
        triage_max_err = float(
            (out_triage[:, :2] - out_triage_ref_h2).abs().max().item()
        )

        cg_err = 0.0
        cg_dyn_err = 0.0
        router_ms = 0.0
        kernel_ms = 0.0
        if device.type == "cuda":
            torch.cuda.synchronize()
            t0 = time.perf_counter()
            for _ in range(20):
                fused_route_and_build_masks(
                    q_first=q0,
                    q_second=q1,
                    k=k,
                    layer_idx=12,
                    tau="0.95",
                    L_q=L_q,
                    M_q=M_q,
                    M_cand=M_cand,
                    M_prefix=12 if "480p" in res_tag else 29,
                    safety_scale=1.0,
                    build_src=True,
                    L_k_src=L_k - L_q,
                    M_k_src=M_cand + M_q,
                    M_cur_src=M_q,
                    build_s0=True,
                    L_k_s0=L_k,
                    M_k_s0=M_k,
                    M_cur_s0=M_cur,
                    build_s1=True,
                    s_evict=12 * BLOCK_SIZE if "480p" in res_tag else 29 * BLOCK_SIZE,
                    L_k_s1=L_k
                    - (19 * BLOCK_SIZE if "480p" in res_tag else 44 * BLOCK_SIZE),
                    M_k_s1=M_k - (19 if "480p" in res_tag else 44),
                    M_cand_s1=M_cand - (19 if "480p" in res_tag else 44),
                    M_cur_s1=M_cur,
                    head_start=head_start,
                    num_heads=H,
                    s1_parity=1,
                )
            torch.cuda.synchronize()
            router_ms = (time.perf_counter() - t0) * 1000.0 / 20.0

            t0 = time.perf_counter()
            for _ in range(20):
                launch_zing_block_sparse_attn(
                    q1,
                    k,
                    v,
                    scale,
                    L_k,
                    M_cand,
                    M_k,
                    mask_s0.cand_cnt,
                    mask_s0.cand_idx,
                    mask_s0.head_order,
                )
            torch.cuda.synchronize()
            kernel_ms = (time.perf_counter() - t0) * 1000.0 / 20.0

            def _make_meta_tensors(mc_v: int, mp_v: int, lk_v: int, mk_v: int):
                sh_v = 19 if "480p" in res_tag else 44
                res_cap_v = 512 if "480p" in res_tag else 1024
                k_cap_v = int(k.shape[0]) // BLOCK_SIZE
                mc_cap_v = max(M_cand, min(max(M_cand, k_cap_v), res_cap_v))
                m_full_src_v = max(0, (mc_v + M_q) - 1 - mc_v)
                m_full_s0_v = max(0, mk_v - 1 - mc_v)
                m_full_s1_v = max(0, (mk_v - sh_v) - 1 - (mc_v - sh_v))
                meta_t = torch.zeros(
                    (SPARSE_META_SIZE,), device=device, dtype=torch.int32
                )
                meta_t[:16] = torch.tensor(
                    [
                        mc_v,
                        mp_v,
                        lk_v - L_q,
                        mc_v + M_q,
                        m_full_src_v,
                        lk_v,
                        mk_v,
                        m_full_s0_v,
                        lk_v - sh_v * BLOCK_SIZE,
                        mk_v - sh_v,
                        mc_v - sh_v,
                        m_full_s1_v,
                        mp_v,
                        mp_v + sh_v,
                        sh_v,
                        mc_cap_v,
                    ],
                    device=device,
                    dtype=torch.int32,
                )
                kc_src = _compute_vectorized_k_cand_cpu(
                    "source_t0", "0.95", mc_v, mp_v, M_q, 1.0, head_start, H
                )[12].to(device)
                kc_s0 = _compute_vectorized_k_cand_cpu(
                    "target_t1000", "0.95", mc_v, mp_v, M_q, 1.0, head_start, H
                )[12].to(device)
                kc_s1 = _compute_vectorized_k_cand_cpu(
                    "target_t500",
                    "0.95",
                    mc_v - sh_v,
                    min(mp_v, mc_v - sh_v),
                    M_q,
                    1.0,
                    head_start,
                    H,
                )[12].to(device)
                mb_s0 = torch.tensor(
                    [lk_v, mc_v, mk_v, m_full_s0_v], device=device, dtype=torch.int32
                )
                return (
                    meta_t,
                    kc_src,
                    kc_src + m_full_src_v,
                    kc_s0,
                    kc_s0 + m_full_s0_v,
                    kc_s1,
                    kc_s1 + m_full_s1_v,
                    mb_s0,
                )

            mp_1 = 12 if "480p" in res_tag else 29
            (
                meta_g,
                kc_src_g,
                nf_src_g,
                kc_s0_g,
                nf_s0_g,
                kc_s1_g,
                nf_s1_g,
                mb_s0_g,
            ) = _make_meta_tensors(M_cand, mp_1, L_k, M_k)
            blk_kind_g = torch.full(
                (SPARSE_BLK_KIND_CAP,), KIND_WIN_FIN, device=device, dtype=torch.int32
            )
            blk_kind_g[:3] = KIND_TEXT
            blk_kind_g[3:mp_1] = KIND_REF_VIS
            blk_kind_g[mp_1 : min(M_cand, mp_1 + 38)] = KIND_SINK

            # Warmup before capture
            _, m_s0_w, _ = fused_route_and_build_masks(
                q_first=q0,
                q_second=q1,
                k=k,
                layer_idx=12,
                tau="0.95",
                L_q=L_q,
                M_q=M_q,
                M_cand=M_cand,
                M_prefix=mp_1,
                safety_scale=1.0,
                build_src=True,
                L_k_src=L_k - L_q,
                M_k_src=M_cand + M_q,
                M_cur_src=M_q,
                build_s0=True,
                L_k_s0=L_k,
                M_k_s0=M_k,
                M_cur_s0=M_cur,
                build_s1=True,
                s_evict=mp_1 * BLOCK_SIZE,
                L_k_s1=L_k
                - (19 * BLOCK_SIZE if "480p" in res_tag else 44 * BLOCK_SIZE),
                M_k_s1=M_k - (19 if "480p" in res_tag else 44),
                M_cand_s1=M_cand - (19 if "480p" in res_tag else 44),
                M_cur_s1=M_cur,
                head_start=head_start,
                num_heads=H,
                s1_parity=1,
                sparse_meta_gpu=meta_g,
                sparse_blk_kind_gpu=blk_kind_g,
                k_cand_src_gpu=kc_src_g,
                num_full_src_gpu=nf_src_g,
                k_cand_s0_gpu=kc_s0_g,
                num_full_s0_gpu=nf_s0_g,
                k_cand_s1_gpu=kc_s1_g,
                num_full_s1_gpu=nf_s1_g,
            )
            out_w = launch_zing_block_sparse_attn(
                q1,
                k,
                v,
                scale,
                L_k,
                M_cand,
                M_k,
                m_s0_w.cand_cnt,
                m_s0_w.cand_idx,
                m_s0_w.head_order,
                meta_branch_gpu=mb_s0_g,
            )
            torch.cuda.synchronize()

            g = torch.cuda.CUDAGraph()
            with torch.cuda.graph(g):
                _m_src_g, m_s0_g, _ = fused_route_and_build_masks(
                    q_first=q0,
                    q_second=q1,
                    k=k,
                    layer_idx=12,
                    tau="0.95",
                    L_q=L_q,
                    M_q=M_q,
                    M_cand=M_cand,
                    M_prefix=mp_1,
                    safety_scale=1.0,
                    build_src=True,
                    L_k_src=L_k - L_q,
                    M_k_src=M_cand + M_q,
                    M_cur_src=M_q,
                    build_s0=True,
                    L_k_s0=L_k,
                    M_k_s0=M_k,
                    M_cur_s0=M_cur,
                    build_s1=True,
                    s_evict=mp_1 * BLOCK_SIZE,
                    L_k_s1=L_k
                    - (19 * BLOCK_SIZE if "480p" in res_tag else 44 * BLOCK_SIZE),
                    M_k_s1=M_k - (19 if "480p" in res_tag else 44),
                    M_cand_s1=M_cand - (19 if "480p" in res_tag else 44),
                    M_cur_s1=M_cur,
                    head_start=head_start,
                    num_heads=H,
                    s1_parity=1,
                    sparse_meta_gpu=meta_g,
                    sparse_blk_kind_gpu=blk_kind_g,
                    k_cand_src_gpu=kc_src_g,
                    num_full_src_gpu=nf_src_g,
                    k_cand_s0_gpu=kc_s0_g,
                    num_full_s0_gpu=nf_s0_g,
                    k_cand_s1_gpu=kc_s1_g,
                    num_full_s1_gpu=nf_s1_g,
                )
                out_cg = launch_zing_block_sparse_attn(
                    q1,
                    k,
                    v,
                    scale,
                    L_k,
                    M_cand,
                    M_k,
                    m_s0_g.cand_cnt,
                    m_s0_g.cand_idx,
                    m_s0_g.head_order,
                    meta_branch_gpu=mb_s0_g,
                )
            g.replay()
            torch.cuda.synchronize()
            cg_err = float((out_cg - out_w).abs().max().item())

            # Now mutate sparse_meta_gpu & budgets in-place to a smaller dynamic (M_cand_2, M_prefix_2, L_k_2)
            # and replay the SAME CUDAGraph without recapturing!
            mc_2 = M_cand // 2
            mp_2 = mp_1 + 8
            mk_2 = mc_2 + M_cur
            lk_2 = L_k - (M_cand - mc_2) * BLOCK_SIZE
            (
                meta_2,
                kc_src_2,
                nf_src_2,
                kc_s0_2,
                nf_s0_2,
                kc_s1_2,
                nf_s1_2,
                mb_s0_2,
            ) = _make_meta_tensors(mc_2, mp_2, lk_2, mk_2)
            meta_g.copy_(meta_2)
            kc_src_g.copy_(kc_src_2)
            nf_src_g.copy_(nf_src_2)
            kc_s0_g.copy_(kc_s0_2)
            nf_s0_g.copy_(nf_s0_2)
            kc_s1_g.copy_(kc_s1_2)
            nf_s1_g.copy_(nf_s1_2)
            mb_s0_g.copy_(mb_s0_2)
            blk_kind_g.fill_(KIND_WIN_FIN)
            blk_kind_g[:3] = KIND_TEXT
            blk_kind_g[3:mp_2] = KIND_REF_VIS
            blk_kind_g[mp_2 : min(mc_2, mp_2 + 38)] = KIND_SINK

            g.replay()
            torch.cuda.synchronize()
            out_cg_dyn = out_cg.clone()

            # Compute eager reference at Config 2 (mc_2, mp_2, lk_2)
            _, m_s0_e2, _ = fused_route_and_build_masks(
                q_first=q0,
                q_second=q1,
                k=k,
                layer_idx=12,
                tau="0.95",
                L_q=L_q,
                M_q=M_q,
                M_cand=mc_2,
                M_prefix=mp_2,
                safety_scale=1.0,
                build_src=True,
                L_k_src=lk_2 - L_q,
                M_k_src=mc_2 + M_q,
                M_cur_src=M_q,
                build_s0=True,
                L_k_s0=lk_2,
                M_k_s0=mk_2,
                M_cur_s0=M_cur,
                build_s1=True,
                s_evict=mp_2 * BLOCK_SIZE,
                L_k_s1=lk_2
                - (19 * BLOCK_SIZE if "480p" in res_tag else 44 * BLOCK_SIZE),
                M_k_s1=mk_2 - (19 if "480p" in res_tag else 44),
                M_cand_s1=mc_2 - (19 if "480p" in res_tag else 44),
                M_cur_s1=M_cur,
                head_start=head_start,
                num_heads=H,
                s1_parity=1,
                sparse_meta_gpu=meta_2,
                sparse_blk_kind_gpu=blk_kind_g,
                k_cand_src_gpu=kc_src_2,
                num_full_src_gpu=nf_src_2,
                k_cand_s0_gpu=kc_s0_2,
                num_full_s0_gpu=nf_s0_2,
                k_cand_s1_gpu=kc_s1_2,
                num_full_s1_gpu=nf_s1_2,
            )
            out_eager_2 = launch_zing_block_sparse_attn(
                q1,
                k,
                v,
                scale,
                lk_2,
                mc_2,
                mk_2,
                m_s0_e2.cand_cnt,
                m_s0_e2.cand_idx,
                m_s0_e2.head_order,
                meta_branch_gpu=mb_s0_2,
            )
            cg_dyn_err = float((out_cg_dyn - out_eager_2).abs().max().item())
            assert cg_dyn_err == 0.0, (
                f"Dynamic CUDAGraph replay mismatch in {res_tag}: {cg_dyn_err}"
            )

        results[res_tag] = {
            "H": H,
            "L_q": L_q,
            "L_k": L_k,
            "M_cand": M_cand,
            "active_ratio": round(mask_s0.active_ratio, 4),
            "max_abs_err_vs_fp32_ref": round(max_err, 6),
            "triage_max_abs_err_vs_fp32_ref": round(triage_max_err, 6),
            "cudagraph_max_abs_err": round(cg_err, 6),
            "cudagraph_dynamic_switch_max_abs_err": round(cg_dyn_err, 6),
            "single_layer_router_ms": round(router_ms, 4),
            "single_layer_kernel_ms": round(kernel_ms, 4),
        }

    return results
